class ThermalDataSource(Enum):
    """Thermal data source types"""
    MODIS_TERRA = "modis_terra"
    MODIS_AQUA = "modis_aqua"
    VIIRS_NPP = "viirs_npp"
    VIIRS_NOAA20 = "viirs_noaa20"
    LANDSAT_8 = "landsat_8"
    LANDSAT_9 = "landsat_9"
    SENTINEL_2 = "sentinel_2"
    ASTER = "aster"
    GROUND_STATION = "ground_station"
    THERMAL_CAMERA = "thermal_camera"
    INFRARED_RADIOMETER = "infrared_radiometer"

class ThermalAnomalyType(Enum):
    """Thermal anomaly classification types"""
    VOLCANIC_HOTSPOT = "volcanic_hotspot"
    LAVA_FLOW = "lava_flow"
    FUMAROLE_FIELD = "fumarole_field"
    HYDROTHERMAL_AREA = "hydrothermal_area"
    PYROCLASTIC_FLOW = "pyroclastic_flow"
    DOME_GROWTH = "dome_growth"
    CRATER_HEATING = "crater_heating"
    FLANK_HEATING = "flank_heating"
    BACKGROUND_ANOMALY = "background_anomaly"
    FALSE_POSITIVE = "false_positive"

class HazardType(Enum):
    """Thermal hazard types"""
    LAVA_FLOW_HAZARD = "lava_flow_hazard"
    PYROCLASTIC_FLOW_HAZARD = "pyroclastic_flow_hazard"
    THERMAL_RADIATION_HAZARD = "thermal_radiation_hazard"
    GAS_EMISSION_HAZARD = "gas_emission_hazard"
    INFRASTRUCTURE_THREAT = "infrastructure_threat"
    AVIATION_HAZARD = "aviation_hazard"

@dataclass
class ThermalObservation:
    """Individual thermal observation data structure"""
    observation_id: str
    timestamp: datetime
    latitude: float
    longitude: float
    elevation: Optional[float]
    temperature_k: float  # Kelvin
    radiance: Optional[float]  # W/m²/sr/μm
    emissivity: Optional[float]
    pixel_size_m: Optional[float]
    data_source: ThermalDataSource
    satellite_zenith_angle: Optional[float]
    solar_zenith_angle: Optional[float]
    atmospheric_correction: bool = False
    cloud_mask: Optional[bool] = None
    quality_flags: List[str] = field(default_factory=list)
    uncertainty_k: Optional[float] = None
    metadata: Dict[str, Any] = field(default_factory=dict)

@dataclass
class ThermalAnomaly:
    """Detected thermal anomaly"""
    anomaly_id: str
    detection_timestamp: datetime
    centroid_lat: float
    centroid_lon: float
    area_m2: float
    max_temperature_k: float
    mean_temperature_k: float
    temperature_excess_k: float  # Above background
    radiant_flux_w: Optional[float]
    anomaly_type: ThermalAnomalyType
    confidence_score: float  # 0-1
    spatial_extent: Dict[str, Any]
    temporal_persistence: Optional[timedelta] = None
    growth_rate: Optional[float] = None  # m²/day
    intensity_trend: Optional[str] = None  # increasing, decreasing, stable
    associated_observations: List[str] = field(default_factory=list)
    validation_status: str = "pending"  # pending, confirmed, rejected
    metadata: Dict[str, Any] = field(default_factory=dict)

@dataclass
class SubsurfaceHeatModel:
    """Subsurface heat transfer model"""
    model_id: str
    grid_resolution_m: float
    depth_layers: List[float]  # meters
    thermal_conductivity: np.ndarray  # W/m/K
    heat_capacity: np.ndarray  # J/kg/K
    density: np.ndarray  # kg/m³
    heat_sources: np.ndarray  # W/m³
    boundary_conditions: Dict[str, Any]
    temperature_field: np.ndarray  # K
    heat_flux_field: np.ndarray  # W/m²
    model_timestamp: datetime
    convergence_criteria: Dict[str, float]
    uncertainty_bounds: Optional[np.ndarray] = None

@dataclass
class ThermalHazardAssessment:
    """Thermal hazard assessment results"""
    assessment_id: str
    volcano_id: str
    assessment_timestamp: datetime
    hazard_type: HazardType
    hazard_level: int  # 1-5 scale
    probability: float  # 0-1
    affected_area_km2: float
    population_at_risk: Optional[int]
    infrastructure_at_risk: List[str]
    time_to_impact: Optional[timedelta]
    mitigation_recommendations: List[str]
    uncertainty_factors: Dict[str, float]
    confidence_interval: Tuple[float, float]
    scenario_parameters: Dict[str, Any]
    evacuation_zones: Optional[Dict[str, Any]] = None

