    async def initialize_database_connections(self):
        """Initialize database connections for thermal data storage"""
        try:
            # PostgreSQL connection for spatial thermal data
            if 'postgresql' not in self.db_connections:
                self.db_connections['postgresql'] = await self._create_postgresql_connection()
            
            # InfluxDB connection for time series thermal data
            if 'influxdb' not in self.db_connections:
                self.db_connections['influxdb'] = await self._create_influxdb_connection()
            
            # Initialize thermal data tables
            await self._initialize_thermal_tables()
            
            self.logger.info("Database connections initialized successfully")
            
        except Exception as e:
            self.logger.error(f"Failed to initialize database connections: {e}")
            raise
    
    async def _create_postgresql_connection(self):
        """Create PostgreSQL connection for spatial data"""
        try:
            connection = psycopg2.connect(
                host=self.config.get('postgresql_host', 'localhost'),
                port=self.config.get('postgresql_port', 5432),
                database=self.config.get('postgresql_db', 'prometheus_thermal'),
                user=self.config.get('postgresql_user', 'prometheus'),
                password=self.config.get('postgresql_password', 'prometheus123'),
                cursor_factory=RealDictCursor
            )
            connection.autocommit = True
            return connection
        except Exception as e:
            self.logger.error(f"Failed to create PostgreSQL connection: {e}")
            raise
    
    async def _create_influxdb_connection(self):
        """Create InfluxDB connection for time series thermal data"""
        try:
            # Import InfluxDB client
            try:
                from influxdb_client.client.influxdb_client_async import InfluxDBClientAsync
                from influxdb_client import Point, WritePrecision
                INFLUXDB_AVAILABLE = True
            except ImportError:
                self.logger.warning("InfluxDB client not available, using fallback storage")
                return {'type': 'fallback_storage', 'data': {}}
            
            # InfluxDB configuration for thermal data
            influx_config = {
                'url': self.config.get('influxdb_url', 'http://localhost:8086'),
                'token': self.config.get('influxdb_token', 'prometheus_thermal_token'),
                'org': self.config.get('influxdb_org', 'prometheus_thermal'),
                'bucket': self.config.get('influxdb_bucket', 'thermal_observations')
            }
            
            # Create async InfluxDB client
            client = InfluxDBClientAsync(
                url=influx_config['url'],
                token=influx_config['token'],
                org=influx_config['org']
            )
            
            # Test connection
            health = await client.health()
            if health.status != "pass":
                raise ConnectionError(f"InfluxDB health check failed: {health.message}")
            
            # Create bucket if it doesn't exist
            buckets_api = client.buckets_api()
            try:
                bucket = await buckets_api.find_bucket_by_name(influx_config['bucket'])
                if not bucket:
                    org = await client.organizations_api().find_organizations(org=influx_config['org'])
                    if org:
                        await buckets_api.create_bucket(
                            bucket_name=influx_config['bucket'],
                            org_id=org[0].id,
                            retention_rules=[{"type": "expire", "everySeconds": 31536000}]  # 1 year retention
                        )
            except Exception as e:
                self.logger.warning(f"Could not create/verify InfluxDB bucket: {e}")
            
            return {
                'client': client,
                'config': influx_config,
                'write_api': client.write_api(),
                'query_api': client.query_api(),
                'type': 'influxdb'
            }
            
        except Exception as e:
            self.logger.error(f"Failed to create InfluxDB connection: {e}")
            # Return fallback storage
            return {'type': 'fallback_storage', 'data': {}}
    
