                {'name': 'Aleutian Trench', 'type': 'subduction', 'coords': [(51, -180), (66, -160)], 'activity': 1.0},
                {'name': 'Japan Trench', 'type': 'subduction', 'coords': [(30, 142), (46, 146)], 'activity': 1.0},
                {'name': 'Peru-Chile Trench', 'type': 'subduction', 'coords': [(-55, -75), (5, -70)], 'activity': 1.0},
                {'name': 'Cascadia Subduction', 'type': 'subduction', 'coords': [(40, -125), (49, -123)], 'activity': 0.9},
                {'name': 'Philippine Trench', 'type': 'subduction', 'coords': [(5, 126), (19, 127)], 'activity': 1.0},
                {'name': 'Java Trench', 'type': 'subduction', 'coords': [(-11, 104), (-6, 115)], 'activity': 1.0},
