    async def _analyze_seismic_volcanic_correlation(self, lat: float, lon: float, 
                                                  regional_volcanoes: List[Dict]) -> Dict[str, Any]:
        """Analyze correlation between seismic activity and volcanic activity"""
        try:
            # Query seismic data from database
            cursor = self.db_connections['postgresql'].cursor()
            
            cursor.execute("""
                SELECT 
                    sm.magnitude,
                    sm.depth_km,
                    sm.timestamp,
                    ST_Distance(
                        ST_GeogFromText('POINT(' || sm.longitude || ' ' || sm.latitude || ')'),
                        ST_GeogFromText('POINT(%s %s)')
                    ) / 1000.0 as distance_km
                FROM seismic_monitoring sm
                WHERE sm.timestamp > NOW() - INTERVAL '1 year'
                AND ST_DWithin(
                    ST_GeogFromText('POINT(' || sm.longitude || ' ' || sm.latitude || ')'),
                    ST_GeogFromText('POINT(%s %s)'),
                    100000
                )
                ORDER BY sm.timestamp DESC
                LIMIT 1000;
            """, (lon, lat, lon, lat))
            
            seismic_events = cursor.fetchall()
            
            if seismic_events and len(seismic_events) > 10:
                # Analyze seismic patterns
                magnitudes = [e['magnitude'] for e in seismic_events if e['magnitude']]
                depths = [e['depth_km'] for e in seismic_events if e['depth_km']]
                distances = [e['distance_km'] for e in seismic_events]
                
                # Calculate seismic statistics
                mean_magnitude = np.mean(magnitudes) if magnitudes else 0.0
                max_magnitude = np.max(magnitudes) if magnitudes else 0.0
                mean_depth = np.mean(depths) if depths else 0.0
                event_rate = len(seismic_events) / 365.0  # events per day
                
                # Analyze depth distribution (shallow events more relevant for volcanism)
                shallow_events = sum(1 for d in depths if d < 10.0)
                shallow_fraction = shallow_events / len(depths) if depths else 0.0
                
                # Calculate volcanic-seismic correlation score
                correlation_score = 0.0
                
                # Higher score for more frequent events
                correlation_score += min(0.3, event_rate / 10.0)
                
                # Higher score for shallow events
                correlation_score += shallow_fraction * 0.3
                
                # Higher score for moderate magnitudes (2-4 range typical for volcanic)
                if 2.0 <= mean_magnitude <= 4.0:
                    correlation_score += 0.2
                
                # Higher score if near active volcanoes
                active_volcanoes = sum(1 for v in regional_volcanoes 
                                     if v['current_alert_level'] and v['current_alert_level'] != 'green')
                if active_volcanoes > 0:
                    correlation_score += min(0.2, active_volcanoes * 0.05)
                
                return {
                    'correlation_score': min(1.0, correlation_score),
                    'seismic_event_count': len(seismic_events),
                    'mean_magnitude': mean_magnitude,
                    'max_magnitude': max_magnitude,
                    'mean_depth_km': mean_depth,
                    'shallow_event_fraction': shallow_fraction,
                    'event_rate_per_day': event_rate,
                    'data_source': 'seismic_database'
                }
            else:
                # Fallback to regional seismic models
                return await self._model_regional_seismicity(lat, lon, regional_volcanoes)
                
        except Exception as e:
            self.logger.error(f"Seismic-volcanic correlation analysis failed: {e}")
            return {
                'correlation_score': 0.5,
                'data_source': 'default'
            }
    
    async def _model_regional_seismicity(self, lat: float, lon: float, 
                                       regional_volcanoes: List[Dict]) -> Dict[str, Any]:
        """Model regional seismicity based on tectonic setting"""
        try:
            # Estimate seismicity based on tectonic setting
            if await self._is_near_active_margin(lat, lon):
                base_seismicity = 0.7
                event_rate = 5.0  # events per day
                mean_magnitude = 3.5
            elif len(regional_volcanoes) > 0:
                base_seismicity = 0.6
                event_rate = 2.0
                mean_magnitude = 2.8
            else:
                base_seismicity = 0.3
                event_rate = 0.5
                mean_magnitude = 2.0
            
            return {
                'correlation_score': base_seismicity,
                'estimated_event_rate_per_day': event_rate,
                'estimated_mean_magnitude': mean_magnitude,
                'data_source': 'tectonic_model'
            }
            
        except Exception as e:
            return {
                'correlation_score': 0.3,
                'data_source': 'default'
            }
    
    async def _analyze_regional_tectonics_fallback(self, lat_min: float, lat_max: float,
                                                  lon_min: float, lon_max: float,
                                                  regional_volcanoes: List[Dict]) -> List[Dict[str, Any]]:
        """Fallback regional tectonic analysis using global tectonic models"""
        try:
            center_lat = (lat_min + lat_max) / 2
            center_lon = (lon_min + lon_max) / 2
            
            # Determine tectonic setting from global models
            tectonic_setting = await self._classify_global_tectonic_setting(center_lat, center_lon)
            
            # Calculate volcanic potential
            volcanic_potential = await self._calculate_global_volcanic_potential(
                center_lat, center_lon, tectonic_setting, regional_volcanoes
            )
            
            # Estimate geophysical parameters
            crustal_stress = await self._estimate_global_crustal_stress(center_lat, center_lon, tectonic_setting)
            heat_flow = await self._estimate_global_heat_flow(center_lat, center_lon, tectonic_setting)
            
            # Create regional analysis
            regional_analysis = {
                'region_id': f"global_{center_lat:.1f}_{center_lon:.1f}",
                'center_lat': center_lat,
                'center_lon': center_lon,
                'tectonic_type': tectonic_setting,
                'volcanic_potential': volcanic_potential,
                'crustal_stress_mpa': crustal_stress,
                'stress_orientation_deg': await self._estimate_stress_orientation(center_lat, center_lon),
                'heat_flow_mw_m2': heat_flow,
                'seismic_correlation': await self._estimate_seismic_correlation(center_lat, center_lon),
                'confidence_level': 0.6,  # Lower confidence for global models
                'data_source': 'global_tectonic_model',
                'regional_volcanoes': len(regional_volcanoes),
                'predicted_volcano_type': await self._predict_volcano_type_from_tectonics(tectonic_setting),
                'magma_composition': await self._predict_magma_composition(tectonic_setting, {}),
                'eruption_style': await self._predict_eruption_style(tectonic_setting, {})
            }
            
            return [regional_analysis]
            
        except Exception as e:
            self.logger.error(f"Regional tectonic fallback analysis failed: {e}")
            return []
    
    async def _classify_global_tectonic_setting(self, lat: float, lon: float) -> str:
        """Classify tectonic setting using global tectonic models"""
        try:
            # Pacific Ring of Fire - Subduction zones
            if ((35 <= lat <= 70 and -180 <= lon <= -120) or  # Alaska/Kamchatka
                (10 <= lat <= 40 and 120 <= lon <= 150) or    # Japan/Philippines
                (-45 <= lat <= 10 and -80 <= lon <= -60) or   # Andes
                (35 <= lat <= 50 and -125 <= lon <= -110)):   # Cascades
                return 'subduction_zone'
            
            # Mid-ocean ridges
            elif ((60 <= lat <= 70 and -25 <= lon <= -10) or  # Iceland (Mid-Atlantic Ridge)
                  (-60 <= lat <= -45 and 130 <= lon <= 180) or # Antarctic Ridge
                  (-30 <= lat <= 30 and -40 <= lon <= -10)):   # Mid-Atlantic Ridge
                return 'rift_zone'
            
            # Hotspots
            elif ((15 <= lat <= 25 and -160 <= lon <= -150) or  # Hawaii
                  (-25 <= lat <= -15 and 160 <= lon <= 180) or  # Vanuatu
                  (-10 <= lat <= 10 and -95 <= lon <= -85)):    # Galapagos
                return 'hotspot'
            
            # Continental rifts
            elif ((35 <= lat <= 45 and 10 <= lon <= 20) or     # Italy (extensional)
                  (-20 <= lat <= 20 and 35 <= lon <= 45)):     # East African Rift
                return 'rift_zone'
            
            # Back-arc basins
            elif (10 <= lat <= 30 and 140 <= lon <= 160):      # Western Pacific
                return 'back_arc'
            
            # Transform faults
            elif (32 <= lat <= 42 and -125 <= lon <= -115):    # San Andreas system
                return 'transform_fault'
            
            else:
                return 'intraplate'
                
        except Exception as e:
            return 'intraplate'
    
    async def _calculate_global_volcanic_potential(self, lat: float, lon: float, 
                                                  tectonic_setting: str,
                                                  regional_volcanoes: List[Dict]) -> float:
        """Calculate volcanic potential using global volcanic database patterns"""
        try:
            # Base potential by tectonic setting
            base_potentials = {
                'subduction_zone': 0.80,
                'volcanic_arc': 0.75,
                'rift_zone': 0.65,
                'hotspot': 0.70,
                'back_arc': 0.60,
                'transform_fault': 0.35,
                'intraplate': 0.25
            }
            
            base_potential = base_potentials.get(tectonic_setting, 0.30)
            
            # Adjust for regional volcanic density
            if regional_volcanoes:
                # Higher potential if there are nearby volcanoes
                volcano_density_factor = min(1.5, 1.0 + len(regional_volcanoes) * 0.1)
                base_potential *= volcano_density_factor
                
                # Higher potential if volcanoes are recently active
                recent_activity = sum(1 for v in regional_volcanoes 
                                    if v.get('last_eruption_date') and 
                                    (datetime.utcnow() - v['last_eruption_date']).days < 3650)
                if recent_activity > 0:
                    activity_factor = min(1.3, 1.0 + recent_activity * 0.05)
                    base_potential *= activity_factor
            
            # Geographic modifiers based on known volcanic regions
            if await self._is_in_major_volcanic_province(lat, lon):
                base_potential *= 1.2
            
            return min(1.0, max(0.0, base_potential))
            
        except Exception as e:
            return 0.5
    
    async def _is_in_major_volcanic_province(self, lat: float, lon: float) -> bool:
        """Check if location is in a major volcanic province"""
        try:
            # Major volcanic provinces
            volcanic_provinces = [
                # Cascade Range
                {'lat_range': (40, 49), 'lon_range': (-125, -120)},
                # Andes
                {'lat_range': (-45, 10), 'lon_range': (-80, -65)},
                # Italian volcanoes
                {'lat_range': (37, 46), 'lon_range': (12, 16)},
                # Japanese arc
                {'lat_range': (30, 46), 'lon_range': (129, 146)},
                # Indonesian arc
                {'lat_range': (-11, 6), 'lon_range': (95, 141)},
                # Kamchatka
                {'lat_range': (50, 61), 'lon_range': (155, 165)},
                # Iceland
                {'lat_range': (63, 67), 'lon_range': (-25, -13)},
                # Hawaii
                {'lat_range': (18, 22), 'lon_range': (-161, -154)},
                # Galapagos
                {'lat_range': (-2, 2), 'lon_range': (-92, -89)}
            ]
            
            for province in volcanic_provinces:
                if (province['lat_range'][0] <= lat <= province['lat_range'][1] and
                    province['lon_range'][0] <= lon <= province['lon_range'][1]):
                    return True
            
            return False
            
        except Exception as e:
            return False
    
    async def _estimate_global_crustal_stress(self, lat: float, lon: float, tectonic_setting: str) -> float:
        """Estimate crustal stress using global stress models"""
        try:
            # Global stress models by tectonic setting
            stress_models = {
                'subduction_zone': 85.0,
                'rift_zone': 25.0,
                'transform_fault': 65.0,
                'hotspot': 40.0,
                'back_arc': 55.0,
                'intraplate': 35.0
            }
            
            base_stress = stress_models.get(tectonic_setting, 40.0)
            
            # Add global stress field variations
            # Based on World Stress Map patterns
            global_stress_variation = 15.0 * np.sin(np.radians(lat * 2)) * np.cos(np.radians(lon))
            
            final_stress = base_stress + global_stress_variation
            
            return max(15.0, min(120.0, final_stress))
            
        except Exception as e:
            return 50.0
    
    async def _estimate_global_heat_flow(self, lat: float, lon: float, tectonic_setting: str) -> float:
        """Estimate heat flow using global heat flow models"""
        try:
            # Global heat flow models by tectonic setting
            heat_flow_models = {
                'subduction_zone': 75.0,
                'rift_zone': 95.0,
                'hotspot': 110.0,
                'back_arc': 65.0,
                'transform_fault': 55.0,
                'intraplate': 45.0
            }
            
            base_heat_flow = heat_flow_models.get(tectonic_setting, 60.0)
            
            # Add global heat flow variations
            global_variation = 20.0 * np.sin(np.radians(lat)) * np.cos(np.radians(lon / 2))
            
            final_heat_flow = base_heat_flow + global_variation
            
            return max(25.0, min(150.0, final_heat_flow))
            
        except Exception as e:
            return 60.0
    
    async def _estimate_stress_orientation(self, lat: float, lon: float) -> float:
        """Estimate stress orientation based on global stress field models"""
        try:
            # Simplified global stress orientation model
            # Based on plate motion and regional stress patterns
            
            # Base orientation from latitude (approximates global stress patterns)
            base_orientation = (lat * 2.0) % 360
            
            # Add longitude-dependent variations
            longitude_variation = 30.0 * np.sin(np.radians(lon))
            
            final_orientation = (base_orientation + longitude_variation) % 360
            
            return final_orientation
            
        except Exception as e:
            return 0.0
    
    async def _estimate_seismic_correlation(self, lat: float, lon: float) -> Dict[str, Any]:
        """Estimate seismic-volcanic correlation using global seismicity models"""
        try:
            # Estimate based on tectonic setting
            if await self._is_near_active_margin(lat, lon):
                correlation_score = 0.7
                event_rate = 4.0
                mean_magnitude = 3.2
            elif await self._is_in_major_volcanic_province(lat, lon):
                correlation_score = 0.6
                event_rate = 2.5
                mean_magnitude = 2.8
            else:
                correlation_score = 0.3
                event_rate = 0.8
                mean_magnitude = 2.2
            
            return {
                'correlation_score': correlation_score,
                'estimated_event_rate_per_day': event_rate,
                'estimated_mean_magnitude': mean_magnitude,
                'data_source': 'global_seismicity_model'
            }
            
        except Exception as e:
            return {
                'correlation_score': 0.4,
                'data_source': 'default'
            }
    
    async def _estimate_activity_from_tectonics(self, tectonic_setting: str, volcanic_potential: float) -> str:
        """Estimate volcanic activity from tectonic setting"""
        try:
            if volcanic_potential > 0.7:
                return 'high'
            elif volcanic_potential > 0.5:
                return 'moderate'
            elif volcanic_potential > 0.3:
                return 'low'
            else:
                return 'dormant'
        except Exception as e:
            return 'unknown'
    
