    # Additional helper methods for submarine and ice-covered volcano monitoring
    
    async def _assess_hydroacoustic_quality(self, processed_signal: Dict[str, Any]) -> float:
        """Assess quality of hydroacoustic signal"""
        try:
            intensity = processed_signal.get('acoustic_intensity', 0)
            signal_type = processed_signal.get('signal_type', 'unknown')
            
            # Quality factors
            intensity_quality = min(1.0, intensity / 100.0)  # Normalize to 0-1
            
            type_quality = {
                'explosive_eruption': 0.9,
                'volcanic_tremor': 0.8,
                'pyroclastic_flow': 0.85,
                'degassing': 0.7,
                'unknown': 0.3
            }.get(signal_type, 0.5)
            
            # Processing quality (based on corrections applied)
            corrections_applied = sum([
                1 if processed_signal.get('depth_attenuation_factor', 1) != 1 else 0,
                1 if processed_signal.get('geometric_correction_factor', 1) != 1 else 0,
                1 if processed_signal.get('absorption_correction_factor', 1) != 1 else 0
            ])
            processing_quality = corrections_applied / 3.0
            
            overall_quality = (intensity_quality + type_quality + processing_quality) / 3.0
            
            return max(0.0, min(1.0, overall_quality))
            
        except Exception as e:
            return 0.5
    
    async def _analyze_hydroacoustic_temporal_patterns(self, processed_signals: List[Dict[str, Any]]) -> Dict[str, Any]:
        """Analyze temporal patterns in hydroacoustic signals"""
        try:
            if len(processed_signals) < 2:
                return {'pattern_type': 'insufficient_data', 'confidence': 0.0}
            
            # Extract time series data
            timestamps = [signal['timestamp'] for signal in processed_signals]
            intensities = [signal['processed_signal'].get('acoustic_intensity', 0) for signal in processed_signals]
            eruption_probs = [signal.get('eruption_probability', 0) for signal in processed_signals]
            
            # Sort by timestamp
            sorted_data = sorted(zip(timestamps, intensities, eruption_probs))
            timestamps, intensities, eruption_probs = zip(*sorted_data)
            
            # Calculate temporal statistics
            time_diffs = [(timestamps[i+1] - timestamps[i]).total_seconds() for i in range(len(timestamps)-1)]
            avg_interval_s = np.mean(time_diffs) if time_diffs else 0
            
            # Detect patterns
            patterns = {}
            
            # Increasing trend
            if len(intensities) >= 3:
                intensity_trend = np.polyfit(range(len(intensities)), intensities, 1)[0]
                prob_trend = np.polyfit(range(len(eruption_probs)), eruption_probs, 1)[0]
                
                patterns['intensity_trend'] = {
                    'slope': intensity_trend,
                    'direction': 'increasing' if intensity_trend > 0 else 'decreasing',
                    'significance': abs(intensity_trend) / max(intensities) if max(intensities) > 0 else 0
                }
                
                patterns['probability_trend'] = {
                    'slope': prob_trend,
                    'direction': 'increasing' if prob_trend > 0 else 'decreasing',
                    'significance': abs(prob_trend)
                }
            
            # Periodicity detection (simplified)
            if len(intensities) >= 5:
                # Use autocorrelation to detect periodicity
                autocorr = np.correlate(intensities, intensities, mode='full')
                autocorr = autocorr[autocorr.size // 2:]
                
                # Find peaks in autocorrelation
                if len(autocorr) > 3:
                    peak_indices = []
                    for i in range(1, len(autocorr) - 1):
                        if autocorr[i] > autocorr[i-1] and autocorr[i] > autocorr[i+1]:
                            peak_indices.append(i)
                    
                    if peak_indices:
                        dominant_period_samples = peak_indices[0] if peak_indices else 0
                        dominant_period_s = dominant_period_samples * avg_interval_s
                        
                        patterns['periodicity'] = {
                            'detected': True,
                            'period_s': dominant_period_s,
                            'period_hours': dominant_period_s / 3600.0,
                            'strength': autocorr[dominant_period_samples] / autocorr[0] if autocorr[0] > 0 else 0
                        }
                    else:
                        patterns['periodicity'] = {'detected': False}
            
            # Overall pattern classification
            if patterns.get('intensity_trend', {}).get('direction') == 'increasing':
                if patterns.get('probability_trend', {}).get('direction') == 'increasing':
                    pattern_type = 'escalating_activity'
                    confidence = 0.8
                else:
                    pattern_type = 'increasing_intensity'
                    confidence = 0.6
            elif patterns.get('periodicity', {}).get('detected'):
                pattern_type = 'periodic_activity'
                confidence = patterns['periodicity'].get('strength', 0.5)
            else:
                pattern_type = 'irregular_activity'
                confidence = 0.4
            
            return {
                'pattern_type': pattern_type,
                'confidence': confidence,
                'patterns': patterns,
                'temporal_statistics': {
                    'signal_count': len(processed_signals),
                    'time_span_hours': (timestamps[-1] - timestamps[0]).total_seconds() / 3600.0,
                    'average_interval_s': avg_interval_s,
                    'average_intensity': np.mean(intensities),
                    'max_intensity': max(intensities),
                    'average_eruption_probability': np.mean(eruption_probs)
                }
            }
            
        except Exception as e:
            self.logger.error(f"Temporal pattern analysis failed: {e}")
            return {'pattern_type': 'analysis_error', 'confidence': 0.0}
    
    async def _calculate_detection_confidence(self, processed_signals: List[Dict[str, Any]]) -> float:
        """Calculate overall detection confidence"""
        try:
            if not processed_signals:
                return 0.0
            
            # Individual signal confidences
            signal_confidences = []
            for signal in processed_signals:
                volcanic_signature = signal.get('volcanic_signature', {})
                eruption_prob = signal.get('eruption_probability', 0)
                signal_quality = signal.get('signal_quality', 0.5)
                
                # Combine signature confidences
                signature_conf = 0.0
                signature_count = 0
                
                for sig_type, sig_data in volcanic_signature.items():
                    if isinstance(sig_data, dict) and 'confidence' in sig_data:
                        signature_conf += sig_data['confidence']
                        signature_count += 1
                
                avg_signature_conf = signature_conf / signature_count if signature_count > 0 else 0
                
                # Combined confidence for this signal
                signal_conf = (avg_signature_conf + eruption_prob + signal_quality) / 3.0
                signal_confidences.append(signal_conf)
            
            # Overall confidence (weighted by signal count)
            base_confidence = np.mean(signal_confidences)
            
            # Boost confidence with more signals
            signal_count_factor = min(1.0, len(processed_signals) / 10.0)  # Max boost at 10 signals
            
            overall_confidence = base_confidence * (0.7 + 0.3 * signal_count_factor)
            
            return max(0.0, min(1.0, overall_confidence))
            
        except Exception as e:
            return 0.0
    
    async def _generate_submarine_monitoring_recommendations(self, processed_signals: List[Dict[str, Any]]) -> List[str]:
        """Generate monitoring recommendations based on hydroacoustic analysis"""
        try:
            recommendations = []
            
            if not processed_signals:
                return ["Insufficient data for recommendations"]
            
            # Analyze signal characteristics
            max_eruption_prob = max([s.get('eruption_probability', 0) for s in processed_signals])
            avg_intensity = np.mean([s['processed_signal'].get('acoustic_intensity', 0) for s in processed_signals])
            
            # High eruption probability recommendations
            if max_eruption_prob > 0.7:
                recommendations.extend([
                    "Deploy additional hydroacoustic sensors in the area",
                    "Increase monitoring frequency to continuous",
                    "Coordinate with tsunami warning centers",
                    "Prepare submarine ROV deployment for visual confirmation"
                ])
            elif max_eruption_prob > 0.4:
                recommendations.extend([
                    "Increase hydroacoustic monitoring frequency",
                    "Cross-correlate with seismic monitoring networks",
                    "Monitor for changes in water column temperature"
                ])
            
            # High intensity recommendations
            if avg_intensity > 100:
                recommendations.extend([
                    "Verify sensor calibration and positioning",
                    "Check for potential interference sources",
                    "Consider deploying backup monitoring systems"
                ])
            
            # Pattern-based recommendations
            temporal_analysis = await self._analyze_hydroacoustic_temporal_patterns(processed_signals)
            pattern_type = temporal_analysis.get('pattern_type', 'unknown')
            
            if pattern_type == 'escalating_activity':
                recommendations.append("Alert: Escalating volcanic activity detected - consider raising alert level")
            elif pattern_type == 'periodic_activity':
                recommendations.append("Monitor for changes in periodic pattern - may indicate evolving magma system")
            
            # General recommendations
            recommendations.extend([
                "Maintain continuous data archival for retrospective analysis",
                "Coordinate with regional volcano observatories",
                "Prepare contingency plans for submarine eruption scenarios"
            ])
            
            return list(set(recommendations))  # Remove duplicates
            
        except Exception as e:
            return ["Error generating recommendations - manual review required"]
    
    async def _estimate_ice_volume(self, volcano_location: Tuple[float, float], ice_thickness_m: float) -> float:
        """Estimate total ice volume around volcano"""
        try:
            # Estimate affected ice area based on volcano size and thermal output
            # This is a simplified model - in reality would use detailed glaciological data
            
            lat, lon = volcano_location
            
            # Base affected area (depends on latitude - more ice at higher latitudes)
            if abs(lat) > 60:  # Polar regions
                base_area_km2 = 50.0
            elif abs(lat) > 45:  # Subpolar regions
                base_area_km2 = 20.0
            else:  # Lower latitudes (high altitude glaciers)
                base_area_km2 = 5.0
            
            # Adjust for ice thickness (thicker ice suggests larger glacier)
            thickness_factor = ice_thickness_m / 100.0  # Normalize by 100m
            adjusted_area_km2 = base_area_km2 * thickness_factor
            
            # Convert to volume
            ice_volume_m3 = adjusted_area_km2 * 1e6 * ice_thickness_m  # km² to m², times thickness
            
            return ice_volume_m3
            
        except Exception as e:
            return ice_thickness_m * 1e6  # Default: 1 km² area
    
    async def _identify_dominant_subglacial_processes(self, phases: List[Dict[str, Any]]) -> List[str]:
        """Identify dominant processes in subglacial eruption"""
        try:
            processes = []
            
            for phase in phases:
                phase_type = phase.get('phase', 'unknown')
                duration = phase.get('duration_s', 0)
                
                if phase_type == 'initial_contact' and duration > 1800:  # > 30 min
                    processes.append('sustained_steam_generation')
                
                if phase_type == 'pillow_formation':
                    processes.append('subaqueous_lava_emplacement')
                
                if phase_type == 'cavity_formation':
                    cavity_volume = phase.get('cavity_volume_m3', 0)
                    if cavity_volume > 50000:  # > 50,000 m³
                        processes.append('large_scale_ice_melting')
                
                if phase_type == 'breakthrough':
                    explosion_energy = phase.get('explosion_energy_j', 0)
                    if explosion_energy > 1e12:  # > 1 TJ
                        processes.append('explosive_ice_breakthrough')
            
            if not processes:
                processes = ['gradual_ice_melting']
            
            return processes
            
        except Exception as e:
            return ['unknown_processes']
    
    async def _extract_subglacial_hazard_indicators(self, phases: List[Dict[str, Any]]) -> Dict[str, Any]:
        """Extract hazard indicators from subglacial eruption phases"""
        try:
            indicators = {
                'steam_pressure_buildup': False,
                'rapid_ice_melting': False,
                'explosive_potential': False,
                'flood_risk': False
            }
            
            for phase in phases:
                phase_type = phase.get('phase', 'unknown')
                
                if phase_type == 'initial_contact':
                    steam_rate = phase.get('steam_rate_kg_s', 0)
                    if steam_rate > 100:  # High steam generation
                        indicators['steam_pressure_buildup'] = True
                
                if phase_type == 'cavity_formation':
                    formation_time = phase.get('duration_s', 0)
                    if formation_time < 3600:  # Rapid cavity formation
                        indicators['rapid_ice_melting'] = True
                    
                    meltwater_volume = phase.get('cavity_volume_m3', 0) * 0.8
                    if meltwater_volume > 10000:  # Significant meltwater
                        indicators['flood_risk'] = True
                
                if phase_type == 'breakthrough':
                    explosion_energy = phase.get('explosion_energy_j', 0)
                    if explosion_energy > 1e11:  # Significant explosion potential
                        indicators['explosive_potential'] = True
            
            return indicators
            
        except Exception as e:
            return {
                'steam_pressure_buildup': False,
                'rapid_ice_melting': False,
                'explosive_potential': False,
                'flood_risk': False
            }
    
    async def _calculate_ice_volcano_thermal_evolution(self, 
                                                     ice_thickness_m: float, 
                                                     magma_temperature_k: float, 
                                                     eruption_rate_m3_s: float) -> Dict[str, Any]:
        """Calculate thermal evolution during ice-volcano interaction"""
        try:
            # Time steps for thermal evolution
            time_steps_s = np.arange(0, 86400, 3600)  # 24 hours, hourly steps
            
            # Initialize arrays
            ice_temperature_evolution = []
            magma_temperature_evolution = []
            meltwater_temperature_evolution = []
            heat_flux_evolution = []
            
            for t in time_steps_s:
                # Magma cooling
                cooling_rate_k_s = 0.01  # 0.01 K/s cooling rate
                current_magma_temp = max(273.15, magma_temperature_k - cooling_rate_k_s * t)
                
                # Ice heating (simplified)
                ice_heating_rate_k_s = 0.001  # Slow ice heating
                initial_ice_temp = 253.15  # -20°C
                current_ice_temp = min(273.15, initial_ice_temp + ice_heating_rate_k_s * t)
                
                # Meltwater temperature (between ice and magma)
                if current_ice_temp >= 273.15:  # Ice has melted
                    meltwater_temp = 273.15 + (current_magma_temp - 273.15) * 0.1  # 10% of excess heat
                else:
                    meltwater_temp = 273.15  # At melting point
                
                # Heat flux (decreases as temperature difference decreases)
                temp_diff = current_magma_temp - current_ice_temp
                heat_flux = eruption_rate_m3_s * 2500 * 1200 * temp_diff  # Simplified heat flux
                
                ice_temperature_evolution.append(current_ice_temp)
                magma_temperature_evolution.append(current_magma_temp)
                meltwater_temperature_evolution.append(meltwater_temp)
                heat_flux_evolution.append(heat_flux)
            
            return {
                'time_steps_s': time_steps_s.tolist(),
                'ice_temperature_k': ice_temperature_evolution,
                'magma_temperature_k': magma_temperature_evolution,
                'meltwater_temperature_k': meltwater_temperature_evolution,
                'heat_flux_w': heat_flux_evolution,
                'thermal_equilibrium_time_s': float(np.argmin(np.abs(np.array(heat_flux_evolution) - heat_flux_evolution[0] * 0.1)) * 3600),
                'maximum_meltwater_temperature_k': max(meltwater_temperature_evolution),
                'total_heat_transferred_j': float(np.trapz(heat_flux_evolution, time_steps_s))
            }
            
        except Exception as e:
            self.logger.error(f"Thermal evolution calculation failed: {e}")
            return {
                'time_steps_s': [0, 3600, 7200],
                'ice_temperature_k': [253.15, 263.15, 273.15],
                'magma_temperature_k': [magma_temperature_k, magma_temperature_k - 100, magma_temperature_k - 200],
                'meltwater_temperature_k': [273.15, 283.15, 293.15],
                'heat_flux_w': [1e6, 5e5, 1e5],
                'thermal_equilibrium_time_s': 7200.0,
                'maximum_meltwater_temperature_k': 293.15,
                'total_heat_transferred_j': 1e12
            }
    
    async def _assess_ice_volcano_hazards(self, 
                                        volcano_location: Tuple[float, float],
                                        ice_melting: Dict[str, Any], 
                                        flood_prediction: Dict[str, Any], 
                                        thermal_evolution: Dict[str, Any]) -> Dict[str, Any]:
        """Assess hazards from ice-volcano interactions"""
        try:
            hazards = {}
            
            # Glacial outburst flood hazard
            if flood_prediction.get('flood_likely', False):
                peak_discharge = flood_prediction.get('peak_discharge_m3_s', 0)
                
                if peak_discharge > 1000:
                    flood_hazard_level = 'extreme'
                elif peak_discharge > 500:
                    flood_hazard_level = 'high'
                elif peak_discharge > 100:
                    flood_hazard_level = 'moderate'
                else:
                    flood_hazard_level = 'low'
                
                hazards['glacial_outburst_flood'] = {
                    'hazard_level': flood_hazard_level,
                    'peak_discharge_m3_s': peak_discharge,
                    'warning_time_hours': flood_prediction.get('warning_time_hours', 0),
                    'affected_areas': flood_prediction.get('impact_assessment', {}).get('affected_areas', [])
                }
            
            # Steam explosion hazard
            melting_rate = ice_melting.get('ice_melting_rate_m3_s', 0)
            if melting_rate > 10:  # Rapid melting
                hazards['steam_explosion'] = {
                    'hazard_level': 'high',
                    'explosion_radius_m': min(5000, melting_rate * 100),
                    'steam_pressure_buildup': True
                }
            elif melting_rate > 1:
                hazards['steam_explosion'] = {
                    'hazard_level': 'moderate',
                    'explosion_radius_m': min(2000, melting_rate * 100),
                    'steam_pressure_buildup': False
                }
            
            # Thermal hazard
            max_meltwater_temp = thermal_evolution.get('maximum_meltwater_temperature_k', 273.15)
            if max_meltwater_temp > 373.15:  # Above boiling
                hazards['thermal'] = {
                    'hazard_level': 'high',
                    'maximum_temperature_k': max_meltwater_temp,
                    'scalding_risk': True
                }
            
            # Structural hazard (ice collapse)
            breakthrough_time = ice_melting.get('time_to_breakthrough_hours', float('inf'))
            if breakthrough_time < 24:  # Rapid breakthrough
                hazards['structural_collapse'] = {
                    'hazard_level': 'high',
                    'collapse_time_hours': breakthrough_time,
                    'debris_flow_risk': True
                }
            
            return hazards
            
        except Exception as e:
            self.logger.error(f"Ice-volcano hazard assessment failed: {e}")
            return {}
    
