    async def _estimate_seamount_density(self, lat: float, lon: float) -> float:
        """Estimate seamount density in region"""
        try:
            # Seamount density varies with tectonic setting
            ridge_distance = await self._calculate_distance_to_ridge_advanced(lat, lon)
            hotspot_distance = await self._calculate_distance_to_hotspot(lat, lon)
            
            # Higher density near ridges and hotspots
            ridge_factor = max(0, 1.0 - ridge_distance / 500.0)
            hotspot_factor = max(0, 1.0 - hotspot_distance / 1000.0)
            
            density = 0.1 * (ridge_factor + hotspot_factor)
            
            return min(1.0, density)
            
        except Exception as e:
            return 0.1
    
