    async def _calculate_ice_temperature_profile(self, ice_thickness_m: float) -> List[float]:
        """Calculate temperature profile through ice using heat conduction"""
        try:
            # Surface and basal temperatures
            surface_temp_k = 253.15  # -20°C typical surface
            basal_temp_k = 273.15    # 0°C at base (pressure melting point)
            
            # Geothermal heat flux
            geothermal_flux = 0.06  # W/m² typical continental
            
            # Ice thermal conductivity
            k_ice = 2.1  # W/m/K
            
            # Depth points
            depths = np.linspace(0, ice_thickness_m, 20)
            temperatures = []
            
            for depth in depths:
                # Linear temperature gradient with geothermal correction
                if ice_thickness_m > 0:
                    # Basic linear profile
                    temp_linear = surface_temp_k + (basal_temp_k - surface_temp_k) * (depth / ice_thickness_m)
                    
                    # Geothermal correction (small effect)
                    geothermal_correction = (geothermal_flux * depth) / k_ice
                    
                    temp_corrected = temp_linear + geothermal_correction
                    temperatures.append(min(273.15, temp_corrected))
                else:
                    temperatures.append(surface_temp_k)
            
            return temperatures
            
        except Exception as e:
            return [253.15] * 20  # Default cold ice
    
    async def _calculate_liquidus_temperature(self, magma_temperature_k: float) -> float:
        """Calculate liquidus temperature for magma composition"""
        try:
            # For basaltic composition (simplified)
            # Liquidus temperature depends on pressure and composition
            
            # Base liquidus for basalt at 1 atm
            base_liquidus = 1473.15  # ~1200°C
            
            # Pressure effect (assuming some depth)
            pressure_effect = 50.0  # K increase per km depth
            assumed_depth_km = 5.0  # Typical magma chamber depth
            
            liquidus_temp = base_liquidus + pressure_effect * assumed_depth_km
            
            return min(magma_temperature_k, liquidus_temp)
            
        except Exception as e:
            return 1473.15
    
    async def _calculate_magma_gas_properties(self, magma_temperature_k: float) -> Dict[str, Any]:
        """Calculate magma gas content and properties"""
        try:
            # Gas solubility in basaltic melt (simplified)
            # Based on pressure and temperature
            
            # Assume shallow magma chamber (5 km depth)
            pressure_mpa = 150.0  # ~5 km depth
            
            # H2O solubility (Liu et al., 2005)
            h2o_solubility_wt = 0.4 + 0.001 * (magma_temperature_k - 1473.15)
            
            # CO2 solubility (much lower)
            co2_solubility_ppm = 100 + 0.1 * (magma_temperature_k - 1473.15)
            
            # SO2 solubility
            so2_solubility_ppm = 1000 + 0.5 * (magma_temperature_k - 1473.15)
            
            return {
                'h2o_content_wt_percent': max(0.1, min(6.0, h2o_solubility_wt)),
                'co2_content_ppm': max(50, min(1000, co2_solubility_ppm)),
                'so2_content_ppm': max(500, min(5000, so2_solubility_ppm)),
                'total_volatiles_wt_percent': h2o_solubility_wt + co2_solubility_ppm/10000 + so2_solubility_ppm/10000
            }
            
        except Exception as e:
            return {
                'h2o_content_wt_percent': 2.0,
                'co2_content_ppm': 200,
                'so2_content_ppm': 1500,
                'total_volatiles_wt_percent': 2.2
            }
    
