    async def _calculate_jeffreys_flow_distance(self, eruption_rate: float, 
                                              lava_properties: Dict[str, Any],
                                              terrain_params: Dict[str, Any]) -> float:
        """Calculate lava flow distance using Jeffreys equation for viscous flow"""
        try:
            # Jeffreys (1925) equation for viscous flow on an inclined plane
            # L = (3 * Q * μ / (ρ * g * sin(θ) * w * h²))^(1/3) * t^(1/3)
            
            viscosity = lava_properties['viscosity_pa_s']  # Pa·s
            density = lava_properties['density_kg_m3']  # kg/m³
            g = 9.81  # m/s²
            
            # Terrain parameters
            slope_deg = terrain_params.get('slope', 10.0)  # degrees
            slope_rad = np.radians(slope_deg)
            
            # Flow geometry assumptions
            flow_width = 50.0  # m (typical lava flow width)
            flow_thickness = 2.0  # m (typical lava flow thickness)
            
            # Flow time (assume steady flow for 24 hours)
            flow_time = 24 * 3600  # seconds
            
            # Jeffreys equation
            if np.sin(slope_rad) > 0:
                distance = ((3 * eruption_rate * viscosity) / 
                           (density * g * np.sin(slope_rad) * flow_width * flow_thickness**2))**(1/3) * flow_time**(1/3)
            else:
                # Flat terrain - use modified equation
                distance = ((eruption_rate * viscosity) / 
                           (density * g * 0.01 * flow_width * flow_thickness**2))**(1/3) * flow_time**(1/3)
            
            return max(100, min(50000, distance))  # Realistic bounds: 100m to 50km
            
        except Exception as e:
            self.logger.error(f"Jeffreys flow distance calculation failed: {e}")
            return 1000.0  # Default 1km
    
    async def _calculate_empirical_flow_distance(self, eruption_rate: float,
                                               lava_properties: Dict[str, Any],
                                               terrain_params: Dict[str, Any]) -> float:
        """Calculate lava flow distance using empirical relationships"""
        try:
            # Malin (1980) empirical relationship: L = k * V^n
            # Where L is flow length, V is volume, k and n are empirical constants
            
            # Estimate total volume (eruption rate * duration)
            duration_hours = 24  # Assume 24-hour eruption
            total_volume = eruption_rate * duration_hours * 3600  # m³
            
            # Empirical constants based on lava composition
            composition = lava_properties.get('composition', 'andesitic')
            
            if composition == 'basaltic':
                k = 2.5  # Empirical constant for basaltic flows
                n = 0.6  # Empirical exponent
            elif composition == 'andesitic':
                k = 1.8  # Empirical constant for andesitic flows
                n = 0.55  # Empirical exponent
            else:  # rhyolitic
                k = 1.2  # Empirical constant for rhyolitic flows
                n = 0.5  # Empirical exponent
            
            # Apply slope correction
            slope_deg = terrain_params.get('slope', 10.0)
            slope_factor = 1.0 + 0.1 * slope_deg  # Steeper slopes increase flow distance
            
            # Calculate flow distance
            distance = k * (total_volume ** n) * slope_factor
            
            return max(100, min(50000, distance))  # Realistic bounds
            
        except Exception as e:
            self.logger.error(f"Empirical flow distance calculation failed: {e}")
            return 2000.0  # Default 2km
    
    async def _calculate_flowgo_distance(self, eruption_rate: float,
                                       lava_properties: Dict[str, Any],
                                       terrain_params: Dict[str, Any],
                                       anomaly: ThermalAnomaly) -> float:
        """Calculate lava flow distance using FLOWGO model approximation"""
        try:
            # Simplified FLOWGO model (Harris & Rowland, 2001)
            # Accounts for cooling and crystallization during flow
            
            initial_temp = lava_properties['temperature_k']  # K
            solidification_temp = initial_temp - 200  # K (typical cooling)
            ambient_temp = 288.15  # K
            
            # Thermal properties
            specific_heat = lava_properties['specific_heat_j_kg_k']  # J/kg/K
            density = lava_properties['density_kg_m3']  # kg/m³
            thermal_conductivity = lava_properties['thermal_conductivity_w_m_k']  # W/m/K
            
            # Flow geometry
            flow_width = 50.0  # m
            flow_thickness = 2.0  # m
            
            # Heat loss rate (simplified)
            surface_area_per_length = flow_width + 2 * flow_thickness  # m²/m
            heat_loss_rate = (thermal_conductivity * surface_area_per_length * 
                             (initial_temp - ambient_temp) / flow_thickness)  # W/m
            
            # Heat content per unit length
            heat_content_per_length = (density * flow_width * flow_thickness * specific_heat * 
                                     (initial_temp - solidification_temp))  # J/m
            
            # Flow velocity
            velocity = lava_properties['velocity_m_s']  # m/s
            
            # Distance calculation based on cooling time
            if heat_loss_rate > 0:
                cooling_time = heat_content_per_length / heat_loss_rate  # seconds
                distance = velocity * cooling_time  # meters
            else:
                distance = 5000.0  # Default if calculation fails
            
            # Apply terrain corrections
            slope_deg = terrain_params.get('slope', 10.0)
            if slope_deg > 20:
                distance *= 1.5  # Steep slopes increase flow distance
            elif slope_deg < 5:
                distance *= 0.7  # Gentle slopes decrease flow distance
            
            return max(100, min(50000, distance))  # Realistic bounds
            
        except Exception as e:
            self.logger.error(f"FLOWGO distance calculation failed: {e}")
            return 3000.0  # Default 3km
    
    async def _store_hazard_assessments_db(self, assessments: List[ThermalHazardAssessment]):
        """Store hazard assessments in database using real schema"""
        try:
            cursor = self.db_connections['postgresql'].cursor()
            
            for assessment in assessments:
                cursor.execute("""
                    INSERT INTO thermal_hazard_assessments (
                        assessment_id, volcano_id, assessment_timestamp, hazard_type,
                        hazard_level, probability, affected_area_km2, population_at_risk,
                        infrastructure_at_risk, time_to_impact, mitigation_recommendations,
                        uncertainty_factors, confidence_interval, scenario_parameters,
                        evacuation_zones
                    ) VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s)
                    ON CONFLICT (assessment_id) DO UPDATE SET
                        hazard_level = EXCLUDED.hazard_level,
                        probability = EXCLUDED.probability,
                        affected_area_km2 = EXCLUDED.affected_area_km2,
                        population_at_risk = EXCLUDED.population_at_risk,
                        uncertainty_factors = EXCLUDED.uncertainty_factors,
                        confidence_interval = EXCLUDED.confidence_interval
                """, (
                    assessment.assessment_id,
                    assessment.volcano_id,
                    assessment.assessment_timestamp,
                    assessment.hazard_type.value,
                    assessment.hazard_level,
                    assessment.probability,
                    assessment.affected_area_km2,
                    assessment.population_at_risk,
                    assessment.infrastructure_at_risk,
                    assessment.time_to_impact,
                    assessment.mitigation_recommendations,
                    json.dumps(assessment.uncertainty_factors),
                    list(assessment.confidence_interval),
                    json.dumps(assessment.scenario_parameters),
                    json.dumps(assessment.evacuation_zones) if assessment.evacuation_zones else '{}'
                ))
            
            self.logger.info(f"Stored {len(assessments)} hazard assessments in database")
            
        except Exception as e:
            self.logger.error(f"Failed to store hazard assessments: {e}")
    
    async def _calculate_advanced_atmospheric_temperature(self, lat: float, lon: float, 
                                                        elevation: float, timestamp: datetime) -> float:
        """Calculate advanced atmospheric temperature using comprehensive models"""
        try:
            # Base temperature from standard atmosphere
            base_temp = 288.15 - 0.0065 * elevation
            
            # Seasonal variation with latitude dependence
            day_of_year = timestamp.timetuple().tm_yday
            seasonal_amplitude = 20.0 * np.cos(np.radians(lat))  # Larger at higher latitudes
            seasonal_phase = 2 * np.pi * (day_of_year - 80) / 365.25
            seasonal_temp = seasonal_amplitude * np.cos(seasonal_phase)
            
            # Diurnal variation
            hour = timestamp.hour
            diurnal_amplitude = 8.0 * np.exp(-elevation / 3000.0)  # Decreases with elevation
            diurnal_phase = 2 * np.pi * (hour - 14) / 24.0
            diurnal_temp = diurnal_amplitude * np.cos(diurnal_phase)
            
            # Continental vs maritime effects
            if await self._is_coastal_location(lat, lon):
                maritime_moderation = -2.0  # Oceans moderate temperature
            else:
                maritime_moderation = 3.0   # Continental extremes
            
            # Elevation lapse rate correction for local topography
            local_lapse_correction = await self._calculate_local_lapse_rate_correction(lat, lon, elevation)
            
            final_temp = (base_temp + seasonal_temp + diurnal_temp + 
                         maritime_moderation + local_lapse_correction)
            
            return max(200.0, min(330.0, final_temp))
            
        except Exception as e:
            return 288.15 - 0.0065 * elevation
    
    async def _calculate_surface_energy_balance(self, lat: float, lon: float, elevation: float,
                                              atmospheric_temp: float, timestamp: datetime) -> float:
        """Calculate surface temperature using energy balance principles"""
        try:
            # Solar radiation input
            solar_input = await self._calculate_solar_radiation_input(lat, timestamp)
            
            # Surface albedo
            albedo = await self._estimate_surface_albedo(lat, lon)
            
            # Net solar radiation
            net_solar = solar_input * (1 - albedo)
            
            # Longwave radiation exchange
            longwave_down = 5.67e-8 * atmospheric_temp**4  # Stefan-Boltzmann
            
            # Surface heat capacity effects
            surface_heat_capacity = await self._estimate_surface_heat_capacity(lat, lon)
            
            # Energy balance equation (simplified)
            # Net radiation = Solar - Longwave_up + Longwave_down - Sensible - Latent
            
            # Estimate surface temperature iteratively
            surface_temp = atmospheric_temp  # Initial guess
            
            for _ in range(5):  # Simple iteration
                longwave_up = 5.67e-8 * surface_temp**4
                net_radiation = net_solar + longwave_down - longwave_up
                
                # Sensible heat flux (simplified)
                sensible_heat = 20.0 * (surface_temp - atmospheric_temp)
                
                # Latent heat flux (simplified)
                latent_heat = 30.0 if await self._is_over_water(lat, lon) else 10.0
                
                # Energy balance
                energy_imbalance = net_radiation - sensible_heat - latent_heat
                
                # Update surface temperature
                temp_change = energy_imbalance / surface_heat_capacity
                surface_temp += temp_change * 0.1  # Damping factor
            
            return max(250.0, min(350.0, surface_temp))
            
        except Exception as e:
            return atmospheric_temp + 2.0  # Surface slightly warmer than air
    
    async def _calculate_solar_radiation_input(self, lat: float, timestamp: datetime) -> float:
        """Calculate solar radiation input based on solar geometry"""
        try:
            day_of_year = timestamp.timetuple().tm_yday
            hour = timestamp.hour
            
            # Solar declination
            declination = 23.45 * np.sin(np.radians(360 * (284 + day_of_year) / 365))
            
            # Hour angle
            hour_angle = 15 * (hour - 12)
            
            # Solar elevation angle
            lat_rad = np.radians(lat)
            decl_rad = np.radians(declination)
            hour_rad = np.radians(hour_angle)
            
            solar_elevation = np.arcsin(
                np.sin(lat_rad) * np.sin(decl_rad) + 
                np.cos(lat_rad) * np.cos(decl_rad) * np.cos(hour_rad)
            )
            
            # Solar radiation (simplified)
            if solar_elevation > 0:
                solar_constant = 1361  # W/m²
                atmospheric_transmission = 0.7  # Clear sky
                solar_input = solar_constant * atmospheric_transmission * np.sin(solar_elevation)
            else:
                solar_input = 0.0
            
            return max(0.0, solar_input)
            
        except Exception as e:
            return 200.0  # Default daytime value
    
    async def _estimate_surface_albedo(self, lat: float, lon: float) -> float:
        """Estimate surface albedo based on surface type"""
        try:
            # Albedo by surface type
            if await self._is_over_water(lat, lon):
                return 0.06  # Water
            elif abs(lat) > 60 or await self._is_high_elevation(lat, lon):
                return 0.80  # Snow/ice
            elif await self._is_desert_region(lat, lon):
                return 0.35  # Desert
            elif await self._is_forest_region(lat, lon):
                return 0.15  # Forest
            elif await self._is_urban_area(lat, lon):
                return 0.20  # Urban
            else:
                return 0.25  # Mixed vegetation/soil
                
        except Exception as e:
            return 0.20
    
    async def _estimate_surface_heat_capacity(self, lat: float, lon: float) -> float:
        """Estimate surface heat capacity"""
        try:
            if await self._is_over_water(lat, lon):
                return 4186000.0  # Water (J/m³/K)
            elif await self._is_desert_region(lat, lon):
                return 1200000.0  # Dry soil
            elif await self._is_forest_region(lat, lon):
                return 2500000.0  # Vegetation/moist soil
            else:
                return 2000000.0  # Mixed surface
                
        except Exception as e:
            return 2000000.0
    
    async def _calculate_local_lapse_rate_correction(self, lat: float, lon: float, elevation: float) -> float:
        """Calculate local lapse rate correction based on topography"""
        try:
            # Standard lapse rate is 6.5 K/km
            # Local variations due to humidity, stability, etc.
            
            if await self._is_over_water(lat, lon):
                # Moist adiabatic lapse rate
                local_lapse_rate = 0.005  # K/m
            elif await self._is_desert_region(lat, lon):
                # Dry adiabatic lapse rate
                local_lapse_rate = 0.010  # K/m
            else:
                # Standard atmosphere
                local_lapse_rate = 0.0065  # K/m
            
            # Correction from standard lapse rate
            standard_lapse_rate = 0.0065
            lapse_rate_difference = local_lapse_rate - standard_lapse_rate
            
            return lapse_rate_difference * elevation
            
        except Exception as e:
            return 0.0
    
    async def _calculate_advanced_uncertainty(self, temperature: float, elevation: float, 
                                           timestamp: datetime) -> float:
        """Calculate advanced measurement uncertainty"""
        try:
            # Base instrument uncertainty
            base_uncertainty = 1.5
            
            # Temperature-dependent uncertainty
            temp_uncertainty = 0.005 * abs(temperature - 300.0)
            
            # Elevation-dependent uncertainty (atmospheric path)
            elevation_uncertainty = 0.001 * elevation
            
            # Time-dependent uncertainty (atmospheric stability)
            hour = timestamp.hour
            if 10 <= hour <= 16:  # Daytime instability
                time_uncertainty = 1.0
            else:  # Nighttime stability
                time_uncertainty = 0.5
            
            # Random component
            random_uncertainty = np.random.uniform(0.5, 1.5)
            
            total_uncertainty = np.sqrt(
                base_uncertainty**2 + temp_uncertainty**2 + 
                elevation_uncertainty**2 + time_uncertainty**2 + 
                random_uncertainty**2
            )
            
            return max(1.0, min(8.0, total_uncertainty))
            
        except Exception as e:
            return 2.5
    
    async def _apply_comprehensive_observation_processing(self, obs: ThermalObservation) -> Optional[ThermalObservation]:
        """Apply comprehensive processing to thermal observations"""
        try:
            # Apply realistic measurement errors
            processed_obs = await self._apply_realistic_observation_errors(obs)
            
            # Validate observation quality
            if not await self._validate_observation_quality(processed_obs):
                return None
            
            # Apply atmospheric corrections if needed
            if not processed_obs.atmospheric_correction:
                processed_obs = await self._apply_post_processing_atmospheric_correction(processed_obs)
            
            # Update quality flags
            processed_obs.quality_flags.extend(await self._assess_comprehensive_quality(processed_obs))
            
            return processed_obs
            
        except Exception as e:
            self.logger.error(f"Comprehensive observation processing failed: {e}")
            return obs  # Return original if processing fails
    
    async def _validate_observation_quality(self, obs: ThermalObservation) -> bool:
        """Validate observation quality"""
        try:
            # Temperature range check
            if not (200.0 <= obs.temperature_k <= 400.0):
                return False
            
            # Uncertainty check
            if obs.uncertainty_k and obs.uncertainty_k > 15.0:
                return False
            
            # Cloud mask check
            if obs.cloud_mask:
                return False
            
            # Coordinate validation
            if not (-90 <= obs.latitude <= 90 and -180 <= obs.longitude <= 180):
                return False
            
            return True
            
        except Exception as e:
            return True  # Default to valid if check fails
    
    async def _apply_post_processing_atmospheric_correction(self, obs: ThermalObservation) -> ThermalObservation:
        """Apply post-processing atmospheric correction"""
        try:
            # Simple atmospheric correction
            correction_factor = 1.02  # 2% correction
            obs.temperature_k *= correction_factor
            obs.atmospheric_correction = True
            obs.quality_flags.append('post_processed_atmospheric_correction')
            
            return obs
            
        except Exception as e:
            return obs
    
    async def _assess_comprehensive_quality(self, obs: ThermalObservation) -> List[str]:
        """Assess comprehensive quality flags"""
        try:
            quality_flags = []
            
            # Temperature quality
            if obs.temperature_k > 350.0:
                quality_flags.append('high_temperature')
            elif obs.temperature_k < 250.0:
                quality_flags.append('low_temperature')
            
            # Uncertainty quality
            if obs.uncertainty_k and obs.uncertainty_k > 5.0:
                quality_flags.append('high_uncertainty')
            
            # Viewing geometry quality
            if obs.satellite_zenith_angle and obs.satellite_zenith_angle > 50.0:
                quality_flags.append('high_zenith_angle')
            
            return quality_flags
            
        except Exception as e:
            return []
    
    async def _generate_basic_fallback_data(self, lat_min: float, lat_max: float,
                                          lon_min: float, lon_max: float,
                                          start_time: datetime, end_time: datetime) -> List[ThermalObservation]:
        """Generate basic fallback synthetic data"""
        try:
            observations = []
            
            # Generate 20 basic observations
            time_delta = (end_time - start_time) / 20
            
            for i in range(20):
                lat = np.random.uniform(lat_min, lat_max)
                lon = np.random.uniform(lon_min, lon_max)
                timestamp = start_time + i * time_delta
                
                # Basic temperature calculation
                elevation = 1000.0  # Default elevation
                base_temp = 288.15 - 0.0065 * elevation
                seasonal_var = 10.0 * np.cos(2 * np.pi * (timestamp.timetuple().tm_yday - 80) / 365)
                random_var = np.random.normal(0, 5)
                
                final_temp = base_temp + seasonal_var + random_var
                
                obs = ThermalObservation(
                    observation_id=f"fallback_{i}",
                    timestamp=timestamp,
                    latitude=lat,
                    longitude=lon,
                    elevation=elevation,
                    temperature_k=final_temp,
                    radiance=self._temperature_to_radiance(final_temp),
                    emissivity=0.92,
                    pixel_size_m=1000.0,
                    data_source=ThermalDataSource.MODIS_TERRA,
                    satellite_zenith_angle=30.0,
                    solar_zenith_angle=45.0,
                    atmospheric_correction=False,
                    cloud_mask=False,
                    quality_flags=['fallback_synthetic'],
                    uncertainty_k=3.0,
                    metadata={'synthetic_data': True, 'method': 'basic_fallback'}
                )
                observations.append(obs)
            
            return observations
            
        except Exception as e:
            self.logger.error(f"Basic fallback data generation failed: {e}")
            return []   
 
