    async def _calculate_hotspot_distance(self, lat: float, lon: float) -> float:
        """Calculate distance to nearest volcanic hotspot"""
        try:
            # Known major hotspots with their approximate locations
            hotspots = [
                {'name': 'Hawaii', 'lat': 19.5, 'lon': -155.5, 'strength': 1.0},
                {'name': 'Yellowstone', 'lat': 44.4, 'lon': -110.6, 'strength': 0.9},
                {'name': 'Iceland', 'lat': 64.1, 'lon': -21.9, 'strength': 0.8},
                {'name': 'Galapagos', 'lat': -0.4, 'lon': -91.4, 'strength': 0.7},
                {'name': 'Reunion', 'lat': -21.1, 'lon': 55.5, 'strength': 0.8},
                {'name': 'Azores', 'lat': 37.7, 'lon': -25.7, 'strength': 0.6},
                {'name': 'Canary Islands', 'lat': 28.1, 'lon': -15.4, 'strength': 0.6},
                {'name': 'Tristan da Cunha', 'lat': -37.1, 'lon': -12.3, 'strength': 0.5},
                {'name': 'Easter Island', 'lat': -27.1, 'lon': -109.4, 'strength': 0.5},
                {'name': 'Kerguelen', 'lat': -49.4, 'lon': 69.2, 'strength': 0.4},
                {'name': 'Louisville', 'lat': -50.0, 'lon': -139.0, 'strength': 0.4},
                {'name': 'Bermuda', 'lat': 32.3, 'lon': -64.8, 'strength': 0.3},
                {'name': 'Cape Verde', 'lat': 16.0, 'lon': -24.0, 'strength': 0.4},
                {'name': 'Samoa', 'lat': -14.3, 'lon': -170.7, 'strength': 0.5},
                {'name': 'Tahiti', 'lat': -17.7, 'lon': -149.4, 'strength': 0.5}
            ]
            
            min_distance = float('inf')
            nearest_hotspot = None
            
            for hotspot in hotspots:
                # Calculate great circle distance
                distance = self._calculate_distance_km(lat, lon, hotspot['lat'], hotspot['lon'])
                
                # Weight by hotspot strength
                weighted_distance = distance / hotspot['strength']
                
                if weighted_distance < min_distance:
                    min_distance = weighted_distance
                    nearest_hotspot = hotspot
            
            # Query database for additional hotspots if available
            try:
                cursor = self.db_connections['postgresql'].cursor()
                cursor.execute("""
                    SELECT ST_Y(location) as lat, ST_X(location) as lon, 
                           properties->>'strength' as strength
                    FROM geological_structures 
                    WHERE structure_type = 'hotspot'
                    ORDER BY ST_Distance(location, ST_GeogFromText(%s)) ASC
                    LIMIT 5;
                """, (f'POINT({lon} {lat})',))
                
                db_hotspots = cursor.fetchall()
                for hs in db_hotspots:
                    distance = self._calculate_distance_km(lat, lon, hs['lat'], hs['lon'])
                    strength = float(hs['strength']) if hs['strength'] else 0.5
                    weighted_distance = distance / strength
                    
                    if weighted_distance < min_distance:
                        min_distance = weighted_distance
                        
            except Exception as db_error:
                self.logger.warning(f"Database hotspot query failed: {db_error}")
            
            return min_distance if min_distance != float('inf') else 2000.0
            
        except Exception as e:
            self.logger.error(f"Hotspot distance calculation failed: {e}")
            return 1000.0  # Default large distance
    
    async def _classify_tectonic_setting_advanced(self, lat: float, lon: float) -> str:
        """Advanced tectonic setting classification using database and geophysical models"""
        try:
            cursor = self.db_connections['postgresql'].cursor()
            
            # Query tectonic plates and boundaries from database
            cursor.execute("""
                SELECT 
                    tp.plate_name,
                    tp.plate_type,
                    pb.boundary_type,
                    pb.convergence_rate_mm_yr,
                    pb.spreading_rate_mm_yr,
                    ST_Distance(pb.location, ST_GeogFromText(%s)) as boundary_distance,
                    ST_Distance(tp.location, ST_GeogFromText(%s)) as plate_distance
                FROM tectonic_plates tp
                LEFT JOIN plate_boundaries pb ON ST_DWithin(tp.location, pb.location, 500000)
                WHERE ST_DWithin(tp.location, ST_GeogFromText(%s), 1000000)
                ORDER BY plate_distance ASC, boundary_distance ASC
                LIMIT 10;
            """, (f'POINT({lon} {lat})', f'POINT({lon} {lat})', f'POINT({lon} {lat})'))
            
            tectonic_records = cursor.fetchall()
            
            if tectonic_records:
                # Analyze tectonic context
                closest_record = tectonic_records[0]
                plate_type = closest_record.get('plate_type', 'continental')
                boundary_type = closest_record.get('boundary_type')
                boundary_distance = closest_record.get('boundary_distance', 1000000)
                convergence_rate = closest_record.get('convergence_rate_mm_yr', 0)
                spreading_rate = closest_record.get('spreading_rate_mm_yr', 0)
                
                # Classify based on proximity to boundaries and rates
                if boundary_distance < 200000:  # Within 200 km of plate boundary
                    if boundary_type == 'convergent':
                        if convergence_rate > 50:  # Fast convergence
                            return 'active_subduction_zone'
                        else:
                            return 'subduction_zone'
                    elif boundary_type == 'divergent':
                        if spreading_rate > 30:  # Fast spreading
                            return 'fast_spreading_ridge'
                        else:
                            return 'mid_ocean_ridge'
                    elif boundary_type == 'transform':
                        return 'transform_fault'
                    else:
                        return 'complex_boundary'
                
                # Check for intraplate settings
                elif boundary_distance > 500000:  # Far from boundaries
                    if plate_type == 'oceanic':
                        # Check for hotspots
                        hotspot_distance = await self._calculate_hotspot_distance(lat, lon)
                        if hotspot_distance < 300000:  # Within 300 km of hotspot
                            return 'oceanic_hotspot'
                        else:
                            return 'stable_oceanic'
                    else:
                        # Continental intraplate
                        rift_distance = await self._calculate_rift_distance(lat, lon)
                        if rift_distance < 200000:  # Within 200 km of rift
                            return 'continental_rift'
                        else:
                            return 'stable_continental'
                
                else:
                    # Intermediate distance from boundaries
                    return 'transitional_tectonic'
            
            else:
                # Use geophysical models as fallback
                return await self._classify_tectonic_from_geophysics(lat, lon)
                
        except Exception as e:
            self.logger.error(f"Advanced tectonic classification failed: {e}")
            return await self._classify_tectonic_from_geophysics(lat, lon)
    
    async def _classify_tectonic_from_geophysics(self, lat: float, lon: float) -> str:
        """Classify tectonic setting using geophysical models and global datasets"""
        try:
            # Calculate distances to major tectonic features
            subduction_distance = await self._calculate_subduction_zone_distance(lat, lon)
            ridge_distance = await self._calculate_ridge_distance(lat, lon)
            hotspot_distance = await self._calculate_hotspot_distance(lat, lon)
            rift_distance = await self._calculate_rift_distance(lat, lon)
            
            # Determine crustal type
            is_oceanic = await self._is_oceanic_crust(lat, lon)
            
            # Classification based on distances and crustal type
            min_distance = min(subduction_distance, ridge_distance, hotspot_distance, rift_distance)
            
            if min_distance == subduction_distance and subduction_distance < 300000:
                # Near subduction zone
                if subduction_distance < 100000:
                    return 'active_subduction_zone'
                else:
                    return 'subduction_zone'
            
            elif min_distance == ridge_distance and ridge_distance < 200000:
                # Near mid-ocean ridge
                if is_oceanic:
                    return 'mid_ocean_ridge'
                else:
                    return 'continental_rift'
            
            elif min_distance == hotspot_distance and hotspot_distance < 400000:
                # Near hotspot
                if is_oceanic:
                    return 'oceanic_hotspot'
                else:
                    return 'continental_hotspot'
            
            elif min_distance == rift_distance and rift_distance < 250000:
                # Near continental rift
                return 'continental_rift'
            
            else:
                # Stable intraplate setting
                if is_oceanic:
                    return 'stable_oceanic'
                else:
                    return 'stable_continental'
                    
        except Exception as e:
            self.logger.error(f"Geophysical tectonic classification failed: {e}")
            return 'stable_continental'
    
    async def _calculate_subduction_zone_distance(self, lat: float, lon: float) -> float:
        """Calculate distance to nearest subduction zone"""
        try:
            # Major subduction zones (simplified global model)
            subduction_zones = [
                # Pacific Ring of Fire
                {'lat_range': (30, 70), 'lon_range': (120, 180), 'name': 'Japan-Kamchatka'},
                {'lat_range': (50, 70), 'lon_range': (-180, -140), 'name': 'Aleutian'},
                {'lat_range': (30, 60), 'lon_range': (-140, -120), 'name': 'Cascadia'},
                {'lat_range': (-60, 20), 'lon_range': (-90, -60), 'name': 'Andes'},
                {'lat_range': (-10, 40), 'lon_range': (120, 150), 'name': 'Indonesia-Philippines'},
                # Other major zones
                {'lat_range': (30, 45), 'lon_range': (20, 50), 'name': 'Mediterranean'},
                {'lat_range': (10, 30), 'lon_range': (-90, -60), 'name': 'Caribbean'},
            ]
            
            min_distance = float('inf')
            
            for zone in subduction_zones:
                lat_min, lat_max = zone['lat_range']
                lon_min, lon_max = zone['lon_range']
                
                # Calculate distance to zone boundary
                if lat_min <= lat <= lat_max and lon_min <= lon <= lon_max:
                    # Inside zone
                    min_distance = 0.0
                    break
                else:
                    # Distance to nearest edge of zone
                    lat_dist = max(0, lat_min - lat, lat - lat_max)
                    lon_dist = max(0, lon_min - lon, lon - lon_max)
                    
                    # Convert to kilometers (rough approximation)
                    distance_km = np.sqrt((lat_dist * 111)**2 + (lon_dist * 111 * np.cos(np.radians(lat)))**2) * 1000
                    min_distance = min(min_distance, distance_km)
            
            return min_distance
            
        except Exception as e:
            self.logger.error(f"Subduction zone distance calculation failed: {e}")
            return 1000000.0  # Large default distance
    
    async def _calculate_ridge_distance(self, lat: float, lon: float) -> float:
        """Calculate distance to nearest mid-ocean ridge"""
        try:
            # Major mid-ocean ridges
            ridges = [
                # Mid-Atlantic Ridge
                {'lat_range': (-60, 70), 'lon_range': (-40, -10), 'name': 'Mid-Atlantic'},
                # East Pacific Rise
                {'lat_range': (-60, 60), 'lon_range': (-120, -100), 'name': 'East Pacific Rise'},
                # Indian Ocean ridges
                {'lat_range': (-50, 20), 'lon_range': (60, 90), 'name': 'Central Indian Ridge'},
                # Arctic ridges
                {'lat_range': (70, 85), 'lon_range': (-10, 30), 'name': 'Gakkel Ridge'},
            ]
            
            min_distance = float('inf')
            
            for ridge in ridges:
                lat_min, lat_max = ridge['lat_range']
                lon_min, lon_max = ridge['lon_range']
                
                if lat_min <= lat <= lat_max and lon_min <= lon <= lon_max:
                    min_distance = 0.0
                    break
                else:
                    lat_dist = max(0, lat_min - lat, lat - lat_max)
                    lon_dist = max(0, lon_min - lon, lon - lon_max)
                    
                    distance_km = np.sqrt((lat_dist * 111)**2 + (lon_dist * 111 * np.cos(np.radians(lat)))**2) * 1000
                    min_distance = min(min_distance, distance_km)
            
            return min_distance
            
        except Exception as e:
            return 1000000.0
    
