    async def _estimate_crustal_thickness(self, lat: float, lon: float) -> float:
        """Estimate crustal thickness using global crustal models"""
        try:
            # Global average crustal thickness patterns
            abs_lat = abs(lat)
            
            # Check if oceanic or continental crust
            is_oceanic = await self._is_oceanic_crust(lat, lon)
            
            if is_oceanic:
                # Oceanic crust thickness (typically 6-10 km)
                base_thickness = 7.0  # km
                
                # Age-dependent thickness variation
                crustal_age = await self._estimate_crustal_age(lat, lon)
                age_factor = min(1.5, 1.0 + crustal_age / 200.0)  # Older crust slightly thicker
                
                thickness = base_thickness * age_factor
                
            else:
                # Continental crust thickness (typically 30-70 km)
                base_thickness = 35.0  # km
                
                # Tectonic setting influence
                tectonic_setting = await self._classify_tectonic_setting_advanced(lat, lon)
                
                if tectonic_setting == 'subduction_zone':
                    thickness = base_thickness * 1.8  # Thickened by compression
                elif tectonic_setting == 'continental_rift':
                    thickness = base_thickness * 0.7  # Thinned by extension
                elif tectonic_setting == 'hotspot':
                    thickness = base_thickness * 1.2  # Slightly thickened
                else:
                    thickness = base_thickness
                
                # Elevation correlation (higher elevations = thicker crust)
                if await self._is_near_volcano(lat, lon):
                    elevation = await self._get_volcanic_base_elevation(lat, lon)
                    elevation_factor = 1.0 + elevation / 10000.0  # 10% increase per 10km elevation
                    thickness *= elevation_factor
            
            return max(5.0, min(80.0, thickness))  # Realistic bounds
            
        except Exception as e:
            self.logger.error(f"Crustal thickness estimation failed: {e}")
            return 35.0 if not await self._is_oceanic_crust(lat, lon) else 7.0
    
    async def _is_oceanic_crust(self, lat: float, lon: float) -> bool:
        """Determine if location is on oceanic crust"""
        try:
            # Simple oceanic/continental classification
            # Major ocean basins
            ocean_regions = [
                # Pacific Ocean
                {'lat_range': (-60, 60), 'lon_range': (120, -70), 'crosses_dateline': True},
                # Atlantic Ocean
                {'lat_range': (-60, 70), 'lon_range': (-70, 20), 'crosses_dateline': False},
                # Indian Ocean
                {'lat_range': (-60, 30), 'lon_range': (20, 120), 'crosses_dateline': False},
                # Arctic Ocean
                {'lat_range': (70, 90), 'lon_range': (-180, 180), 'crosses_dateline': False},
                # Southern Ocean
                {'lat_range': (-90, -60), 'lon_range': (-180, 180), 'crosses_dateline': False}
            ]
            
            for region in ocean_regions:
                lat_min, lat_max = region['lat_range']
                lon_min, lon_max = region['lon_range']
                
                if lat_min <= lat <= lat_max:
                    if region['crosses_dateline']:
                        if lon >= lon_min or lon <= lon_max:
                            return True
                    else:
                        if lon_min <= lon <= lon_max:
                            return True
            
            return False
            
        except Exception as e:
            return False
    
    async def _estimate_crustal_age(self, lat: float, lon: float) -> float:
        """Estimate crustal age in millions of years"""
        try:
            is_oceanic = await self._is_oceanic_crust(lat, lon)
            
            if is_oceanic:
                # Oceanic crust age based on distance from mid-ocean ridges
                ridge_distance = await self._calculate_distance_to_ridge_advanced(lat, lon)
                
                # Typical spreading rate: 2-10 cm/year
                spreading_rate = 5.0  # cm/year average
                age_ma = (ridge_distance * 1000 * 100) / (spreading_rate * 1e6)  # Convert to Ma
                
                return min(200.0, max(0.0, age_ma))  # Oceanic crust max ~200 Ma
                
            else:
                # Continental crust age (much older, typically 1-4 Ga)
                # Advanced age model based on tectonic setting
                tectonic_setting = await self._classify_tectonic_setting_advanced(lat, lon)
                
                if tectonic_setting in ['subduction_zone', 'continental_rift']:
                    return np.random.uniform(100, 1000)  # Younger continental crust
                else:
                    return np.random.uniform(500, 3000)  # Older continental crust
                    
        except Exception as e:
            return 100.0 if await self._is_oceanic_crust(lat, lon) else 1000.0
    
    def _calculate_distance_km(self, lat1: float, lon1: float, lat2: float, lon2: float) -> float:
        """Calculate great circle distance between two points in kilometers"""
        try:
            # Haversine formula
            R = 6371.0  # Earth radius in km
            
            lat1_rad = np.radians(lat1)
            lat2_rad = np.radians(lat2)
            dlat = np.radians(lat2 - lat1)
            dlon = np.radians(lon2 - lon1)
            
            a = (np.sin(dlat/2)**2 + 
                 np.cos(lat1_rad) * np.cos(lat2_rad) * np.sin(dlon/2)**2)
            c = 2 * np.arctan2(np.sqrt(a), np.sqrt(1-a))
            
            return R * c
            
        except Exception as e:
            return 0.0
    
    async def _calculate_distance_to_ridge_advanced(self, lat: float, lon: float) -> float:
        """Calculate distance to nearest mid-ocean ridge"""
        try:
            # Major mid-ocean ridge segments
            ridges = [
                # Mid-Atlantic Ridge
                {'lat_range': (-60, 70), 'lon_center': -25, 'name': 'Mid-Atlantic'},
                # East Pacific Rise
                {'lat_range': (-55, 35), 'lon_center': -110, 'name': 'East Pacific Rise'},
                # Southwest Indian Ridge
                {'lat_range': (-55, -25), 'lon_center': 50, 'name': 'Southwest Indian'},
                # Southeast Indian Ridge
                {'lat_range': (-50, -25), 'lon_center': 120, 'name': 'Southeast Indian'},
                # Central Indian Ridge
                {'lat_range': (-25, 25), 'lon_center': 65, 'name': 'Central Indian'},
                # Juan de Fuca Ridge
                {'lat_range': (40, 50), 'lon_center': -130, 'name': 'Juan de Fuca'}
            ]
            
            min_distance = float('inf')
            
            for ridge in ridges:
                lat_min, lat_max = ridge['lat_range']
                ridge_lon = ridge['lon_center']
                
                # Find closest point on ridge segment
                if lat_min <= lat <= lat_max:
                    # Point is within ridge latitude range
                    distance = self._calculate_distance_km(lat, lon, lat, ridge_lon)
                else:
                    # Point is outside ridge latitude range
                    if lat < lat_min:
                        distance = self._calculate_distance_km(lat, lon, lat_min, ridge_lon)
                    else:
                        distance = self._calculate_distance_km(lat, lon, lat_max, ridge_lon)
                
                min_distance = min(min_distance, distance)
            
            return min_distance if min_distance != float('inf') else 5000.0
            
        except Exception as e:
            return 3000.0  # Default moderate distance   
