            radius_deg = 0.05  # ~5 km radius
            
            # Sample elevations in a grid pattern
            elevations = []
            for i in range(7):  # 7x7 grid
                for j in range(7):
                    sample_lat = lat + (i - 3) * radius_deg / 3
                    sample_lon = lon + (j - 3) * radius_deg / 3
                    
