    async def _calculate_simple_spatial_correlation(self, temp_slice: np.ndarray) -> float:
        """Simple spatial correlation as fallback"""
        try:
            valid_mask = ~np.isnan(temp_slice)
            if np.sum(valid_mask) < 4:
                return 0.0
            
            # Calculate correlation between neighboring pixels
            correlations = []
            
            rows, cols = temp_slice.shape
            for i in range(rows-1):
                for j in range(cols-1):
                    if valid_mask[i, j] and valid_mask[i+1, j]:
                        correlations.append(temp_slice[i, j] * temp_slice[i+1, j])
                    if valid_mask[i, j] and valid_mask[i, j+1]:
                        correlations.append(temp_slice[i, j] * temp_slice[i, j+1])
            
            if correlations:
                return np.mean(correlations) / (np.var(temp_slice[valid_mask]) + 1e-10)
            else:
                return 0.0
                
        except Exception as e:
            return 0.0 
   
    def _improved_noise_function(self, x: float, y: float) -> float:
        """Improved noise function with better interpolation than simple trigonometric"""
        try:
            # Use a combination of trigonometric functions with different phases
            # to create more natural-looking noise
            
            # Primary noise component
            noise1 = np.sin(x * 2.0 * np.pi + 0.5) * np.cos(y * 2.0 * np.pi + 0.3)
            
            # Secondary component with different frequency and phase
            noise2 = np.sin(x * 3.14159 + 1.2) * np.cos(y * 3.14159 + 0.8)
            
            # Tertiary component for fine detail
            noise3 = np.sin(x * 5.1 + 2.1) * np.cos(y * 5.1 + 1.7)
            
            # Combine with weights
            combined = 0.6 * noise1 + 0.3 * noise2 + 0.1 * noise3
            
            # Apply smoothing function to reduce harsh transitions
            return np.tanh(combined)
            
        except Exception as e:
            return 0.0
    
    async def _calculate_morans_i_p_value(self, morans_i: float, n: int, sum_weights: float) -> float:
        """Calculate p-value for Moran's I using proper statistical distribution"""
        try:
            if n < 4 or sum_weights == 0:
                return 0.5
            
            # Expected value of Moran's I under null hypothesis
            expected_i = -1.0 / (n - 1)
            
            # Variance of Moran's I (simplified formula)
            # Full formula requires second-order weights matrix
            variance_i = (n * n - 3 * n + 3) / ((n - 1) * (n - 2) * (n - 3))
            variance_i *= (sum_weights * sum_weights) / (sum_weights * sum_weights)
            
            if variance_i <= 0:
                return 0.5
            
            # Standardized Moran's I
            z_score = (morans_i - expected_i) / np.sqrt(variance_i)
            
            # Calculate p-value using normal approximation
            # Two-tailed test
            p_value = 2 * (1 - stats.norm.cdf(abs(z_score)))
            
            return max(0.001, min(0.999, p_value))
            
        except Exception as e:
            return 0.5
    
