    async def _calculate_distance_to_coast(self, location: Tuple[float, float]) -> float:
        """Calculate distance to nearest coastline"""
        try:
            lat, lon = location
            
            # Simplified coastline distance calculation
            # In production, would use high-resolution coastline database
            
            # Major continental boundaries (simplified)
            continental_boundaries = [
                # North America Pacific coast
                {'lat_range': (30, 70), 'lon_range': (-130, -120)},
                # North America Atlantic coast
                {'lat_range': (25, 70), 'lon_range': (-85, -65)},
                # South America Pacific coast
                {'lat_range': (-55, 15), 'lon_range': (-85, -70)},
                # South America Atlantic coast
                {'lat_range': (-55, 15), 'lon_range': (-60, -35)},
                # Europe Atlantic coast
                {'lat_range': (35, 75), 'lon_range': (-15, 5)},
                # Africa Atlantic coast
                {'lat_range': (-35, 35), 'lon_range': (-20, 20)},
                # Asia Pacific coast
                {'lat_range': (20, 70), 'lon_range': (100, 150)},
                # Australia coast
                {'lat_range': (-45, -10), 'lon_range': (110, 155)}
            ]
            
            min_distance = float('inf')
            
            for boundary in continental_boundaries:
                lat_min, lat_max = boundary['lat_range']
                lon_min, lon_max = boundary['lon_range']
                
                # Find closest point on boundary
                if lat_min <= lat <= lat_max:
                    # Within latitude range, find closest longitude
                    if lon < lon_min:
                        closest_distance = self._calculate_distance_km(lat, lon, lat, lon_min)
                    elif lon > lon_max:
                        closest_distance = self._calculate_distance_km(lat, lon, lat, lon_max)
                    else:
                        closest_distance = 0.0  # On land
                else:
                    # Outside latitude range, find closest corner
                    closest_lat = lat_min if lat < lat_min else lat_max
                    closest_lon = max(lon_min, min(lon_max, lon))
                    closest_distance = self._calculate_distance_km(lat, lon, closest_lat, closest_lon)
                
                min_distance = min(min_distance, closest_distance)
            
            return min_distance if min_distance != float('inf') else 1000.0
            
        except Exception as e:
            return 500.0
    
