    async def _query_volcanic_geological_features(self, lat: float, lon: float) -> List[Dict[str, Any]]:
        """Query volcanic geological features from database"""
        try:
            cursor = self.db_connections['postgresql'].cursor()
            
            # Query geological features within 25km
            cursor.execute("""
                SELECT 
                    structure_type,
                    properties->>'feature_type' as feature_type,
                    properties->>'age_ma' as age_ma,
                    properties->>'composition' as composition,
                    ST_Distance(location, ST_GeogFromText(%s)) as distance_m
                FROM geological_structures 
                WHERE ST_DWithin(location, ST_GeogFromText(%s), 25000)
                AND structure_type IN ('volcanic_deposit', 'thermal_spring', 'fumarole', 'lava_flow', 'pyroclastic_deposit')
                ORDER BY distance_m ASC
                LIMIT 10;
            """, (f'POINT({lon} {lat})', f'POINT({lon} {lat})'))
            
            features = []
            for row in cursor.fetchall():
                features.append({
                    'structure_type': row['structure_type'],
                    'feature_type': row['feature_type'],
                    'age_ma': float(row['age_ma']) if row['age_ma'] else None,
                    'composition': row['composition'],
                    'distance_m': row['distance_m']
                })
            
            return features
            
        except Exception as e:
            self.logger.error(f"Volcanic geological features query failed: {e}")
            return []
    
    async def _classify_plate_boundary_type(self, lat: float, lon: float) -> str:
        """Classify type of nearest plate boundary"""
        try:
            cursor = self.db_connections['postgresql'].cursor()
            
            # Query nearest plate boundary
            cursor.execute("""
                SELECT 
                    boundary_type,
                    convergence_rate_mm_yr,
                    spreading_rate_mm_yr
                FROM tectonic_plates 
                WHERE ST_DWithin(boundary_geom, ST_GeogFromText(%s), 500000)
                ORDER BY ST_Distance(boundary_geom, ST_GeogFromText(%s)) ASC
                LIMIT 1;
            """, (f'POINT({lon} {lat})', f'POINT({lon} {lat})'))
            
            result = cursor.fetchone()
            if result:
                boundary_type = result['boundary_type']
                convergence_rate = result['convergence_rate_mm_yr'] or 0
                spreading_rate = result['spreading_rate_mm_yr'] or 0
                
                # Classify based on kinematics
                if boundary_type == 'convergent':
                    if convergence_rate > 50:
                        return 'fast_convergent'
                    else:
                        return 'slow_convergent'
                elif boundary_type == 'divergent':
                    if spreading_rate > 40:
                        return 'fast_spreading'
                    else:
                        return 'slow_spreading'
                elif boundary_type == 'transform':
                    if convergence_rate > 10:  # Some convergent component
                        return 'transform_with_volcanism'
                    else:
                        return 'pure_transform'
                else:
                    return boundary_type
            
            return 'unknown'
            
        except Exception as e:
            return 'unknown'
    
