    async def _query_comprehensive_plate_boundary_database(self, lat: float, lon: float) -> Optional[float]:
        """Query comprehensive plate boundary database with detailed boundary segments"""
        try:
            cursor = self.db_connections['postgresql'].cursor()
            
            # Query detailed plate boundary segments
            cursor.execute("""
                SELECT 
                    pb.boundary_type,
                    pb.plate_name_1,
                    pb.plate_name_2,
                    pb.convergence_rate_mm_yr,
                    pb.spreading_rate_mm_yr,
                    pb.transform_rate_mm_yr,
                    ST_Distance(pb.boundary_geom, ST_GeogFromText(%s)) as distance_m,
                    pb.boundary_confidence,
                    pb.age_ma
                FROM plate_boundaries pb
                WHERE ST_DWithin(pb.boundary_geom, ST_GeogFromText(%s), 2000000)
                ORDER BY distance_m ASC
                LIMIT 10;
            """, (f'POINT({lon} {lat})', f'POINT({lon} {lat})'))
            
            boundary_records = cursor.fetchall()
            
            if boundary_records:
                # Use the closest high-confidence boundary
                for record in boundary_records:
                    confidence = record.get('boundary_confidence', 0.5)
                    if confidence > 0.7:  # High confidence boundary
                        return record['distance_m'] / 1000.0  # Convert to km
                
                # If no high-confidence boundary, use closest one
                return boundary_records[0]['distance_m'] / 1000.0
            
            return None
            
        except Exception as e:
            self.logger.error(f"Plate boundary database query failed: {e}")
            return None
    
