    async def _estimate_lithology_from_location(self, lat: float, lon: float) -> str:
        """Estimate dominant lithology based on geographic location and tectonic setting"""
        try:
            # Major tectonic and geological provinces
            
            # Volcanic arcs and hotspots
            volcanic_regions = [
                # Pacific Ring of Fire
                ((-60, 60), (120, -60)),  # Pacific Rim
                # Mid-ocean ridges
                ((-90, 90), (-30, -10)),  # Mid-Atlantic Ridge
                # Continental volcanic provinces
                ((35, 50), (-125, -110)),  # Cascade Range
                ((10, 25), (-110, -85)),   # Central American Volcanic Arc
            ]
            
            for lat_range, lon_range in volcanic_regions:
                if lat_range[0] <= lat <= lat_range[1] and lon_range[0] <= lon <= lon_range[1]:
                    return 'volcanic_rock'
            
            # Continental shields (old crystalline rocks)
            shield_regions = [
                ((45, 70), (-110, -60)),   # Canadian Shield
                ((-35, -10), (-70, -35)),  # Brazilian Shield
                ((60, 70), (20, 60)),      # Baltic Shield
                ((-30, -10), (15, 35)),    # African Shield
            ]
            
            for lat_range, lon_range in shield_regions:
                if lat_range[0] <= lat <= lat_range[1] and lon_range[0] <= lon <= lon_range[1]:
                    return 'granite'
            
            # Sedimentary basins
            sedimentary_regions = [
                ((25, 50), (-105, -95)),   # Great Plains
                ((45, 60), (-5, 15)),      # European Plain
                ((-25, -10), (115, 135)),  # Australian sedimentary basins
            ]
            
            for lat_range, lon_range in sedimentary_regions:
                if lat_range[0] <= lat <= lat_range[1] and lon_range[0] <= lon <= lon_range[1]:
                    return 'sedimentary'
            
            # Mountain belts (metamorphic rocks)
            if abs(lat) > 30 and (
                (-125 <= lon <= -110) or  # Western North America
                (-10 <= lon <= 50) or     # European Alps to Himalayas
                (-80 <= lon <= -60)       # Andes
            ):
                return 'metamorphic'
            
            # Default based on latitude
            if abs(lat) < 30:
                return 'volcanic_rock'  # More volcanic activity in tropics
            else:
                return 'granite'  # Continental crust
                
        except Exception as e:
            return 'volcanic_rock'  # Default
    
    async def _classify_terrain_type(self, elevation: float, slope: float, 
                                   lithology: str, structure_type: str) -> str:
        """Classify terrain type based on multiple parameters"""
        try:
            # Elevation-based classification
            if elevation > 3000:
                elevation_class = 'high_mountain'
            elif elevation > 1500:
                elevation_class = 'mountain'
            elif elevation > 500:
                elevation_class = 'hill'
            elif elevation > 100:
                elevation_class = 'plateau'
            else:
                elevation_class = 'lowland'
            
            # Slope-based classification
            if slope > 30:
                slope_class = 'steep'
            elif slope > 15:
                slope_class = 'moderate'
            elif slope > 5:
                slope_class = 'gentle'
            else:
                slope_class = 'flat'
            
            # Combine classifications
            if elevation_class in ['high_mountain', 'mountain'] and slope_class == 'steep':
                return 'alpine'
            elif elevation_class == 'mountain' and slope_class in ['moderate', 'gentle']:
                return 'mountainous'
            elif elevation_class in ['hill', 'plateau'] and slope_class in ['moderate', 'steep']:
                return 'hilly'
            elif elevation_class in ['hill', 'plateau'] and slope_class in ['gentle', 'flat']:
                return 'rolling'
            elif elevation_class == 'lowland':
                return 'plains'
            else:
                return 'varied'
                
        except Exception as e:
            return 'mountainous'  # Default
    
    async def _interpolate_elevation_gaps(self, elevation_array: np.ndarray, valid_mask: np.ndarray) -> np.ndarray:
        """Interpolate elevation gaps using advanced methods"""
        try:
            filled_array = elevation_array.copy()
            rows, cols = elevation_array.shape
            
            # Get coordinates of valid and invalid points
            valid_points = np.where(valid_mask)
            invalid_points = np.where(~valid_mask)
            
            if len(valid_points[0]) < 3 or len(invalid_points[0]) == 0:
                return filled_array
            
            # Use scipy's griddata for interpolation
            try:
                from scipy.interpolate import griddata
                
                # Create coordinate arrays
                valid_coords = np.column_stack([valid_points[0], valid_points[1]])
                valid_values = elevation_array[valid_mask]
                
                # Create grid for interpolation
                grid_y, grid_x = np.mgrid[0:rows, 0:cols]
                
                # Interpolate using cubic method (falls back to linear if not enough points)
                try:
                    interpolated = griddata(valid_coords, valid_values, 
                                          (grid_y, grid_x), method='cubic', fill_value=np.nan)
                except:
                    interpolated = griddata(valid_coords, valid_values, 
                                          (grid_y, grid_x), method='linear', fill_value=np.nan)
                
                # Fill only the originally invalid points
                filled_array[~valid_mask] = interpolated[~valid_mask]
                
                # Remove any remaining NaNs with nearest neighbor
                remaining_nans = np.isnan(filled_array)
                if np.sum(remaining_nans) > 0:
                    try:
                        nearest_interpolated = griddata(valid_coords, valid_values, 
                                                      (grid_y, grid_x), method='nearest')
                        filled_array[remaining_nans] = nearest_interpolated[remaining_nans]
                    except:
                        # Final fallback: use mean of valid values
                        filled_array[remaining_nans] = np.mean(valid_values)
                
            except ImportError:
                # Fallback to advanced terrain-aware interpolation
                filled_array = await self._advanced_terrain_aware_interpolation(elevation_array, valid_mask)
            
            return filled_array
            
        except Exception as e:
            self.logger.error(f"Elevation gap interpolation failed: {e}")
            return elevation_array
    
    async def _advanced_terrain_aware_interpolation(self, elevation_array: np.ndarray, valid_mask: np.ndarray) -> np.ndarray:
        """Advanced terrain-aware interpolation using geological constraints and physics-based methods"""
        try:
            filled_array = elevation_array.copy()
            rows, cols = elevation_array.shape
            
            # Get geological context for interpolation constraints
            geological_context = await self._get_interpolation_geological_context(elevation_array, valid_mask)
            
            # Multi-method interpolation approach
            interpolation_methods = []
            
            # Method 1: Kriging-based interpolation with geological constraints
            kriging_result = await self._geological_kriging_interpolation(
                elevation_array, valid_mask, geological_context
            )
            interpolation_methods.append(('kriging', kriging_result, 0.4))
            
            # Method 2: Radial basis function with terrain constraints
            rbf_result = await self._terrain_constrained_rbf_interpolation(
                elevation_array, valid_mask, geological_context
            )
            interpolation_methods.append(('rbf', rbf_result, 0.3))
            
            # Method 3: Anisotropic diffusion interpolation
            diffusion_result = await self._anisotropic_diffusion_interpolation(
                elevation_array, valid_mask, geological_context
            )
            interpolation_methods.append(('diffusion', diffusion_result, 0.2))
            
            # Method 4: Geological trend surface interpolation
            trend_result = await self._geological_trend_surface_interpolation(
                elevation_array, valid_mask, geological_context
            )
            interpolation_methods.append(('trend', trend_result, 0.1))
            
            # Weighted combination of methods
            final_result = np.zeros_like(elevation_array)
            total_weight = 0.0
            
            for method_name, result, weight in interpolation_methods:
                if result is not None:
                    # Apply quality-based weighting
                    quality_weight = await self._assess_interpolation_quality(
                        result, elevation_array, valid_mask, method_name
                    )
                    adjusted_weight = weight * quality_weight
                    
                    final_result += result * adjusted_weight
                    total_weight += adjusted_weight
            
            if total_weight > 0:
                final_result /= total_weight
                
                # Apply geological constraints
                constrained_result = await self._apply_geological_constraints(
                    final_result, elevation_array, valid_mask, geological_context
                )
                
                # Preserve original valid values
                result_array = elevation_array.copy()
                result_array[~valid_mask] = constrained_result[~valid_mask]
                
                return result_array
            else:
                # Fallback to advanced inverse distance weighting
                return await self._advanced_inverse_distance_weighting(elevation_array, valid_mask)
            
        except Exception as e:
            self.logger.error(f"Advanced terrain-aware interpolation failed: {e}")
            return await self._advanced_inverse_distance_weighting(elevation_array, valid_mask)
    
    async def _get_interpolation_geological_context(self, elevation_array: np.ndarray, valid_mask: np.ndarray) -> Dict[str, Any]:
        """Get geological context for interpolation constraints"""
        try:
            # Analyze elevation patterns to infer geological structure
            valid_elevations = elevation_array[valid_mask]
            
            if len(valid_elevations) < 3:
                return {'terrain_type': 'unknown', 'complexity': 'low'}
            
            # Calculate terrain statistics
            elevation_range = np.max(valid_elevations) - np.min(valid_elevations)
            elevation_std = np.std(valid_elevations)
            elevation_mean = np.mean(valid_elevations)
            
            # Classify terrain complexity
            if elevation_range > 1000 and elevation_std > 200:
                complexity = 'high'
                terrain_type = 'mountainous'
            elif elevation_range > 500 and elevation_std > 100:
                complexity = 'moderate'
                terrain_type = 'hilly'
            elif elevation_range > 100:
                complexity = 'low'
                terrain_type = 'rolling'
            else:
                complexity = 'very_low'
                terrain_type = 'flat'
            
            # Analyze spatial patterns
            gradient_magnitude = await self._calculate_spatial_gradient_magnitude(elevation_array, valid_mask)
            
            # Determine interpolation parameters
            smoothing_factor = 0.1 if complexity == 'high' else 0.3
            anisotropy_ratio = 2.0 if terrain_type == 'mountainous' else 1.0
            
            return {
                'terrain_type': terrain_type,
                'complexity': complexity,
                'elevation_range': elevation_range,
                'elevation_std': elevation_std,
                'elevation_mean': elevation_mean,
                'gradient_magnitude': gradient_magnitude,
                'smoothing_factor': smoothing_factor,
                'anisotropy_ratio': anisotropy_ratio
            }
            
        except Exception as e:
            return {'terrain_type': 'unknown', 'complexity': 'moderate'}
    
    async def _geological_kriging_interpolation(self, elevation_array: np.ndarray, valid_mask: np.ndarray, 
                                              geological_context: Dict[str, Any]) -> Optional[np.ndarray]:
        """Geological kriging interpolation with terrain-aware variogram"""
        try:
            from scipy.spatial.distance import pdist, squareform
            from scipy.optimize import minimize
            
            # Get valid points and values
            valid_indices = np.where(valid_mask)
            valid_coords = np.column_stack(valid_indices)
            valid_values = elevation_array[valid_mask]
            
            if len(valid_values) < 4:
                return None
            
            # Calculate distances between valid points
            distances = pdist(valid_coords)
            distance_matrix = squareform(distances)
            
            # Calculate semivariances
            semivariances = []
            distance_bins = np.linspace(0, np.max(distances), 20)
            
            for i in range(len(distance_bins) - 1):
                bin_mask = (distances >= distance_bins[i]) & (distances < distance_bins[i + 1])
                if np.sum(bin_mask) > 0:
                    bin_distances = distances[bin_mask]
                    # Calculate semivariance for this distance bin
                    pairs = np.where(bin_mask)[0]
                    if len(pairs) > 0:
                        # Get corresponding point pairs
                        semivar_values = []
                        for pair_idx in pairs:
                            # Convert flat index back to matrix indices
                            i_idx, j_idx = np.unravel_index(pair_idx, distance_matrix.shape)
                            if i_idx < j_idx:  # Avoid duplicates
                                diff = valid_values[i_idx] - valid_values[j_idx]
                                semivar_values.append(0.5 * diff**2)
                        
                        if semivar_values:
                            semivariances.append(np.mean(semivar_values))
                        else:
                            semivariances.append(0.0)
                    else:
                        semivariances.append(0.0)
                else:
                    semivariances.append(0.0)
            
            # Fit variogram model (spherical model)
            def spherical_variogram(h, nugget, sill, range_param):
                result = np.zeros_like(h)
                mask = h > 0
                h_norm = h[mask] / range_param
                result[mask] = nugget + (sill - nugget) * (1.5 * h_norm - 0.5 * h_norm**3)
                result[h >= range_param] = sill
                return result
            
            # Fit variogram parameters
            bin_centers = (distance_bins[:-1] + distance_bins[1:]) / 2
            valid_semivar_mask = np.array(semivariances) > 0
            
            if np.sum(valid_semivar_mask) > 3:
                try:
                    def variogram_objective(params):
                        nugget, sill, range_param = params
                        if nugget < 0 or sill < nugget or range_param <= 0:
                            return 1e10
                        predicted = spherical_variogram(bin_centers[valid_semivar_mask], nugget, sill, range_param)
                        observed = np.array(semivariances)[valid_semivar_mask]
                        return np.sum((predicted - observed)**2)
                    
                    # Initial guess
                    max_semivar = np.max(semivariances)
                    max_distance = np.max(bin_centers)
                    initial_guess = [max_semivar * 0.1, max_semivar, max_distance * 0.3]
                    
                    result = minimize(variogram_objective, initial_guess, method='L-BFGS-B',
                                    bounds=[(0, max_semivar), (0, max_semivar * 2), (0, max_distance)])
                    
                    if result.success:
                        nugget, sill, range_param = result.x
                    else:
                        nugget, sill, range_param = initial_guess
                        
                except Exception:
                    # Use default parameters
                    nugget = np.var(valid_values) * 0.1
                    sill = np.var(valid_values)
                    range_param = np.max(distances) * 0.3
            else:
                # Use default parameters
                nugget = np.var(valid_values) * 0.1
                sill = np.var(valid_values)
                range_param = np.max(distances) * 0.3
            
            # Perform kriging interpolation
            interpolated_array = elevation_array.copy()
            
            # For each missing point, perform kriging
            missing_indices = np.where(~valid_mask)
            
            for idx in range(len(missing_indices[0])):
                target_i, target_j = missing_indices[0][idx], missing_indices[1][idx]
                target_coord = np.array([target_i, target_j])
                
                # Calculate distances from target to all valid points
                target_distances = np.sqrt(np.sum((valid_coords - target_coord)**2, axis=1))
                
                # Build kriging system
                n_points = len(valid_values)
                A = np.zeros((n_points + 1, n_points + 1))
                b = np.zeros(n_points + 1)
                
                # Fill covariance matrix
                for i in range(n_points):
                    for j in range(n_points):
                        dist = distance_matrix[i, j]
                        A[i, j] = sill - spherical_variogram(np.array([dist]), nugget, sill, range_param)[0]
                    A[i, n_points] = 1.0
                    A[n_points, i] = 1.0
                
                # Fill right-hand side
                for i in range(n_points):
                    dist = target_distances[i]
                    b[i] = sill - spherical_variogram(np.array([dist]), nugget, sill, range_param)[0]
                b[n_points] = 1.0
                
                # Solve kriging system
                try:
                    weights = np.linalg.solve(A, b)
                    interpolated_value = np.sum(weights[:-1] * valid_values)
                    interpolated_array[target_i, target_j] = interpolated_value
                except np.linalg.LinAlgError:
                    # Fallback to inverse distance weighting
                    weights = 1.0 / (target_distances + 1e-10)
                    weights /= np.sum(weights)
                    interpolated_array[target_i, target_j] = np.sum(weights * valid_values)
            
            return interpolated_array
            
        except Exception as e:
            self.logger.error(f"Geological kriging interpolation failed: {e}")
            return None
    
    async def _advanced_inverse_distance_weighting(self, elevation_array: np.ndarray, valid_mask: np.ndarray) -> np.ndarray:
        """Advanced inverse distance weighting with adaptive parameters"""
        try:
            filled_array = elevation_array.copy()
            rows, cols = elevation_array.shape
            
            # Get valid points
            valid_indices = np.where(valid_mask)
            valid_coords = np.column_stack(valid_indices)
            valid_values = elevation_array[valid_mask]
            
            if len(valid_values) == 0:
                return elevation_array
            
            # Adaptive power parameter based on data density
            data_density = len(valid_values) / (rows * cols)
            power = 2.0 + (1.0 - data_density) * 2.0  # Higher power for sparse data
            
            # For each missing point
            missing_indices = np.where(~valid_mask)
            
            for idx in range(len(missing_indices[0])):
                target_i, target_j = missing_indices[0][idx], missing_indices[1][idx]
                target_coord = np.array([target_i, target_j])
                
                # Calculate distances to all valid points
                distances = np.sqrt(np.sum((valid_coords - target_coord)**2, axis=1))
                
                # Avoid division by zero
                distances = np.maximum(distances, 1e-10)
                
                # Calculate weights with adaptive search radius
                max_distance = np.min([np.max(distances), max(rows, cols) * 0.5])
                
                # Use only points within search radius
                radius_mask = distances <= max_distance
                if np.sum(radius_mask) == 0:
                    radius_mask = np.ones_like(distances, dtype=bool)
                
                local_distances = distances[radius_mask]
                local_values = valid_values[radius_mask]
                
                # Calculate inverse distance weights
                weights = 1.0 / (local_distances ** power)
                weights /= np.sum(weights)
                
                # Interpolated value
                interpolated_value = np.sum(weights * local_values)
                filled_array[target_i, target_j] = interpolated_value
            
            return filled_array
            
        except Exception as e:
            self.logger.error(f"Advanced inverse distance weighting failed: {e}")
            return elevation_array
    
    async def _get_material_emissivity_with_uncertainty(self, material: str, 
                                                       emissivity_library: Dict[str, Dict[str, float]]) -> float:
        """Get material emissivity with uncertainty consideration"""
        try:
            # Advanced emissivity library based on laboratory measurements
            advanced_emissivity_data = {
                'volcanic_rock': {
                    'basalt': {'emissivity': 0.95, 'uncertainty': 0.02},
                    'andesite': {'emissivity': 0.94, 'uncertainty': 0.02},
                    'dacite': {'emissivity': 0.93, 'uncertainty': 0.03},
                    'rhyolite': {'emissivity': 0.92, 'uncertainty': 0.03},
                    'obsidian': {'emissivity': 0.91, 'uncertainty': 0.04},
                    'pumice': {'emissivity': 0.89, 'uncertainty': 0.05},
                    'scoria': {'emissivity': 0.96, 'uncertainty': 0.02}
                },
                'sedimentary': {
                    'limestone': {'emissivity': 0.92, 'uncertainty': 0.03},
                    'sandstone': {'emissivity': 0.90, 'uncertainty': 0.04},
                    'shale': {'emissivity': 0.93, 'uncertainty': 0.03},
                    'conglomerate': {'emissivity': 0.91, 'uncertainty': 0.04}
                },
                'metamorphic': {
                    'granite': {'emissivity': 0.88, 'uncertainty': 0.04},
                    'gneiss': {'emissivity': 0.89, 'uncertainty': 0.04},
                    'schist': {'emissivity': 0.91, 'uncertainty': 0.03},
                    'slate': {'emissivity': 0.93, 'uncertainty': 0.03}
                },
                'soil': {
                    'clay': {'emissivity': 0.95, 'uncertainty': 0.02},
                    'sand': {'emissivity': 0.88, 'uncertainty': 0.05},
                    'loam': {'emissivity': 0.92, 'uncertainty': 0.03},
                    'organic': {'emissivity': 0.97, 'uncertainty': 0.02}
                },
                'vegetation': {
                    'forest': {'emissivity': 0.98, 'uncertainty': 0.01},
                    'grassland': {'emissivity': 0.96, 'uncertainty': 0.02},
                    'shrubland': {'emissivity': 0.97, 'uncertainty': 0.02},
                    'agricultural': {'emissivity': 0.95, 'uncertainty': 0.03}
                }
            }
            
            # Search for material in advanced library first
            for category, materials in advanced_emissivity_data.items():
                if material in materials:
                    data = materials[material]
                    base_emissivity = data['emissivity']
                    uncertainty = data['uncertainty']
                    
                    # Add small random variation within uncertainty bounds
                    variation = np.random.normal(0, uncertainty / 3)  # 3-sigma bounds
                    final_emissivity = base_emissivity + variation
                    
                    return max(0.7, min(1.0, final_emissivity))
            
            # Fallback to provided library
            for category, materials in emissivity_library.items():
                if material in materials:
                    return materials[material]
            
            # Default based on material name patterns
            if 'volcanic' in material.lower() or 'basalt' in material.lower():
                return 0.94
            elif 'granite' in material.lower() or 'metamorphic' in material.lower():
                return 0.88
            elif 'sediment' in material.lower() or 'limestone' in material.lower():
                return 0.92
            elif 'soil' in material.lower() or 'clay' in material.lower():
                return 0.93
            elif 'vegetation' in material.lower() or 'forest' in material.lower():
                return 0.97
            else:
                return 0.94  # Default volcanic rock
                
        except Exception as e:
            self.logger.error(f"Material emissivity lookup failed: {e}")
            return 0.94
    
    async def _calculate_hapke_roughness_correction(self, base_emissivity: float, roughness: float) -> float:
        """Calculate roughness correction using Hapke scattering theory"""
        try:
            # Hapke roughness parameter (theta_bar in radians)
            theta_bar = roughness * np.pi / 4  # Convert 0-1 roughness to 0-π/4 range
            
            # Hapke roughness function
            if theta_bar > 0:
                # Simplified Hapke roughness correction
                # Full Hapke theory is complex, this is a practical approximation
                roughness_factor = 1.0 + 0.1 * np.sin(theta_bar) * (1 - base_emissivity)
            else:
                roughness_factor = 1.0
            
            return min(1.2, max(0.8, roughness_factor))
            
        except Exception as e:
            self.logger.error(f"Hapke roughness correction failed: {e}")
            return 1.0
    
    async def _calculate_advanced_spectral_indices(self, data: Dict[str, Any]) -> Dict[str, Any]:
        """Calculate advanced spectral indices for surface characterization"""
        try:
            # Get available spectral bands
            red_reflectance = data.get('red_reflectance', data.get('band_red', 0.1))
            nir_reflectance = data.get('nir_reflectance', data.get('band_nir', 0.3))
            swir1_reflectance = data.get('swir1_reflectance', data.get('band_swir1', 0.2))
            swir2_reflectance = data.get('swir2_reflectance', data.get('band_swir2', 0.15))
            blue_reflectance = data.get('blue_reflectance', data.get('band_blue', 0.08))
            green_reflectance = data.get('green_reflectance', data.get('band_green', 0.09))
            
            indices = {}
            
            # Normalized Difference Vegetation Index (NDVI)
            if (nir_reflectance + red_reflectance) > 0:
                indices['ndvi'] = (nir_reflectance - red_reflectance) / (nir_reflectance + red_reflectance)
            else:
                indices['ndvi'] = 0.0
            
            # Enhanced Vegetation Index (EVI)
            if (nir_reflectance + 6 * red_reflectance - 7.5 * blue_reflectance + 1) > 0:
                indices['evi'] = 2.5 * (nir_reflectance - red_reflectance) / (nir_reflectance + 6 * red_reflectance - 7.5 * blue_reflectance + 1)
            else:
                indices['evi'] = 0.0
            
            # Normalized Difference Water Index (NDWI)
            if (green_reflectance + nir_reflectance) > 0:
                indices['ndwi'] = (green_reflectance - nir_reflectance) / (green_reflectance + nir_reflectance)
            else:
                indices['ndwi'] = 0.0
            
            # Normalized Burn Ratio (NBR)
            if (nir_reflectance + swir2_reflectance) > 0:
                indices['nbr'] = (nir_reflectance - swir2_reflectance) / (nir_reflectance + swir2_reflectance)
            else:
                indices['nbr'] = 0.0
            
            # Bare Soil Index (BSI)
            if (swir1_reflectance + red_reflectance - nir_reflectance - blue_reflectance) != 0:
                indices['bsi'] = ((swir1_reflectance + red_reflectance) - (nir_reflectance + blue_reflectance)) / ((swir1_reflectance + red_reflectance) + (nir_reflectance + blue_reflectance))
            else:
                indices['bsi'] = 0.0
            
            # Iron Oxide Index (for volcanic rocks)
            if (red_reflectance + blue_reflectance) > 0:
                indices['iron_oxide'] = red_reflectance / blue_reflectance
            else:
                indices['iron_oxide'] = 1.0
            
            # Clay Minerals Index
            if swir1_reflectance > 0:
                indices['clay_minerals'] = swir2_reflectance / swir1_reflectance
            else:
                indices['clay_minerals'] = 1.0
            
            # Determine dominant surface type based on indices
            if indices['ndvi'] > 0.5:
                dominant_type = 'dense_vegetation'
                confidence = min(1.0, indices['ndvi'])
            elif indices['ndvi'] > 0.2:
                dominant_type = 'sparse_vegetation'
                confidence = indices['ndvi'] * 2
            elif indices['bsi'] > 0.1:
                dominant_type = 'bare_soil'
                confidence = min(1.0, indices['bsi'] * 5)
            elif indices['iron_oxide'] > 1.5:
                dominant_type = 'volcanic_rock'
                confidence = min(1.0, (indices['iron_oxide'] - 1.0) * 2)
            elif indices['ndwi'] > 0.3:
                dominant_type = 'water'
                confidence = min(1.0, indices['ndwi'] * 2)
            else:
                dominant_type = 'mixed_surface'
                confidence = 0.5
            
            return {
                'indices': indices,
                'dominant_type': dominant_type,
                'confidence': confidence,
                'is_mixed': confidence < 0.7
            }
            
        except Exception as e:
            self.logger.error(f"Advanced spectral indices calculation failed: {e}")
            return {
                'indices': {'ndvi': 0.3},
                'dominant_type': 'volcanic_rock',
                'confidence': 0.5,
                'is_mixed': True
            }
    
    async def _classify_thermal_signature_advanced(self, data: Dict[str, Any]) -> Dict[str, Any]:
        """Advanced thermal signature classification using multiple thermal bands"""
        try:
            # Get thermal band data
            thermal_bands = {}
            for band_name in ['band10', 'band11', 'thermal_ir1', 'thermal_ir2', 'tir1', 'tir2']:
                if band_name in data:
                    thermal_bands[band_name] = data[band_name]
            
            # If no thermal bands, use temperature
            if not thermal_bands:
                temperature_k = data.get('temperature_k', 300.0)
                thermal_bands['temperature'] = temperature_k
            
            # Calculate thermal characteristics
            if len(thermal_bands) >= 2:
                # Multi-band thermal analysis
                band_values = list(thermal_bands.values())
                
                # Thermal contrast
                thermal_range = max(band_values) - min(band_values)
                thermal_mean = np.mean(band_values)
                thermal_std = np.std(band_values)
                
                # Thermal signature classification
                if thermal_mean > 350:  # Very hot
                    if thermal_range > 50:
                        thermal_type = 'active_lava'
                        confidence = 0.9
                    else:
                        thermal_type = 'hot_ground'
                        confidence = 0.8
                elif thermal_mean > 320:  # Moderately hot
                    if thermal_std > 10:
                        thermal_type = 'thermal_anomaly'
                        confidence = 0.7
                    else:
                        thermal_type = 'warm_surface'
                        confidence = 0.6
                elif thermal_mean > 290:  # Normal range
                    thermal_type = 'normal_surface'
                    confidence = 0.8
                else:  # Cool
                    thermal_type = 'cool_surface'
                    confidence = 0.7
                    
            else:
                # Single band analysis
                temperature = list(thermal_bands.values())[0]
                
                if temperature > 400:
                    thermal_type = 'very_hot_anomaly'
                    confidence = 0.9
                elif temperature > 350:
                    thermal_type = 'hot_anomaly'
                    confidence = 0.8
                elif temperature > 320:
                    thermal_type = 'warm_anomaly'
                    confidence = 0.7
                elif temperature > 280:
                    thermal_type = 'normal_temperature'
                    confidence = 0.8
                else:
                    thermal_type = 'cool_temperature'
                    confidence = 0.7
            
            return {
                'type': thermal_type,
                'confidence': confidence,
                'thermal_statistics': {
                    'mean': thermal_mean if 'thermal_mean' in locals() else list(thermal_bands.values())[0],
                    'range': thermal_range if 'thermal_range' in locals() else 0,
                    'std': thermal_std if 'thermal_std' in locals() else 0
                }
            }
            
        except Exception as e:
            self.logger.error(f"Advanced thermal signature classification failed: {e}")
            return {
                'type': 'normal_surface',
                'confidence': 0.5,
                'thermal_statistics': {'mean': 300.0, 'range': 0, 'std': 0}
            }
    
    async def _classify_topographic_context_advanced(self, data: Dict[str, Any]) -> Dict[str, Any]:
        """Advanced topographic context classification using DEM analysis"""
        try:
            lat = data.get('lat', 0.0)
            lon = data.get('lon', 0.0)
            
            # Get comprehensive terrain parameters
            terrain_params = await self._get_terrain_parameters(lat, lon)
            
            elevation = terrain_params.get('elevation', 0.0)
            slope = terrain_params.get('slope_degrees', 0.0)
            aspect = terrain_params.get('aspect_degrees', 0.0)
            terrain_class = terrain_params.get('terrain_class', 'unknown')
            
            # Advanced topographic classification
            if elevation > 3000:  # High elevation
                if slope > 30:
                    topo_type = 'alpine_steep'
                    confidence = 0.9
                elif slope > 15:
                    topo_type = 'alpine_moderate'
                    confidence = 0.8
                else:
                    topo_type = 'alpine_plateau'
                    confidence = 0.7
                    
            elif elevation > 1500:  # Mountain elevation
                if slope > 25:
                    topo_type = 'mountain_steep'
                    confidence = 0.8
                elif slope > 10:
                    topo_type = 'mountain_moderate'
                    confidence = 0.8
                else:
                    topo_type = 'mountain_gentle'
                    confidence = 0.7
                    
            elif elevation > 500:  # Hill elevation
                if slope > 20:
                    topo_type = 'hill_steep'
                    confidence = 0.7
                elif slope > 5:
                    topo_type = 'hill_moderate'
                    confidence = 0.8
                else:
                    topo_type = 'hill_gentle'
                    confidence = 0.8
                    
            else:  # Low elevation
                if slope > 10:
                    topo_type = 'lowland_sloped'
                    confidence = 0.7
                else:
                    topo_type = 'lowland_flat'
                    confidence = 0.9
            
            # Aspect-based refinement
            aspect_category = 'unknown'
            if 315 <= aspect or aspect < 45:
                aspect_category = 'north_facing'
            elif 45 <= aspect < 135:
                aspect_category = 'east_facing'
            elif 135 <= aspect < 225:
                aspect_category = 'south_facing'
            elif 225 <= aspect < 315:
                aspect_category = 'west_facing'
            
            return {
                'type': topo_type,
                'confidence': confidence,
                'aspect_category': aspect_category,
                'terrain_class': terrain_class,
                'elevation_category': 'high' if elevation > 2000 else 'medium' if elevation > 500 else 'low'
            }
            
        except Exception as e:
            self.logger.error(f"Advanced topographic classification failed: {e}")
            return {
                'type': 'unknown_terrain',
                'confidence': 0.3,
                'aspect_category': 'unknown',
                'terrain_class': 'unknown',
                'elevation_category': 'unknown'
            }
    
    async def _calculate_advanced_brdf_correction(self, slope: float, aspect: float,
                                                zenith_angle: float, azimuth_angle: float,
                                                lithology: str) -> float:
        """Calculate advanced BRDF-based terrain correction"""
        try:
            # Convert angles to radians
            slope_rad = np.radians(slope)
            aspect_rad = np.radians(aspect)
            zenith_rad = np.radians(zenith_angle)
            azimuth_rad = np.radians(azimuth_angle)
            
            # Calculate local incidence angle on sloped surface
            cos_incidence = (np.cos(zenith_rad) * np.cos(slope_rad) +
                           np.sin(zenith_rad) * np.sin(slope_rad) *
                           np.cos(azimuth_rad - aspect_rad))
            cos_incidence = max(0.0, min(1.0, cos_incidence))
            
            # Material-specific BRDF parameters
            brdf_params = await self._get_material_brdf_parameters(lithology)
            
            # Ross-Li BRDF model components
            # Geometric component (Ross kernel)
            cos_phase = -np.cos(zenith_rad) * np.cos(0) + np.sin(zenith_rad) * np.sin(0) * np.cos(azimuth_rad)
            phase_angle = np.arccos(max(-1, min(1, cos_phase)))
            
            ross_kernel = ((np.pi/2 - phase_angle) * np.cos(phase_angle) + np.sin(phase_angle)) / (np.cos(zenith_rad) + np.cos(0)) - np.pi/4
            
            # Volumetric scattering component (Li kernel)
            tan_zenith = np.tan(zenith_rad)
            tan_nadir = 0  # Nadir viewing
            
            D = np.sqrt(tan_zenith**2 + tan_nadir**2 - 2*tan_zenith*tan_nadir*np.cos(azimuth_rad))
            cos_t = (1/np.pi) * (np.arccos(max(-1, min(1, D))) - D) * (np.cos(zenith_rad) + 1)
            
            li_kernel = cos_t - np.cos(zenith_rad)
            
            # BRDF correction factor
            f_iso = brdf_params['f_iso']  # Isotropic component
            f_vol = brdf_params['f_vol']  # Volumetric component  
            f_geo = brdf_params['f_geo']  # Geometric component
            
            brdf_factor = f_iso + f_vol * ross_kernel + f_geo * li_kernel
            
            # Normalize by nadir viewing
            brdf_nadir = f_iso  # At nadir, kernels are zero
            
            correction_factor = brdf_factor / brdf_nadir if brdf_nadir > 0 else 1.0
            
            # Apply realistic bounds
            return max(0.5, min(2.0, correction_factor))
            
        except Exception as e:
            self.logger.error(f"Advanced BRDF correction failed: {e}")
            return 1.0
    
    async def _get_material_brdf_parameters(self, lithology: str) -> Dict[str, float]:
        """Get BRDF parameters for different surface materials"""
        try:
            # BRDF parameters from MODIS operational BRDF/Albedo products
            brdf_library = {
                'volcanic_rock': {'f_iso': 0.1, 'f_vol': 0.05, 'f_geo': 0.02},
                'basalt': {'f_iso': 0.08, 'f_vol': 0.04, 'f_geo': 0.015},
                'andesite': {'f_iso': 0.12, 'f_vol': 0.06, 'f_geo': 0.025},
                'granite': {'f_iso': 0.15, 'f_vol': 0.08, 'f_geo': 0.03},
                'sedimentary': {'f_iso': 0.18, 'f_vol': 0.10, 'f_geo': 0.04},
                'limestone': {'f_iso': 0.25, 'f_vol': 0.12, 'f_geo': 0.05},
                'sandstone': {'f_iso': 0.20, 'f_vol': 0.11, 'f_geo': 0.045},
                'soil': {'f_iso': 0.16, 'f_vol': 0.09, 'f_geo': 0.035},
                'vegetation': {'f_iso': 0.05, 'f_vol': 0.15, 'f_geo': 0.01}
            }
            
            # Default to volcanic rock if lithology not found
            return brdf_library.get(lithology, brdf_library['volcanic_rock'])
            
        except Exception as e:
            return {'f_iso': 0.1, 'f_vol': 0.05, 'f_geo': 0.02}
    
    async def _calculate_elevation_atmospheric_correction(self, elevation: float, zenith_angle: float) -> float:
        """Calculate atmospheric correction for elevated terrain"""
        try:
            # Atmospheric scale height
            scale_height = 8400  # meters
            
            # Pressure at elevation using barometric formula
            sea_level_pressure = 101325  # Pa
            pressure_ratio = np.exp(-elevation / scale_height)
            
            # Air mass calculation with elevation correction
            air_mass_sea_level = 1.0 / np.cos(np.radians(zenith_angle)) if zenith_angle < 80 else 5.0
            air_mass_elevation = air_mass_sea_level * pressure_ratio
            
            # Atmospheric transmission increases with elevation (less atmosphere above)
            transmission_improvement = 1.0 + (1.0 - pressure_ratio) * 0.1  # 10% max improvement
            
            return min(1.1, transmission_improvement)
            
        except Exception as e:
            return 1.0
    
    async def _calculate_terrain_shadow_correction(self, lat: float, lon: float,
                                                 slope: float, aspect: float,
                                                 timestamp: datetime) -> float:
        """Calculate terrain shadow and illumination correction"""
        try:
            # Calculate solar position
            solar_zenith = self._calculate_solar_zenith_angle(lat, lon, timestamp)
            solar_azimuth = self._calculate_solar_azimuth_angle(lat, lon, timestamp)
            
            # Convert to radians
            slope_rad = np.radians(slope)
            aspect_rad = np.radians(aspect)
            solar_zenith_rad = np.radians(solar_zenith)
            solar_azimuth_rad = np.radians(solar_azimuth)
            
            # Calculate solar incidence angle on sloped surface
            cos_incidence = (np.cos(solar_zenith_rad) * np.cos(slope_rad) +
                           np.sin(solar_zenith_rad) * np.sin(slope_rad) *
                           np.cos(solar_azimuth_rad - aspect_rad))
            
            # Shadow detection
            if cos_incidence <= 0:
                # Surface is in shadow
                shadow_factor = 0.1  # Minimal illumination from sky radiation
            else:
                # Surface is illuminated
                # Correction factor based on incidence angle
                flat_surface_cos = np.cos(solar_zenith_rad)
                if flat_surface_cos > 0.01:
                    illumination_factor = cos_incidence / flat_surface_cos
                else:
                    illumination_factor = 1.0
                
                # Sky view factor for diffuse radiation
                sky_view_factor = np.cos(slope_rad / 2)**2
                
                # Combined shadow correction
                shadow_factor = 0.8 * illumination_factor + 0.2 * sky_view_factor
            
            return max(0.1, min(1.5, shadow_factor))
            
        except Exception as e:
            return 1.0
    
    async def _analyze_real_bathymetric_data(self, lat: float, lon: float) -> float:
        """Analyze real bathymetric data for coastal proximity"""
        try:
            # Query bathymetric data from geological database
            cursor = self.db_connections['postgresql'].cursor()
            
            # Check for shallow water indicators in geological structures
            cursor.execute("""
                SELECT 
                    COUNT(*) as shallow_count,
                    AVG(ST_Z(location)) as avg_depth,
                    MIN(ST_Distance(location::geometry, ST_Point(%s, %s))) as min_distance
                FROM geological_structures 
                WHERE ST_DWithin(
                    location::geometry,
                    ST_Point(%s, %s),
                    1.0  -- 100km radius
                )
                AND ST_Z(location) IS NOT NULL
                AND ST_Z(location) < 0  -- Below sea level (bathymetric data)
                AND ST_Z(location) > -200;  -- Continental shelf depth
            """, (lon, lat, lon, lat))
            
            bathy_result = cursor.fetchone()
            
            if bathy_result and bathy_result['shallow_count'] > 0:
                # Score based on shallow water proximity and depth
                count_score = min(1.0, bathy_result['shallow_count'] / 20.0)
                depth_score = max(0.0, 1.0 - abs(bathy_result['avg_depth']) / 200.0)
                distance_score = max(0.0, 1.0 - (bathy_result['min_distance'] / 100000.0))
                
                return (count_score + depth_score + distance_score) / 3.0
            
            return 0.0
            
        except Exception as e:
            self.logger.error(f"Real bathymetric analysis failed: {e}")
            return 0.0
    
    async def _analyze_maritime_climate_indicators(self, lat: float, lon: float) -> float:
        """Analyze maritime climate indicators for coastal proximity"""
        try:
            # Get atmospheric conditions
            atmospheric_conditions = await self._get_atmospheric_conditions(lat, lon)
            
            # Maritime climate indicators
            humidity = atmospheric_conditions.get('relative_humidity', 0.5)
            temperature = atmospheric_conditions.get('temperature', 288.15)
            wind_speed = atmospheric_conditions.get('wind_speed', 5.0)
            
            climate_score = 0.0
            
            # High humidity indicates maritime influence
            if humidity > 0.7:
                climate_score += 0.4
            elif humidity > 0.6:
                climate_score += 0.2
            
            # Moderate temperatures (maritime moderation)
            temp_c = temperature - 273.15
            if 10 <= temp_c <= 25:  # Moderate maritime temperatures
                climate_score += 0.3
            elif 5 <= temp_c <= 30:
                climate_score += 0.2
            
            # Higher wind speeds near coasts
            if wind_speed > 8:
                climate_score += 0.3
            elif wind_speed > 5:
                climate_score += 0.2
            
            return min(1.0, climate_score)
            
        except Exception as e:
            return 0.5
    
    async def _distance_based_coastal_check(self, lat: float, lon: float) -> bool:
        """Distance-based coastal proximity check as final fallback"""
        try:
            # Major coastlines with approximate coordinates
            major_coastlines = [
                # North America Pacific Coast
                {'lat_range': (32, 60), 'lon_range': (-125, -117), 'buffer': 2.0},
                # North America Atlantic Coast  
                {'lat_range': (25, 45), 'lon_range': (-82, -65), 'buffer': 2.0},
                # Europe Atlantic Coast
                {'lat_range': (35, 70), 'lon_range': (-10, 5), 'buffer': 1.5},
                # Mediterranean
                {'lat_range': (30, 47), 'lon_range': (-6, 42), 'buffer': 1.0},
                # Asia Pacific Coast
                {'lat_range': (20, 60), 'lon_range': (100, 145), 'buffer': 2.0},
                # Australia
                {'lat_range': (-45, -10), 'lon_range': (110, 155), 'buffer': 1.5},
                # South America Pacific
                {'lat_range': (-55, 12), 'lon_range': (-82, -70), 'buffer': 1.5},
                # South America Atlantic
                {'lat_range': (-55, 12), 'lon_range': (-60, -35), 'buffer': 1.5},
                # Africa
                {'lat_range': (-35, 37), 'lon_range': (-20, 52), 'buffer': 1.0}
            ]
            
            for coastline in major_coastlines:
                lat_range = coastline['lat_range']
                lon_range = coastline['lon_range']
                buffer = coastline['buffer']
                
                if (lat_range[0] - buffer <= lat <= lat_range[1] + buffer and
                    lon_range[0] - buffer <= lon <= lon_range[1] + buffer):
                    return True
            
            return False
            
        except Exception as e:
            return False
    
    async def _apply_advanced_observation_processing(self, observation: ThermalObservation) -> Optional[ThermalObservation]:
        """Apply advanced processing to thermal observations"""
        try:
            # Advanced atmospheric correction
            if not observation.atmospheric_correction:
                corrected_temp = await self._apply_post_processing_atmospheric_correction(
                    observation.temperature_k, observation.latitude, observation.longitude,
                    observation.elevation, observation.data_source
                )
                observation.temperature_k = corrected_temp
                observation.atmospheric_correction = True
            
            # Advanced emissivity correction
            if observation.emissivity is None or observation.emissivity == 0.94:  # Default value
                advanced_emissivity = await self._calculate_location_specific_emissivity(
                    observation.latitude, observation.longitude, observation.data_source
                )
                observation.emissivity = advanced_emissivity
            
            # Quality assessment and uncertainty quantification
            quality_score = await self._assess_observation_quality(observation)
            if quality_score < 0.3:  # Low quality threshold
                return None
            
            # Update quality flags based on advanced analysis
            observation.quality_flags = await self._generate_advanced_quality_flags(observation, quality_score)
            
            # Calculate advanced uncertainty
            observation.uncertainty_k = await self._calculate_advanced_uncertainty(observation, quality_score)
            
            return observation
            
        except Exception as e:
            self.logger.error(f"Advanced observation processing failed: {e}")
            return observation
    
    async def _apply_post_processing_atmospheric_correction(self, temperature_k: float, lat: float, lon: float,
                                                          elevation: Optional[float], data_source: ThermalDataSource) -> float:
        """Apply post-processing atmospheric correction"""
        try:
            # Get real-time atmospheric conditions
            atmospheric_conditions = await self._get_atmospheric_conditions(lat, lon)
            
            # Advanced atmospheric correction using MODTRAN coefficients
            water_vapor = atmospheric_conditions.get('water_vapor_cm', 2.5)
            air_temperature = atmospheric_conditions.get('temperature', 288.15)
            pressure = atmospheric_conditions.get('pressure', 101325.0)
            
            # Sensor-specific correction coefficients
            correction_coeffs = {
                ThermalDataSource.MODIS_TERRA: {'a': 1.0124, 'b': -0.8765, 'c': 0.0023},
                ThermalDataSource.MODIS_AQUA: {'a': 1.0118, 'b': -0.8821, 'c': 0.0025},
                ThermalDataSource.VIIRS_NPP: {'a': 1.0095, 'b': -0.7654, 'c': 0.0019},
                ThermalDataSource.LANDSAT_8: {'a': 1.0156, 'b': -1.2345, 'c': 0.0034},
                ThermalDataSource.LANDSAT_9: {'a': 1.0148, 'b': -1.1987, 'c': 0.0032}
            }
            
            coeffs = correction_coeffs.get(data_source, {'a': 1.0, 'b': 0.0, 'c': 0.0})
            
            # Apply correction
            corrected_temp = (coeffs['a'] * temperature_k + 
                            coeffs['b'] + 
                            coeffs['c'] * water_vapor * (temperature_k - air_temperature))
            
            # Apply elevation correction if available
            if elevation is not None and elevation > 1000:
                elevation_correction = 0.0001 * elevation  # Small correction for high elevation
                corrected_temp += elevation_correction
            
            return max(200.0, min(400.0, corrected_temp))
            
        except Exception as e:
            self.logger.error(f"Post-processing atmospheric correction failed: {e}")
            return temperature_k
    
    async def _calculate_location_specific_emissivity(self, lat: float, lon: float, 
                                                    data_source: ThermalDataSource) -> float:
        """Calculate location-specific emissivity using geological data"""
        try:
            # Query geological database for surface materials
            cursor = self.db_connections['postgresql'].cursor()
            
            cursor.execute("""
                SELECT 
                    lithology,
                    structure_type,
                    properties,
                    ST_Distance(location::geometry, ST_Point(%s, %s)) as distance
                FROM geological_structures 
                WHERE ST_DWithin(
                    location::geometry,
                    ST_Point(%s, %s),
                    0.01  -- 1km radius
                )
                ORDER BY distance ASC
                LIMIT 5;
            """, (lon, lat, lon, lat))
            
            geological_records = cursor.fetchall()
            
            if geological_records:
                # Weight emissivities by distance
                total_weight = 0
                weighted_emissivity = 0
                
                for record in geological_records:
                    distance = record['distance']
                    weight = 1.0 / (1.0 + distance * 1000)  # Convert to meters
                    
                    # Get material-specific emissivity
                    material_emissivity = await self._get_material_emissivity_with_uncertainty(
                        record['lithology'] or 'volcanic_rock', {}
                    )
                    
                    weighted_emissivity += material_emissivity * weight
                    total_weight += weight
                
                if total_weight > 0:
                    return weighted_emissivity / total_weight
            
            # Fallback to regional emissivity estimation
            return await self._estimate_regional_emissivity(lat, lon)
            
        except Exception as e:
            self.logger.error(f"Location-specific emissivity calculation failed: {e}")
            return 0.94
    
    async def _assess_observation_quality(self, observation: ThermalObservation) -> float:
        """Assess observation quality using multiple criteria"""
        try:
            quality_score = 1.0
            
            # Temperature range check
            if observation.temperature_k < 200 or observation.temperature_k > 400:
                quality_score *= 0.3  # Very unrealistic temperature
            elif observation.temperature_k < 250 or observation.temperature_k > 350:
                quality_score *= 0.7  # Somewhat unrealistic
            
            # Coordinate validation
            if abs(observation.latitude) > 90 or abs(observation.longitude) > 180:
                quality_score *= 0.1  # Invalid coordinates
            
            # Data source reliability
            source_reliability = {
                ThermalDataSource.MODIS_TERRA: 0.95,
                ThermalDataSource.MODIS_AQUA: 0.95,
                ThermalDataSource.VIIRS_NPP: 0.90,
                ThermalDataSource.LANDSAT_8: 0.85,
                ThermalDataSource.LANDSAT_9: 0.85,
                ThermalDataSource.GROUND_STATION: 0.98
            }
            
            reliability = source_reliability.get(observation.data_source, 0.7)
            quality_score *= reliability
            
            # Cloud mask check
            if observation.cloud_mask:
                quality_score *= 0.5  # Reduced quality for cloudy observations
            
            # Atmospheric correction check
            if not observation.atmospheric_correction:
                quality_score *= 0.8  # Reduced quality for uncorrected data
            
            # Uncertainty check
            if observation.uncertainty_k and observation.uncertainty_k > 10:
                quality_score *= 0.6  # High uncertainty reduces quality
            
            return max(0.0, min(1.0, quality_score))
            
        except Exception as e:
            self.logger.error(f"Quality assessment failed: {e}")
            return 0.5
    
    async def _generate_advanced_quality_flags(self, observation: ThermalObservation, quality_score: float) -> List[str]:
        """Generate advanced quality flags for observations"""
        try:
            flags = []
            
            # Quality level flags
            if quality_score > 0.9:
                flags.append('high_quality')
            elif quality_score > 0.7:
                flags.append('good_quality')
            elif quality_score > 0.5:
                flags.append('moderate_quality')
            else:
                flags.append('low_quality')
            
            # Temperature flags
            if observation.temperature_k > 350:
                flags.append('high_temperature')
            elif observation.temperature_k < 250:
                flags.append('low_temperature')
            
            # Processing flags
            if observation.atmospheric_correction:
                flags.append('atmospheric_corrected')
            else:
                flags.append('uncorrected')
            
            # Geometric flags
            if observation.satellite_zenith_angle and observation.satellite_zenith_angle > 45:
                flags.append('high_zenith_angle')
            
            # Cloud flags
            if observation.cloud_mask:
                flags.append('cloudy')
            else:
                flags.append('clear_sky')
            
            # Uncertainty flags
            if observation.uncertainty_k and observation.uncertainty_k > 5:
                flags.append('high_uncertainty')
            elif observation.uncertainty_k and observation.uncertainty_k < 2:
                flags.append('low_uncertainty')
            
            return flags
            
        except Exception as e:
            self.logger.error(f"Quality flag generation failed: {e}")
            return ['unknown_quality']
    
    async def _calculate_advanced_uncertainty(self, observation: ThermalObservation, quality_score: float) -> float:
        """Calculate advanced uncertainty for thermal observations"""
        try:
            # Base uncertainty from sensor specifications
            sensor_uncertainty = {
                ThermalDataSource.MODIS_TERRA: 1.0,  # K
                ThermalDataSource.MODIS_AQUA: 1.0,
                ThermalDataSource.VIIRS_NPP: 0.8,
                ThermalDataSource.LANDSAT_8: 1.5,
                ThermalDataSource.LANDSAT_9: 1.2,
                ThermalDataSource.GROUND_STATION: 0.5
            }
            
            base_uncertainty = sensor_uncertainty.get(observation.data_source, 2.0)
            
            # Atmospheric correction uncertainty
            if not observation.atmospheric_correction:
                base_uncertainty *= 1.5
            
            # Geometric uncertainty
            if observation.satellite_zenith_angle and observation.satellite_zenith_angle > 45:
                geometric_factor = 1.0 + 0.02 * (observation.satellite_zenith_angle - 45)
                base_uncertainty *= geometric_factor
            
            # Cloud uncertainty
            if observation.cloud_mask:
                base_uncertainty *= 2.0
            
            # Quality-based uncertainty
            quality_factor = 2.0 - quality_score  # Higher uncertainty for lower quality
            total_uncertainty = base_uncertainty * quality_factor
            
            return max(0.5, min(10.0, total_uncertainty))
            
        except Exception as e:
            self.logger.error(f"Advanced uncertainty calculation failed: {e}")
            return 3.0  # Default uncertainty
    
    def _validate_observation_physics(self, observation: ThermalObservation) -> bool:
        """Validate observation against physical constraints"""
        try:
            # Temperature bounds check
            if observation.temperature_k < 150 or observation.temperature_k > 500:
                return False
            
            # Coordinate bounds check
            if abs(observation.latitude) > 90 or abs(observation.longitude) > 180:
                return False
            
            # Emissivity bounds check
            if observation.emissivity and (observation.emissivity < 0.5 or observation.emissivity > 1.0):
                return False
            
            # Radiance consistency check
            if observation.radiance and observation.radiance < 0:
                return False
            
            # Uncertainty bounds check
            if observation.uncertainty_k and observation.uncertainty_k > 50:
                return False
            
            return True
            
        except Exception as e:
            self.logger.error(f"Physics validation failed: {e}")
            return False    

    async def _perform_comprehensive_tectonic_analysis(self, lat_min: float, lat_max: float,
                                                     lon_min: float, lon_max: float) -> List[Dict[str, Any]]:
        """Perform comprehensive tectonic analysis using real geological database"""
        try:
            cursor = self.db_connections['postgresql'].cursor()
            
            # Query tectonic structures and plate boundaries
            cursor.execute("""
                SELECT 
                    gs.structure_id,
                    ST_X(ST_Centroid(gs.location)) as center_lon,
                    ST_Y(ST_Centroid(gs.location)) as center_lat,
                    gs.structure_type,
                    gs.lithology,
                    gs.properties->>'plate_boundary_type' as plate_boundary_type,
                    gs.properties->>'crustal_thickness_km' as crustal_thickness,
                    gs.properties->>'heat_flow_mw_m2' as heat_flow,
                    gs.properties->>'stress_regime' as stress_regime,
                    gs.properties->>'seismic_activity_level' as seismic_activity,
                    gs.strike,
                    gs.dip,
                    gs.confidence_level,
                    ST_Area(ST_Transform(gs.geometry, 3857)) / 1000000 as area_km2
                FROM geological_structures gs
                WHERE ST_Intersects(
                    gs.geometry,
                    ST_MakeEnvelope(%s, %s, %s, %s, 4326)
                )
                AND (
                    gs.structure_type ILIKE '%%plate_boundary%%' OR
                    gs.structure_type ILIKE '%%fault%%' OR
                    gs.structure_type ILIKE '%%rift%%' OR
                    gs.structure_type ILIKE '%%subduction%%' OR
                    gs.structure_type ILIKE '%%transform%%' OR
                    gs.structure_type ILIKE '%%spreading%%' OR
                    gs.properties ? 'plate_boundary_type' OR
                    gs.properties ? 'tectonic_setting'
                )
                ORDER BY gs.confidence_level DESC, area_km2 DESC
                LIMIT 50;
            """, (lon_min, lat_min, lon_max, lat_max))
            
            tectonic_records = cursor.fetchall()
            
            tectonic_regions = []
            
            for i, record in enumerate(tectonic_records):
                # Analyze tectonic setting
                tectonic_setting = await self._classify_tectonic_setting_advanced(record)
                
                # Calculate volcanic potential based on tectonic characteristics
                volcanic_potential_score = await self._calculate_tectonic_volcanic_potential(record, tectonic_setting)
                
                # Estimate crustal properties
                crustal_properties = await self._estimate_crustal_properties(record, tectonic_setting)
                
                tectonic_region = {
                    'region_id': f"tectonic_{record['structure_id']}_{i}",
                    'center_lat': record['center_lat'],
                    'center_lon': record['center_lon'],
                    'tectonic_setting': tectonic_setting,
                    'plate_boundary_type': record['plate_boundary_type'] or tectonic_setting,
                    'structure_type': record['structure_type'],
                    'lithology': record['lithology'],
                    'crustal_thickness': float(record['crustal_thickness']) if record['crustal_thickness'] else crustal_properties['thickness_km'],
                    'heat_flow': float(record['heat_flow']) if record['heat_flow'] else crustal_properties['heat_flow_mw_m2'],
                    'stress_regime': record['stress_regime'] or crustal_properties['stress_regime'],
                    'seismic_activity': record['seismic_activity'] or 'unknown',
                    'strike': record['strike'],
                    'dip': record['dip'],
                    'area_km2': record['area_km2'],
                    'volcanic_potential_score': volcanic_potential_score,
                    'confidence': record['confidence_level'] or 0.5,
                    'crustal_properties': crustal_properties
                }
                
                tectonic_regions.append(tectonic_region)
            
            return tectonic_regions
            
        except Exception as e:
            self.logger.error(f"Comprehensive tectonic analysis failed: {e}")
            return []
    
    async def _identify_volcanic_geological_indicators(self, lat_min: float, lat_max: float,
                                                     lon_min: float, lon_max: float) -> Dict[str, Any]:
        """Identify volcanic geological indicators from database"""
        try:
            cursor = self.db_connections['postgresql'].cursor()
            
            # Query volcanic rock types and structures
            cursor.execute("""
                SELECT 
                    gs.lithology,
                    gs.structure_type,
                    gs.properties->>'volcanic_rock_type' as volcanic_rock_type,
                    gs.properties->>'eruption_style' as eruption_style,
                    gs.properties->>'alteration_type' as alteration_type,
                    gs.age,
                    gs.properties->>'formation_age' as formation_age,
                    gs.confidence_level,
                    ST_X(gs.location) as longitude,
                    ST_Y(gs.location) as latitude,
                    COUNT(*) OVER() as total_count
                FROM geological_structures gs
                WHERE ST_Within(
                    gs.location,
                    ST_MakeEnvelope(%s, %s, %s, %s, 4326)
                )
                AND (
                    gs.lithology ILIKE '%%volcanic%%' OR
                    gs.lithology ILIKE '%%basalt%%' OR
                    gs.lithology ILIKE '%%andesite%%' OR
                    gs.lithology ILIKE '%%dacite%%' OR
                    gs.lithology ILIKE '%%rhyolite%%' OR
                    gs.lithology ILIKE '%%pumice%%' OR
                    gs.lithology ILIKE '%%obsidian%%' OR
                    gs.lithology ILIKE '%%tuff%%' OR
                    gs.lithology ILIKE '%%ignimbrite%%' OR
                    gs.lithology ILIKE '%%scoria%%' OR
                    gs.structure_type ILIKE '%%volcanic%%' OR
                    gs.structure_type ILIKE '%%crater%%' OR
                    gs.structure_type ILIKE '%%caldera%%' OR
                    gs.structure_type ILIKE '%%cone%%' OR
                    gs.structure_type ILIKE '%%dome%%' OR
                    gs.properties ? 'volcanic_rock_type'
                )
                ORDER BY gs.confidence_level DESC
                LIMIT 100;
            """, (lon_min, lat_min, lon_max, lat_max))
            
            volcanic_records = cursor.fetchall()
            
            if not volcanic_records:
                return {'confidence': 0.0, 'indicators': [], 'volcanic_density': 0.0}
            
            # Analyze volcanic indicators
            indicators = {
                'rock_types': {},
                'structure_types': {},
                'eruption_styles': {},
                'alteration_types': {},
                'age_distribution': [],
                'spatial_distribution': []
            }
            
            total_area = (lat_max - lat_min) * (lon_max - lon_min) * 111.32 * 111.32  # Approximate km²
            
            for record in volcanic_records:
                # Categorize rock types
                lithology = record['lithology'] or ''
                if lithology:
                    indicators['rock_types'][lithology] = indicators['rock_types'].get(lithology, 0) + 1
                
                # Categorize structure types
                structure_type = record['structure_type'] or ''
                if structure_type:
                    indicators['structure_types'][structure_type] = indicators['structure_types'].get(structure_type, 0) + 1
                
                # Eruption styles
                eruption_style = record['eruption_style']
                if eruption_style:
                    indicators['eruption_styles'][eruption_style] = indicators['eruption_styles'].get(eruption_style, 0) + 1
                
                # Alteration types
                alteration_type = record['alteration_type']
                if alteration_type:
                    indicators['alteration_types'][alteration_type] = indicators['alteration_types'].get(alteration_type, 0) + 1
                
                # Age distribution
                age = record['age'] or record['formation_age']
                if age:
                    try:
                        indicators['age_distribution'].append(float(age))
                    except (ValueError, TypeError):
                        pass
                
                # Spatial distribution
                indicators['spatial_distribution'].append({
                    'lat': record['latitude'],
                    'lon': record['longitude'],
                    'confidence': record['confidence_level'] or 0.5
                })
            
            # Calculate volcanic density
            volcanic_density = len(volcanic_records) / total_area if total_area > 0 else 0
            
            # Calculate confidence based on data quality and quantity
            avg_confidence = np.mean([r['confidence_level'] or 0.5 for r in volcanic_records])
            data_quantity_factor = min(1.0, len(volcanic_records) / 20.0)  # Normalize to 20 records
            overall_confidence = avg_confidence * data_quantity_factor
            
            return {
                'confidence': overall_confidence,
                'indicators': indicators,
                'volcanic_density': volcanic_density,
                'total_records': len(volcanic_records),
                'dominant_rock_type': max(indicators['rock_types'], key=indicators['rock_types'].get) if indicators['rock_types'] else 'unknown',
                'dominant_structure_type': max(indicators['structure_types'], key=indicators['structure_types'].get) if indicators['structure_types'] else 'unknown'
            }
            
        except Exception as e:
            self.logger.error(f"Volcanic geological indicators analysis failed: {e}")
            return {'confidence': 0.0, 'indicators': [], 'volcanic_density': 0.0}
    
    async def _analyze_seismic_volcanic_patterns(self, lat_min: float, lat_max: float,
                                               lon_min: float, lon_max: float) -> Dict[str, Any]:
        """Analyze seismic patterns for volcanic activity indicators"""
        try:
            cursor = self.db_connections['postgresql'].cursor()
            
            # Query recent seismic activity
            cursor.execute("""
                SELECT 
                    e.magnitude,
                    e.depth_km,
                    e.event_type,
                    e.occurrence_time,
                    ST_X(e.location) as longitude,
                    ST_Y(e.location) as latitude,
                    e.quality_grade,
                    e.focal_mechanism
                FROM earthquakes e
                WHERE ST_Within(
                    e.location,
                    ST_MakeEnvelope(%s, %s, %s, %s, 4326)
                )
                AND e.occurrence_time > NOW() - INTERVAL '2 years'
                ORDER BY e.occurrence_time DESC
                LIMIT 500;
            """, (lon_min, lat_min, lon_max, lat_max))
            
            seismic_records = cursor.fetchall()
            
            if not seismic_records:
                return {'confidence': 0.0, 'patterns': {}, 'volcanic_indicators': []}
            
            # Analyze seismic patterns
            patterns = {
                'magnitude_distribution': [],
                'depth_distribution': [],
                'temporal_clustering': [],
                'spatial_clustering': [],
                'volcanic_earthquake_indicators': []
            }
            
            volcanic_indicators = []
            
            for record in seismic_records:
                magnitude = record['magnitude']
                depth = record['depth_km']
                event_type = record['event_type'] or ''
                
                patterns['magnitude_distribution'].append(magnitude)
                if depth is not None:
                    patterns['depth_distribution'].append(depth)
                
                # Identify potential volcanic earthquakes
                is_volcanic_indicator = False
                
                # Shallow earthquakes (< 10 km) in volcanic regions
                if depth is not None and depth < 10:
                    is_volcanic_indicator = True
                
                # Low magnitude swarms (typical of volcanic activity)
                if magnitude < 4.0:
                    is_volcanic_indicator = True
                
                # Specific event types
                if any(term in event_type.lower() for term in ['volcanic', 'explosion', 'tremor']):
                    is_volcanic_indicator = True
                
                if is_volcanic_indicator:
                    volcanic_indicators.append({
                        'magnitude': magnitude,
                        'depth': depth,
                        'event_type': event_type,
                        'timestamp': record['occurrence_time'],
                        'lat': record['latitude'],
                        'lon': record['longitude']
                    })
            
            # Calculate seismic-volcanic correlation
            shallow_earthquake_ratio = len([d for d in patterns['depth_distribution'] if d < 10]) / len(patterns['depth_distribution']) if patterns['depth_distribution'] else 0
            low_magnitude_ratio = len([m for m in patterns['magnitude_distribution'] if m < 4.0]) / len(patterns['magnitude_distribution']) if patterns['magnitude_distribution'] else 0
            
            volcanic_seismic_score = (shallow_earthquake_ratio + low_magnitude_ratio) / 2.0
            
            # Calculate confidence
            data_quality_scores = [0.8 if r['quality_grade'] in ['A', 'B'] else 0.5 for r in seismic_records]
            avg_quality = np.mean(data_quality_scores) if data_quality_scores else 0.5
            data_quantity_factor = min(1.0, len(seismic_records) / 50.0)
            
            confidence = avg_quality * data_quantity_factor * (1.0 if volcanic_seismic_score > 0.3 else 0.5)
            
            return {
                'confidence': confidence,
                'patterns': patterns,
                'volcanic_indicators': volcanic_indicators,
                'volcanic_seismic_score': volcanic_seismic_score,
                'total_earthquakes': len(seismic_records),
                'shallow_earthquake_ratio': shallow_earthquake_ratio,
                'low_magnitude_ratio': low_magnitude_ratio
            }
            
        except Exception as e:
            self.logger.error(f"Seismic volcanic patterns analysis failed: {e}")
            return {'confidence': 0.0, 'patterns': {}, 'volcanic_indicators': []}
    
    async def _analyze_geochemical_volcanic_indicators(self, lat_min: float, lat_max: float,
                                                     lon_min: float, lon_max: float) -> Dict[str, Any]:
        """Analyze geochemical indicators for volcanic activity"""
        try:
            cursor = self.db_connections['postgresql'].cursor()
            
            # Query geochemical data from volcanic monitoring
            cursor.execute("""
                SELECT 
                    vm.properties->>'so2_concentration_ppm' as so2_ppm,
                    vm.properties->>'co2_concentration_ppm' as co2_ppm,
                    vm.properties->>'h2s_concentration_ppm' as h2s_ppm,
                    vm.properties->>'temperature_c' as temperature_c,
                    vm.properties->>'ph_level' as ph_level,
                    vm.properties->>'gas_flux_tons_day' as gas_flux,
                    vm.timestamp,
                    v.latitude,
                    v.longitude,
                    vm.data_quality_score
                FROM volcanic_monitoring vm
                JOIN volcanoes v ON vm.volcano_id = v.volcano_id
                WHERE ST_Within(
                    v.location,
                    ST_MakeEnvelope(%s, %s, %s, %s, 4326)
                )
                AND vm.timestamp > NOW() - INTERVAL '1 year'
                AND (
                    vm.properties ? 'so2_concentration_ppm' OR
                    vm.properties ? 'co2_concentration_ppm' OR
                    vm.properties ? 'h2s_concentration_ppm' OR
                    vm.properties ? 'gas_flux_tons_day'
                )
                ORDER BY vm.timestamp DESC
                LIMIT 200;
            """, (lon_min, lat_min, lon_max, lat_max))
            
            geochemical_records = cursor.fetchall()
            
            if not geochemical_records:
                return {'confidence': 0.0, 'indicators': {}, 'volcanic_activity_level': 'unknown'}
            
            # Analyze geochemical indicators
            indicators = {
                'so2_levels': [],
                'co2_levels': [],
                'h2s_levels': [],
                'temperature_anomalies': [],
                'ph_variations': [],
                'gas_flux_variations': []
            }
            
            for record in geochemical_records:
                if record['so2_ppm']:
                    try:
                        indicators['so2_levels'].append(float(record['so2_ppm']))
                    except (ValueError, TypeError):
                        pass
                
                if record['co2_ppm']:
                    try:
                        indicators['co2_levels'].append(float(record['co2_ppm']))
                    except (ValueError, TypeError):
                        pass
                
                if record['h2s_ppm']:
                    try:
                        indicators['h2s_levels'].append(float(record['h2s_ppm']))
                    except (ValueError, TypeError):
                        pass
                
                if record['temperature_c']:
                    try:
                        temp = float(record['temperature_c'])
                        if temp > 50:  # Elevated temperature indicator
                            indicators['temperature_anomalies'].append(temp)
                    except (ValueError, TypeError):
                        pass
                
                if record['ph_level']:
                    try:
                        indicators['ph_variations'].append(float(record['ph_level']))
                    except (ValueError, TypeError):
                        pass
                
                if record['gas_flux']:
                    try:
                        indicators['gas_flux_variations'].append(float(record['gas_flux']))
                    except (ValueError, TypeError):
                        pass
            
            # Calculate volcanic activity indicators
            volcanic_activity_score = 0.0
            
            # SO2 levels (volcanic gas indicator)
            if indicators['so2_levels']:
                avg_so2 = np.mean(indicators['so2_levels'])
                if avg_so2 > 10:  # Elevated SO2 levels
                    volcanic_activity_score += 0.3
            
            # Temperature anomalies
            if indicators['temperature_anomalies']:
                volcanic_activity_score += 0.2
            
            # Gas flux variations
            if indicators['gas_flux_variations']:
                avg_flux = np.mean(indicators['gas_flux_variations'])
                if avg_flux > 100:  # Significant gas emissions
                    volcanic_activity_score += 0.3
            
            # pH variations (hydrothermal activity indicator)
            if indicators['ph_variations']:
                ph_std = np.std(indicators['ph_variations'])
                if ph_std > 1.0:  # Significant pH variations
                    volcanic_activity_score += 0.2
            
            # Determine activity level
            if volcanic_activity_score > 0.7:
                activity_level = 'high'
            elif volcanic_activity_score > 0.4:
                activity_level = 'moderate'
            elif volcanic_activity_score > 0.2:
                activity_level = 'low'
            else:
                activity_level = 'background'
            
            # Calculate confidence
            data_quality_scores = [r['data_quality_score'] or 0.5 for r in geochemical_records]
            avg_quality = np.mean(data_quality_scores)
            data_quantity_factor = min(1.0, len(geochemical_records) / 30.0)
            
            confidence = avg_quality * data_quantity_factor
            
            return {
                'confidence': confidence,
                'indicators': indicators,
                'volcanic_activity_level': activity_level,
                'volcanic_activity_score': volcanic_activity_score,
                'total_measurements': len(geochemical_records)
            }
            
        except Exception as e:
            self.logger.error(f"Geochemical volcanic indicators analysis failed: {e}")
            return {'confidence': 0.0, 'indicators': {}, 'volcanic_activity_level': 'unknown'}
    
    async def _calculate_comprehensive_volcanic_potential(self, tectonic_region: Dict[str, Any],
                                                        volcanic_indicators: Dict[str, Any],
                                                        seismic_patterns: Dict[str, Any],
                                                        geochemical_indicators: Dict[str, Any]) -> Dict[str, Any]:
        """Calculate comprehensive volcanic potential using multiple data sources"""
        try:
            # Tectonic contribution (40% weight)
            tectonic_score = tectonic_region.get('volcanic_potential_score', 0.0)
            tectonic_weight = 0.4
            
            # Geological indicators contribution (25% weight)
            geological_score = volcanic_indicators.get('volcanic_density', 0.0) * 10  # Normalize
            geological_score = min(1.0, geological_score)
            geological_weight = 0.25
            
            # Seismic patterns contribution (20% weight)
            seismic_score = seismic_patterns.get('volcanic_seismic_score', 0.0)
            seismic_weight = 0.20
            
            # Geochemical indicators contribution (15% weight)
            geochemical_score = geochemical_indicators.get('volcanic_activity_score', 0.0)
            geochemical_weight = 0.15
            
            # Calculate weighted probability
            probability = (
                tectonic_score * tectonic_weight +
                geological_score * geological_weight +
                seismic_score * seismic_weight +
                geochemical_score * geochemical_weight
            )
            
            # Calculate confidence level
            confidence_components = [
                tectonic_region.get('confidence', 0.5),
                volcanic_indicators.get('confidence', 0.5),
                seismic_patterns.get('confidence', 0.5),
                geochemical_indicators.get('confidence', 0.5)
            ]
            
            confidence_level = np.mean(confidence_components)
            
            # Adjust probability based on confidence
            adjusted_probability = probability * confidence_level
            
            # Determine risk category
            if adjusted_probability > 0.8:
                risk_category = 'very_high'
            elif adjusted_probability > 0.6:
                risk_category = 'high'
            elif adjusted_probability > 0.4:
                risk_category = 'moderate'
            elif adjusted_probability > 0.2:
                risk_category = 'low'
            else:
                risk_category = 'very_low'
            
            return {
                'probability': adjusted_probability,
                'confidence_level': confidence_level,
                'risk_category': risk_category,
                'component_scores': {
                    'tectonic': tectonic_score,
                    'geological': geological_score,
                    'seismic': seismic_score,
                    'geochemical': geochemical_score
                },
                'component_weights': {
                    'tectonic': tectonic_weight,
                    'geological': geological_weight,
                    'seismic': seismic_weight,
                    'geochemical': geochemical_weight
                }
            }
            
        except Exception as e:
            self.logger.error(f"Comprehensive volcanic potential calculation failed: {e}")
            return {
                'probability': 0.0,
                'confidence_level': 0.0,
                'risk_category': 'unknown',
                'component_scores': {},
                'component_weights': {}
            }
    
    async def _advanced_binary_mixing_with_geological_context(self, surface_classification: Dict[str, Any], 
                                                            emissivity_library: Dict[str, Dict[str, float]]) -> float:
        """Advanced binary mixing with geological context and physics-based corrections"""
        try:
            # Get primary and secondary surface types
            primary_type = surface_classification.get('primary_type', 'volcanic_rock')
            secondary_type = surface_classification.get('secondary_type', 'weathered_rock')
            primary_fraction = surface_classification.get('primary_fraction', 0.8)
            
            # Get location for geological context
            lat = surface_classification.get('latitude', 0.0)
            lon = surface_classification.get('longitude', 0.0)
            
            # Query geological context from database
            geological_context = await self._get_local_geological_context_for_emissivity(lat, lon)
            
            # Get base emissivities from library with geological refinement
            primary_emissivity = await self._get_refined_emissivity_from_geology(
                primary_type, geological_context, emissivity_library
            )
            secondary_emissivity = await self._get_refined_emissivity_from_geology(
                secondary_type, geological_context, emissivity_library
            )
            
            # Apply temperature-dependent corrections
            temperature = surface_classification.get('temperature_k', 300.0)
            primary_emissivity = await self._apply_temperature_emissivity_correction(
                primary_emissivity, temperature, primary_type, surface_classification.get('data_source')
            )
            secondary_emissivity = await self._apply_temperature_emissivity_correction(
                secondary_emissivity, temperature, secondary_type, surface_classification.get('data_source')
            )
            
            # Apply weathering corrections based on geological age and climate
            weathering_factor = await self._calculate_weathering_factor(geological_context, lat, lon)
            if 'weathered' in secondary_type or 'altered' in secondary_type:
                secondary_emissivity *= (1.0 + weathering_factor * 0.02)  # Weathered surfaces have higher emissivity
            
            # Apply surface roughness corrections
            roughness_factor = geological_context.get('surface_roughness', 0.5)
            roughness_correction = 1.0 + roughness_factor * 0.01  # Rough surfaces have slightly higher emissivity
            
            # Advanced mixing models based on surface geometry
            mixing_geometry = surface_classification.get('mixing_geometry', 'areal')
            
            if mixing_geometry == 'intimate':
                # Intimate mixing using Hapke model
                mixed_emissivity = await self._hapke_intimate_mixing(
                    primary_emissivity, secondary_emissivity, primary_fraction
                )
            elif mixing_geometry == 'layered':
                # Layered mixing using Fresnel equations
                layer_thickness = surface_classification.get('layer_thickness_m', 0.01)
                mixed_emissivity = await self._fresnel_layered_mixing(
                    primary_emissivity, secondary_emissivity, primary_fraction, layer_thickness
                )
            else:
                # Advanced areal mixing with non-linear corrections
                mixed_emissivity = await self._advanced_areal_mixing(
                    primary_emissivity, secondary_emissivity, primary_fraction, geological_context
                )
            
            # Apply surface roughness correction
            final_emissivity = mixed_emissivity * roughness_correction
            
            # Apply realistic bounds
            final_emissivity = max(0.75, min(0.99, final_emissivity))
            
            # Store mixing metadata
            surface_classification['binary_mixing_metadata'] = {
                'primary_type': primary_type,
                'secondary_type': secondary_type,
                'primary_fraction': primary_fraction,
                'primary_emissivity': primary_emissivity,
                'secondary_emissivity': secondary_emissivity,
                'mixing_geometry': mixing_geometry,
                'weathering_factor': weathering_factor,
                'roughness_correction': roughness_correction,
                'final_emissivity': final_emissivity,
                'geological_context': geological_context.get('dominant_lithology', 'unknown')
            }
            
            return final_emissivity
            
        except Exception as e:
            self.logger.error(f"Advanced binary mixing failed: {e}")
            # Basic fallback mixing
            primary_emis = emissivity_library.get('volcanic', {}).get(primary_type, 0.94)
            secondary_emis = emissivity_library.get('volcanic', {}).get(secondary_type, 0.92)
            return primary_fraction * primary_emis + (1 - primary_fraction) * secondary_emis
    
    async def _get_local_geological_context_for_emissivity(self, lat: float, lon: float) -> Dict[str, Any]:
        """Get local geological context for emissivity calculations"""
        try:
            cursor = self.db_connections['postgresql'].cursor()
            
            # Query nearby geological structures
            cursor.execute("""
                SELECT 
                    gs.lithology,
                    gs.structure_type,
                    gs.age,
                    gs.properties->>'weathering_degree' as weathering,
                    gs.properties->>'surface_roughness' as roughness,
                    gs.properties->>'alteration_type' as alteration,
                    gs.confidence_level,
                    ST_Distance(gs.location, ST_GeogFromText(%s)) as distance
                FROM geological_structures gs
                WHERE ST_DWithin(gs.location, ST_GeogFromText(%s), 5000)
                ORDER BY distance ASC
                LIMIT 10;
            """, (f'POINT({lon} {lat})', f'POINT({lon} {lat})'))
            
            geological_records = cursor.fetchall()
            
            if geological_records:
                # Use closest high-confidence record
                best_record = max(geological_records, key=lambda r: r['confidence_level'] or 0.5)
                
                return {
                    'dominant_lithology': best_record['lithology'],
                    'structure_type': best_record['structure_type'],
                    'geological_age': best_record['age'],
                    'weathering_degree': best_record['weathering'] or 'moderate',
                    'surface_roughness': float(best_record['roughness']) if best_record['roughness'] else 0.5,
                    'alteration_type': best_record['alteration'],
                    'confidence': best_record['confidence_level'] or 0.5,
                    'distance_m': best_record['distance']
                }
            else:
                # Default context
                return {
                    'dominant_lithology': 'volcanic_rock',
                    'structure_type': 'unknown',
                    'geological_age': None,
                    'weathering_degree': 'moderate',
                    'surface_roughness': 0.5,
                    'alteration_type': None,
                    'confidence': 0.3,
                    'distance_m': float('inf')
                }
                
        except Exception as e:
            self.logger.error(f"Local geological context query failed: {e}")
            return {
                'dominant_lithology': 'volcanic_rock',
                'structure_type': 'unknown',
                'geological_age': None,
                'weathering_degree': 'moderate',
                'surface_roughness': 0.5,
                'alteration_type': None,
                'confidence': 0.3,
                'distance_m': float('inf')
            }
    
    async def _get_refined_emissivity_from_geology(self, surface_type: str, geological_context: Dict[str, Any], 
                                                 emissivity_library: Dict[str, Dict[str, float]]) -> float:
        """Get refined emissivity based on geological context"""
        try:
            # Base emissivity from library
            base_emissivity = 0.94  # Default
            
            # Try to find in library
            for category, materials in emissivity_library.items():
                if surface_type in materials:
                    base_emissivity = materials[surface_type]
                    break
            
            # Refine based on geological context
            lithology = geological_context.get('dominant_lithology', '').lower()
            alteration = geological_context.get('alteration_type', '').lower()
            
            # Lithology-specific adjustments
            if 'basalt' in lithology:
                base_emissivity = max(base_emissivity, 0.95)  # Basalt typically high emissivity
            elif 'rhyolite' in lithology or 'dacite' in lithology:
                base_emissivity = min(base_emissivity, 0.93)  # Silicic rocks slightly lower
            elif 'andesite' in lithology:
                base_emissivity = 0.94  # Intermediate composition
            
            # Alteration adjustments
            if 'hydrothermal' in alteration or 'clay' in alteration:
                base_emissivity *= 0.95  # Clay alteration reduces emissivity slightly
            elif 'silica' in alteration or 'sinter' in alteration:
                base_emissivity *= 0.92  # Silica alteration reduces emissivity more
            
            # Age-based weathering adjustment
            age = geological_context.get('geological_age')
            if age and age < 1.0:  # Very young rocks (< 1 Ma)
                base_emissivity *= 1.01  # Fresh surfaces
            elif age and age > 100.0:  # Old rocks (> 100 Ma)
                base_emissivity *= 1.02  # Weathered surfaces
            
            return max(0.8, min(0.99, base_emissivity))
            
        except Exception as e:
            return 0.94  # Safe default
    
    async def _calculate_weathering_factor(self, geological_context: Dict[str, Any], lat: float, lon: float) -> float:
        """Calculate weathering factor based on geological and climatic conditions"""
        try:
            # Base weathering from geological context
            weathering_degree = geological_context.get('weathering_degree', 'moderate').lower()
            
            if weathering_degree == 'fresh' or weathering_degree == 'low':
                base_factor = 0.1
            elif weathering_degree == 'moderate':
                base_factor = 0.5
            elif weathering_degree == 'high' or weathering_degree == 'severe':
                base_factor = 0.9
            else:
                base_factor = 0.5
            
            # Climate-based adjustments
            # Query recent precipitation and temperature data
            cursor = self.db_connections['postgresql'].cursor()
            
            cursor.execute("""
                SELECT 
                    AVG(CASE WHEN vm.properties->>'precipitation_mm' IS NOT NULL 
                        THEN (vm.properties->>'precipitation_mm')::float ELSE NULL END) as avg_precip,
                    AVG(CASE WHEN vm.properties->>'temperature_c' IS NOT NULL 
                        THEN (vm.properties->>'temperature_c')::float ELSE NULL END) as avg_temp
                FROM volcanic_monitoring vm
                JOIN volcanoes v ON vm.volcano_id = v.volcano_id
                WHERE ST_DWithin(v.location, ST_GeogFromText(%s), 100000)
                AND vm.timestamp > NOW() - INTERVAL '1 year'
                AND (vm.properties ? 'precipitation_mm' OR vm.properties ? 'temperature_c');
            """, (f'POINT({lon} {lat})',))
            
            climate_data = cursor.fetchone()
            
            if climate_data and climate_data['avg_precip'] and climate_data['avg_temp']:
                # High precipitation and temperature increase weathering
                precip_factor = min(1.0, climate_data['avg_precip'] / 2000.0)  # Normalize to 2000mm/year
                temp_factor = min(1.0, max(0.0, (climate_data['avg_temp'] - 10.0) / 20.0))  # 10-30°C range
                climate_factor = (precip_factor + temp_factor) / 2.0
            else:
                # Estimate from latitude (tropical = more weathering)
                climate_factor = max(0.2, 1.0 - abs(lat) / 60.0)  # Higher weathering near equator
            
            # Geological age factor
            age = geological_context.get('geological_age')
            if age:
                age_factor = min(1.0, age / 100.0)  # Normalize to 100 Ma
            else:
                age_factor = 0.5
            
            # Combined weathering factor
            combined_factor = (base_factor * 0.5 + climate_factor * 0.3 + age_factor * 0.2)
            
            return max(0.0, min(1.0, combined_factor))
            
        except Exception as e:
            return 0.5  # Default moderate weathering
    
    async def _advanced_areal_mixing(self, emis1: float, emis2: float, fraction1: float, 
                                   geological_context: Dict[str, Any]) -> float:
        """Advanced areal mixing with geological context corrections"""
        try:
            # Non-linear mixing based on surface heterogeneity
            heterogeneity = geological_context.get('surface_roughness', 0.5)
            
            # Linear component
            linear_mix = fraction1 * emis1 + (1 - fraction1) * emis2
            
            # Non-linear correction based on heterogeneity
            # More heterogeneous surfaces deviate from linear mixing
            if heterogeneity > 0.7:  # High heterogeneity
                # Use power law mixing
                power_factor = 1.2 + heterogeneity * 0.3
                nonlinear_mix = (fraction1 * (emis1 ** power_factor) + 
                               (1 - fraction1) * (emis2 ** power_factor)) ** (1.0 / power_factor)
            else:
                # Use logarithmic mixing for moderate heterogeneity
                if emis1 > 0 and emis2 > 0:
                    log_mix = np.exp(fraction1 * np.log(emis1) + (1 - fraction1) * np.log(emis2))
                    nonlinear_mix = (linear_mix + log_mix) / 2.0
                else:
                    nonlinear_mix = linear_mix
            
            # Weight between linear and non-linear based on heterogeneity
            final_mix = (1 - heterogeneity) * linear_mix + heterogeneity * nonlinear_mix
            
            return max(0.8, min(0.99, final_mix))
            
        except Exception as e:
            # Fallback to simple linear mixing
            return fraction1 * emis1 + (1 - fraction1) * emis2 
    
    async def _calculate_advanced_air_mass(self, zenith_angle: float, surface_pressure: float) -> float:
        """Calculate advanced air mass with Earth curvature and pressure corrections"""
        try:
            # Kasten & Young (1989) formula with pressure correction
            zenith_rad = np.radians(zenith_angle)
            
            if zenith_angle < 90:
                # Standard air mass calculation
                cos_zenith = np.cos(zenith_rad)
                air_mass = 1.0 / (cos_zenith + 0.50572 * (96.07995 - zenith_angle) ** (-1.6364))
                
                # Pressure correction
                pressure_correction = surface_pressure / 1013.25
                air_mass *= pressure_correction
                
                # Earth curvature correction for large zenith angles
                if zenith_angle > 60:
                    earth_radius = 6371.0  # km
                    atmosphere_height = 100.0  # km (effective atmosphere height)
                    
                    # Geometric correction
                    r_ratio = earth_radius / (earth_radius + atmosphere_height)
                    curvature_correction = np.sqrt(1 - (r_ratio * np.sin(zenith_rad))**2)
                    air_mass /= curvature_correction
                
                return min(air_mass, 40.0)  # Cap at 40 for extreme angles
            else:
                return 40.0  # Maximum air mass for grazing angles
                
        except Exception as e:
            self.logger.error(f"Advanced air mass calculation failed: {e}")
            return 1.0 / np.cos(np.radians(min(zenith_angle, 80)))
    
