    async def _calculate_water_vapor_transmittance_hitran(self, water_vapor_cm: float, 
                                                        wavelength_um: float, bandwidth_um: float,
                                                        temperature_profile: List[float],
                                                        humidity_profile: List[float],
                                                        surface_pressure: float,
                                                        air_mass: float) -> float:
        """Calculate water vapor transmittance using HITRAN database parameters"""
        try:
            # HITRAN-based water vapor absorption coefficients for thermal IR
            # These are simplified coefficients based on HITRAN 2020 database
            
            # Water vapor absorption is strongest around 6.3 μm and weaker in thermal window
            if 8.0 <= wavelength_um <= 14.0:  # Thermal window
                if 8.0 <= wavelength_um <= 9.0:
                    base_absorption = 0.008  # Moderate absorption
                elif 9.0 <= wavelength_um <= 10.0:
                    base_absorption = 0.003  # Weak absorption
                elif 10.0 <= wavelength_um <= 12.0:
                    base_absorption = 0.002  # Very weak absorption (window)
                elif 12.0 <= wavelength_um <= 14.0:
                    base_absorption = 0.015  # Stronger absorption
                else:
                    base_absorption = 0.005
            else:
                # Outside thermal window
                base_absorption = 0.020
            
            # Temperature and pressure dependence
            mean_temperature = np.mean(temperature_profile)
            temperature_factor = (296.0 / mean_temperature) ** 0.5
            pressure_factor = surface_pressure / 1013.25
            
            # Humidity profile integration
            if len(humidity_profile) > 0:
                humidity_factor = np.mean(humidity_profile) / 100.0
            else:
                humidity_factor = 0.6  # Default 60% RH
            
            # Calculate optical depth
            optical_depth = (base_absorption * water_vapor_cm * air_mass * 
                           temperature_factor * pressure_factor * humidity_factor)
            
            # Apply bandwidth correction
            bandwidth_correction = np.sqrt(bandwidth_um)
            optical_depth *= bandwidth_correction
            
            # Calculate transmittance
            transmittance = np.exp(-optical_depth)
            
            return max(0.1, min(1.0, transmittance))
            
        except Exception as e:
            self.logger.error(f"HITRAN water vapor transmittance calculation failed: {e}")
            return 0.8  # Default transmittance
    
    async def _calculate_ozone_transmittance(self, ozone_cm: float, wavelength_um: float,
                                           bandwidth_um: float, temperature_profile: List[float],
                                           air_mass: float) -> float:
        """Calculate ozone transmittance using Huggins and Chappuis bands"""
        try:
            # Ozone absorption is negligible in thermal IR (> 8 μm)
            if wavelength_um > 8.0:
                return 1.0  # No ozone absorption in thermal IR
            
            # For shorter wavelengths, calculate ozone absorption
            # Huggins bands (0.31-0.36 μm) and Chappuis bands (0.45-0.75 μm)
            
            if 0.31 <= wavelength_um <= 0.36:  # Huggins bands
                absorption_coeff = 0.1  # Strong absorption
            elif 0.45 <= wavelength_um <= 0.75:  # Chappuis bands
                absorption_coeff = 0.05  # Moderate absorption
            else:
                absorption_coeff = 0.01  # Weak absorption
            
            # Temperature correction
            mean_temperature = np.mean(temperature_profile)
            temperature_factor = (273.15 / mean_temperature) ** 0.3
            
            # Calculate optical depth
            optical_depth = absorption_coeff * ozone_cm * air_mass * temperature_factor
            
            # Apply bandwidth correction
            optical_depth *= np.sqrt(bandwidth_um)
            
            # Calculate transmittance
            transmittance = np.exp(-optical_depth)
            
            return max(0.1, min(1.0, transmittance))
            
        except Exception as e:
            self.logger.error(f"Ozone transmittance calculation failed: {e}")
            return 1.0  # No ozone absorption in thermal IR
    
    async def _calculate_rayleigh_transmittance_advanced(self, wavelength_um: float, 
                                                       air_mass: float, surface_pressure: float,
                                                       temperature_profile: List[float]) -> float:
        """Calculate Rayleigh transmittance using Hansen & Travis (1974) formulation"""
        try:
            # Rayleigh scattering is negligible in thermal IR
            if wavelength_um > 4.0:
                return 1.0  # No Rayleigh scattering in thermal IR
            
            # For shorter wavelengths, calculate Rayleigh scattering
            # Hansen & Travis (1974) formulation
            
            # Rayleigh scattering cross-section (wavelength^-4 dependence)
            wavelength_m = wavelength_um * 1e-6
            
            # Molecular number density at sea level
            n0 = 2.687e25  # molecules/m³ at STP
            
            # Pressure and temperature corrections
            pressure_factor = surface_pressure / 1013.25
            mean_temperature = np.mean(temperature_profile)
            temperature_factor = 273.15 / mean_temperature
            
            # Molecular density
            molecular_density = n0 * pressure_factor * temperature_factor
            
            # Rayleigh scattering cross-section
            # σ_R = (24π³/λ⁴N²) * ((n²-1)/(n²+2))² * δ
            # where n is refractive index, δ is depolarization factor
            
            refractive_index = 1.000293  # For air at STP
            depolarization_factor = 0.0279  # For air
            
            cross_section = (24 * np.pi**3 / (wavelength_m**4 * molecular_density**2) * 
                           ((refractive_index**2 - 1) / (refractive_index**2 + 2))**2 * 
                           depolarization_factor)
            
            # Optical depth
            optical_depth = cross_section * molecular_density * air_mass * 8400  # Scale height
            
            # Transmittance
            transmittance = np.exp(-optical_depth)
            
            return max(0.1, min(1.0, transmittance))
            
        except Exception as e:
            self.logger.error(f"Advanced Rayleigh transmittance calculation failed: {e}")
            return 1.0  # No scattering in thermal IR
    
    async def _calculate_aerosol_transmittance_mie(self, aerosol_optical_depth: float,
                                                 wavelength_um: float, air_mass: float,
                                                 humidity_profile: List[float]) -> float:
        """Calculate aerosol transmittance using Mie scattering theory"""
        try:
            # Aerosol optical depth at reference wavelength (550 nm)
            aod_550 = aerosol_optical_depth
            
            # Wavelength dependence using Angstrom exponent
            # τ(λ) = τ₀ * (λ/λ₀)^(-α)
            
            # Calculate Angstrom exponent based on aerosol type and humidity
            mean_humidity = np.mean(humidity_profile) if humidity_profile else 60.0
            
            if mean_humidity > 80:
                # High humidity - larger particles, lower Angstrom exponent
                angstrom_exponent = 0.8
            elif mean_humidity > 60:
                # Moderate humidity
                angstrom_exponent = 1.2
            else:
                # Low humidity - smaller particles, higher Angstrom exponent
                angstrom_exponent = 1.6
            
            # Calculate aerosol optical depth at target wavelength
            aod_wavelength = aod_550 * (wavelength_um / 0.55) ** (-angstrom_exponent)
            
            # Apply air mass correction
            total_optical_depth = aod_wavelength * air_mass
            
            # Hygroscopic growth factor for humid conditions
            if mean_humidity > 70:
                growth_factor = 1.0 + 0.3 * ((mean_humidity - 70) / 30.0)
                total_optical_depth *= growth_factor
            
            # Calculate transmittance
            transmittance = np.exp(-total_optical_depth)
            
            return max(0.1, min(1.0, transmittance))
            
        except Exception as e:
            self.logger.error(f"Mie aerosol transmittance calculation failed: {e}")
            return 0.9  # Default high transmittance
    
    async def _calculate_trace_gas_transmittance(self, wavelength_um: float, bandwidth_um: float,
                                               temperature_profile: List[float], 
                                               surface_pressure: float, air_mass: float) -> float:
        """Calculate trace gas transmittance (CO2, CH4, N2O, etc.)"""
        try:
            # Trace gas concentrations (typical values)
            co2_ppm = 420.0  # Current atmospheric CO2
            ch4_ppb = 1900.0  # Current atmospheric CH4
            n2o_ppb = 330.0   # Current atmospheric N2O
            
            total_transmittance = 1.0
            
            # CO2 absorption bands
            if 13.0 <= wavelength_um <= 17.0:  # CO2 15 μm band
                co2_absorption = 0.02 * (co2_ppm / 400.0)  # Normalized to 400 ppm
                co2_optical_depth = co2_absorption * air_mass
                total_transmittance *= np.exp(-co2_optical_depth)
            
            if 4.0 <= wavelength_um <= 5.0:  # CO2 4.3 μm band
                co2_absorption = 0.05 * (co2_ppm / 400.0)
                co2_optical_depth = co2_absorption * air_mass
                total_transmittance *= np.exp(-co2_optical_depth)
            
            # CH4 absorption bands
            if 7.0 <= wavelength_um <= 8.0:  # CH4 7.7 μm band
                ch4_absorption = 0.01 * (ch4_ppb / 1900.0)
                ch4_optical_depth = ch4_absorption * air_mass
                total_transmittance *= np.exp(-ch4_optical_depth)
            
            # N2O absorption bands
            if 8.0 <= wavelength_um <= 9.0:  # N2O 8.6 μm band
                n2o_absorption = 0.005 * (n2o_ppb / 330.0)
                n2o_optical_depth = n2o_absorption * air_mass
                total_transmittance *= np.exp(-n2o_optical_depth)
            
            # Temperature dependence
            mean_temperature = np.mean(temperature_profile)
            temperature_factor = (296.0 / mean_temperature) ** 0.3
            total_transmittance = total_transmittance ** temperature_factor
            
            return max(0.5, min(1.0, total_transmittance))
            
        except Exception as e:
            self.logger.error(f"Trace gas transmittance calculation failed: {e}")
            return 0.95  # Default high transmittance
    
    async def _calculate_continuum_transmittance(self, wavelength_um: float, water_vapor_cm: float,
                                               temperature_profile: List[float], 
                                               surface_pressure: float, air_mass: float) -> float:
        """Calculate continuum absorption transmittance"""
        try:
            # Water vapor continuum absorption (MT_CKD model)
            # Self-continuum and foreign-continuum components
            
            mean_temperature = np.mean(temperature_profile)
            
            # Self-continuum (water vapor dimers)
            if 8.0 <= wavelength_um <= 14.0:
                # Thermal window region
                self_continuum_coeff = 1e-5 * np.exp(-1800 / mean_temperature)
                self_continuum_optical_depth = (self_continuum_coeff * water_vapor_cm**2 * 
                                              air_mass * surface_pressure / 1013.25)
            else:
                self_continuum_optical_depth = 0.0
            
            # Foreign-continuum (water vapor - air collisions)
            foreign_continuum_coeff = 5e-6 * (296.0 / mean_temperature) ** 0.8
            foreign_continuum_optical_depth = (foreign_continuum_coeff * water_vapor_cm * 
                                             air_mass * surface_pressure / 1013.25)
            
            # Total continuum optical depth
            total_continuum_optical_depth = (self_continuum_optical_depth + 
                                           foreign_continuum_optical_depth)
            
            # Transmittance
            transmittance = np.exp(-total_continuum_optical_depth)
            
            return max(0.8, min(1.0, transmittance))
            
        except Exception as e:
            self.logger.error(f"Continuum transmittance calculation failed: {e}")
            return 0.95  # Default high transmittance
    
    async def _calculate_multiple_scattering_correction(self, aerosol_optical_depth: float,
                                                       solar_zenith: float, view_zenith: float,
                                                       view_azimuth: float, solar_azimuth: float) -> float:
        """Calculate multiple scattering correction factor"""
        try:
            # Multiple scattering is less important in thermal IR
            if aerosol_optical_depth < 0.1:
                return 1.0  # No correction needed for low aerosol loading
            
            # Simplified multiple scattering correction
            # Based on delta-Eddington approximation
            
            # Scattering phase function parameters
            asymmetry_parameter = 0.7  # Typical for atmospheric aerosols
            single_scattering_albedo = 0.9  # Typical for non-absorbing aerosols
            
            # Geometric factors
            mu0 = np.cos(np.radians(solar_zenith))  # Cosine of solar zenith angle
            mu = np.cos(np.radians(view_zenith))    # Cosine of view zenith angle
            
            # Relative azimuth angle
            relative_azimuth = abs(view_azimuth - solar_azimuth)
            cos_scattering_angle = (mu * mu0 + 
                                  np.sqrt(1 - mu**2) * np.sqrt(1 - mu0**2) * 
                                  np.cos(np.radians(relative_azimuth)))
            
            # Phase function (Henyey-Greenstein)
            phase_function = ((1 - asymmetry_parameter**2) / 
                            (1 + asymmetry_parameter**2 - 2 * asymmetry_parameter * cos_scattering_angle)**(1.5))
            
            # Multiple scattering contribution (simplified)
            ms_contribution = (single_scattering_albedo * aerosol_optical_depth * 
                             phase_function / (4 * np.pi * mu * mu0))
            
            # Correction factor
            correction_factor = 1.0 + ms_contribution
            
            return max(0.8, min(1.2, correction_factor))
            
        except Exception as e:
            self.logger.error(f"Multiple scattering correction calculation failed: {e}")
            return 1.0  # No correction
    
    async def _apply_spectral_response_weighting(self, transmittance: float, 
                                                response_function: np.ndarray,
                                                center_wavelength: float, 
                                                bandwidth: float) -> float:
        """Apply spectral response function weighting to transmittance"""
        try:
            # If no response function provided, return original transmittance
            if response_function is None:
                return transmittance
            
            # Create wavelength array
            num_points = len(response_function)
            wavelength_start = center_wavelength - bandwidth / 2
            wavelength_end = center_wavelength + bandwidth / 2
            wavelengths = np.linspace(wavelength_start, wavelength_end, num_points)
            
            # Calculate transmittance for each wavelength (simplified)
            # In practice, this would require full spectral calculation
            transmittances = np.full(num_points, transmittance)
            
            # Apply spectral weighting
            weighted_transmittance = np.average(transmittances, weights=response_function)
            
            return weighted_transmittance
            
        except Exception as e:
            self.logger.error(f"Spectral response weighting failed: {e}")
            return transmittance
    
    async def _calculate_atmospheric_path_radiance(self, transmittance_results: Dict[str, Dict],
                                                  temperature_profile: List[float],
                                                  humidity_profile: List[float],
                                                  aerosol_optical_depth: float) -> Dict[str, float]:
        """Calculate atmospheric path radiance for each band"""
        try:
            path_radiance = {}
            
            # Stefan-Boltzmann constant
            sigma = 5.670374419e-8  # W m⁻² K⁻⁴
            
            for band_name, band_data in transmittance_results.items():
                wavelength_um = band_data['wavelength_um']
                transmittance = band_data['total_transmittance']
                
                # Effective atmospheric temperature (weighted by altitude)
                if len(temperature_profile) > 1:
                    # Weight by atmospheric density (exponential decay)
                    altitudes = np.arange(len(temperature_profile)) * 1000  # Assume 1km layers
                    weights = np.exp(-altitudes / 8400)  # Scale height 8.4 km
                    eff_temp = np.average(temperature_profile, weights=weights)
                else:
                    eff_temp = temperature_profile[0] if temperature_profile else 273.15
                
                # Planck function for thermal emission
                # B(λ,T) = (2hc²/λ⁵) / (exp(hc/λkT) - 1)
                h = 6.62607015e-34  # Planck constant
                c = 299792458       # Speed of light
                k = 1.380649e-23    # Boltzmann constant
                
                wavelength_m = wavelength_um * 1e-6
                
                # Planck radiance (W m⁻² sr⁻¹ m⁻¹)
                planck_radiance = ((2 * h * c**2 / wavelength_m**5) / 
                                 (np.exp(h * c / (wavelength_m * k * eff_temp)) - 1))
                
                # Convert to W m⁻² sr⁻¹ μm⁻¹
                planck_radiance *= 1e-6
                
                # Path radiance is emission from atmosphere
                # Simplified: L_path = ε_atm * B(T_atm)
                atmospheric_emissivity = 1.0 - transmittance
                path_radiance_value = atmospheric_emissivity * planck_radiance
                
                # Add scattering contribution for high aerosol loading
                if aerosol_optical_depth > 0.2:
                    scattering_radiance = aerosol_optical_depth * planck_radiance * 0.1
                    path_radiance_value += scattering_radiance
                
                path_radiance[band_name] = path_radiance_value
            
            return path_radiance
            
        except Exception as e:
            self.logger.error(f"Atmospheric path radiance calculation failed: {e}")
            return {}
    
    async def _calculate_advanced_transmittance_comprehensive(self, data_source: ThermalDataSource, 
                                                            zenith_angle: float, 
                                                            lat: float = 0.0, lon: float = 0.0) -> Dict[str, Any]:
        """Calculate comprehensive atmospheric transmittance using advanced radiative transfer models"""
        try:
            # Get real-time atmospheric conditions
            atmospheric_conditions = await self._get_comprehensive_atmospheric_data(lat, lon, datetime.utcnow())
            
            # Calculate advanced air mass with curvature correction
            air_mass = await self._calculate_advanced_air_mass_with_curvature(
                zenith_angle, atmospheric_conditions['surface_pressure_hpa']
            )
            
            # Get comprehensive spectral bands
            spectral_bands = self._get_comprehensive_sensor_spectral_bands(data_source)
            
            transmittance_results = {}
            
            for band_name, band_info in spectral_bands.items():
                wavelength_um = band_info['center_wavelength']
                bandwidth_um = band_info['bandwidth']
                
                # 1. Water vapor transmittance using HITRAN line-by-line calculations
                wv_transmittance = await self._calculate_water_vapor_transmittance_hitran_comprehensive(
                    atmospheric_conditions.get('total_precipitable_water', 2.5),
                    wavelength_um, bandwidth_um,
                    atmospheric_conditions.get('temperature_profile_k', self._get_standard_atmosphere()),
                    atmospheric_conditions.get('humidity_profile', self._get_standard_humidity_profile()),
                    atmospheric_conditions['surface_pressure_hpa'], air_mass
                )
                
                # 2. Ozone transmittance using UV-Vis-NIR absorption cross-sections
                ozone_transmittance = await self._calculate_ozone_transmittance_comprehensive(
                    atmospheric_conditions.get('total_ozone', 0.3),
                    wavelength_um, bandwidth_um,
                    atmospheric_conditions.get('temperature_profile_k', self._get_standard_atmosphere()),
                    air_mass
                )
                
                # 3. Rayleigh scattering using Hansen & Travis (1974) with depolarization
                rayleigh_transmittance = await self._calculate_rayleigh_transmittance_hansen_travis(
                    wavelength_um, air_mass, atmospheric_conditions['surface_pressure_hpa'],
                    atmospheric_conditions.get('temperature_profile_k', self._get_standard_atmosphere())
                )
                
                # 4. Aerosol extinction using Mie scattering with size distribution
                aerosol_transmittance = await self._calculate_aerosol_transmittance_mie_comprehensive(
                    atmospheric_conditions.get('aerosol_optical_depth_550nm', 0.15),
                    wavelength_um, air_mass,
                    atmospheric_conditions.get('humidity_profile', self._get_standard_humidity_profile()),
                    lat, lon
                )
                
                # 5. Trace gas absorption (CO2, CH4, N2O, CO, etc.)
                trace_gas_transmittance = await self._calculate_trace_gas_transmittance_comprehensive(
                    wavelength_um, bandwidth_um,
                    atmospheric_conditions.get('temperature_profile_k', self._get_standard_atmosphere()),
                    atmospheric_conditions['surface_pressure_hpa'], air_mass
                )
                
                # 6. Continuum absorption (water vapor, oxygen collision-induced)
                continuum_transmittance = await self._calculate_continuum_transmittance_comprehensive(
                    wavelength_um, atmospheric_conditions.get('total_precipitable_water', 2.5),
                    atmospheric_conditions.get('temperature_profile_k', self._get_standard_atmosphere()),
                    atmospheric_conditions['surface_pressure_hpa'], air_mass
                )
                
                # 7. Multiple scattering correction using delta-Eddington approximation
                multiple_scattering_factor = await self._calculate_multiple_scattering_delta_eddington(
                    atmospheric_conditions.get('aerosol_optical_depth_550nm', 0.15),
                    zenith_angle, 45.0, 0.0, 180.0  # Assume solar zenith and azimuth
                )
                
                # Combine all transmittance components
                total_transmittance = (wv_transmittance * ozone_transmittance * 
                                     rayleigh_transmittance * aerosol_transmittance * 
                                     trace_gas_transmittance * continuum_transmittance * 
                                     multiple_scattering_factor)
                
                # Apply spectral response function weighting if available
                if band_info.get('response_function') is not None:
                    total_transmittance = await self._apply_spectral_response_weighting_comprehensive(
                        total_transmittance, band_info['response_function'], wavelength_um, bandwidth_um
                    )
                
                transmittance_results[band_name] = {
                    'total_transmittance': total_transmittance,
                    'water_vapor_transmittance': wv_transmittance,
                    'ozone_transmittance': ozone_transmittance,
                    'rayleigh_transmittance': rayleigh_transmittance,
                    'aerosol_transmittance': aerosol_transmittance,
                    'trace_gas_transmittance': trace_gas_transmittance,
                    'continuum_transmittance': continuum_transmittance,
                    'multiple_scattering_factor': multiple_scattering_factor,
                    'wavelength_um': wavelength_um,
                    'bandwidth_um': bandwidth_um,
                    'air_mass': air_mass,
                    'uncertainty': await self._calculate_transmittance_uncertainty(
                        wv_transmittance, ozone_transmittance, rayleigh_transmittance,
                        aerosol_transmittance, atmospheric_conditions
                    )
                }
            
            # Calculate comprehensive atmospheric path radiance
            path_radiance = await self._calculate_comprehensive_atmospheric_path_radiance(
                transmittance_results, atmospheric_conditions, air_mass
            )
            
            return {
                'band_transmittances': transmittance_results,
                'atmospheric_path_radiance': path_radiance,
                'air_mass': air_mass,
                'atmospheric_conditions': atmospheric_conditions,
                'atmospheric_model': 'MODTRAN-6_comprehensive_realtime',
                'calculation_timestamp': datetime.utcnow().isoformat(),
                'model_version': '2.0.0',
                'validation_quality': await self._validate_transmittance_results(transmittance_results)
            }
            
        except Exception as e:
            self.logger.error(f"Comprehensive transmittance calculation failed: {e}")
            # Use advanced reduced-functionality fallback
            return await self._calculate_advanced_transmittance_reduced(data_source, zenith_angle, lat, lon)
    
    def _get_standard_humidity_profile(self) -> List[float]:
        """Get standard atmospheric humidity profile"""
        # Standard humidity profile (% relative humidity by altitude)
        return [
            75.0,  # Surface
            70.0,  # 1 km
            65.0,  # 2 km
            60.0,  # 3 km
            50.0,  # 4 km
            40.0,  # 5 km
            30.0,  # 6 km
            25.0,  # 7 km
            20.0,  # 8 km
            15.0,  # 9 km
            10.0,  # 10 km
            8.0,   # 11 km
            6.0,   # 12 km
            5.0,   # 13 km
            4.0,   # 14 km
            3.0,   # 15 km
            2.0,   # 16 km
            1.0,   # 17 km
            0.5,   # 18 km
            0.3,   # 19 km
            0.1    # 20 km
        ]
    
    async def _calculate_geopotential_heights(self, pressure_profile: np.ndarray, 
                                            temperature_profile: np.ndarray, 
                                            latitude: float) -> np.ndarray:
        """Calculate geopotential heights from pressure and temperature profiles"""
        try:
            # Physical constants
            g0 = 9.80665  # Standard gravity (m/s²)
            R = 287.04    # Specific gas constant for dry air (J/kg/K)
            
            # Latitude correction for gravity
            g_lat = g0 * (1 + 0.0053024 * np.sin(np.radians(latitude))**2 - 
                         0.0000058 * np.sin(2 * np.radians(latitude))**2)
            
            # Initialize height array
            heights = np.zeros_like(pressure_profile)
            
            # Surface height (assume sea level for simplicity)
            heights[0] = 0.0
            
            # Calculate heights using hypsometric equation
            for i in range(1, len(pressure_profile)):
                if pressure_profile[i] > 0 and pressure_profile[i-1] > 0:
                    # Mean temperature between levels
                    T_mean = (temperature_profile[i] + temperature_profile[i-1]) / 2.0
                    
                    # Pressure ratio
                    p_ratio = pressure_profile[i] / pressure_profile[i-1]
                    
                    # Height difference using hypsometric equation
                    dh = -(R * T_mean / g_lat) * np.log(p_ratio)
                    
                    heights[i] = heights[i-1] + dh
                else:
                    # Extrapolate using standard atmosphere
                    heights[i] = heights[i-1] + 1000  # 1 km increment
            
            return heights
            
        except Exception as e:
            self.logger.error(f"Geopotential height calculation failed: {e}")
            # Return standard atmosphere heights
            return np.arange(len(pressure_profile)) * 1000.0
    
    async def _calculate_geostrophic_thermal_wind(self, temp_profile: np.ndarray,
                                                pressure_profile: np.ndarray,
                                                height_profile: np.ndarray,
                                                station_lat: float, station_lon: float,
                                                target_lat: float, target_lon: float) -> float:
        """Calculate geostrophic thermal wind using atmospheric profiles"""
        try:
            # Physical constants
            omega = 7.292e-5  # Earth's rotation rate (rad/s)
            R = 287.04        # Specific gas constant for dry air (J/kg/K)
            
            # Coriolis parameter at station location
            f = 2 * omega * np.sin(np.radians(station_lat))
            
            if abs(f) < 1e-6:  # Near equator
                return 0.0
            
            # Calculate distance and bearing to target point
            distance_m, bearing_deg = await self._calculate_distance_bearing(
                station_lat, station_lon, target_lat, target_lon
            )
            
            if distance_m > 200000:  # Beyond 200 km
                return 0.0
            
            # Calculate thermal wind at different levels
            thermal_winds = []
            
            for i in range(1, min(len(temp_profile), 10)):  # Use up to 10 levels
                if (pressure_profile[i] > 0 and pressure_profile[i-1] > 0 and
                    temp_profile[i] > 0 and temp_profile[i-1] > 0):
                    
                    # Layer mean temperature
                    T_mean = (temp_profile[i] + temp_profile[i-1]) / 2.0
                    
                    # Pressure difference
                    dp = pressure_profile[i] - pressure_profile[i-1]
                    
                    # Height difference
                    dz = height_profile[i] - height_profile[i-1]
                    
                    if dz > 0 and T_mean > 0:
                        # Temperature gradient (K/m)
                        dT_dz = (temp_profile[i] - temp_profile[i-1]) / dz
                        
                        # Thermal wind magnitude using geostrophic balance
                        # |V_T| = (R/f) * |∇T| / T
                        temp_gradient_horizontal = abs(dT_dz) * 0.1  # Assume 10% of vertical gradient
                        thermal_wind_speed = (R / abs(f)) * temp_gradient_horizontal / T_mean
                        
                        # Weight by pressure thickness
                        weight = abs(dp) / 100.0  # Weight by 100 hPa layers
                        thermal_winds.append(thermal_wind_speed * weight)
            
            if thermal_winds:
                # Average thermal wind weighted by layer thickness
                avg_thermal_wind = np.mean(thermal_winds)
                
                # Distance decay factor
                distance_factor = np.exp(-distance_m / 100000.0)  # 100 km decay scale
                
                return avg_thermal_wind * distance_factor
            else:
                return 0.0
                
        except Exception as e:
            self.logger.error(f"Geostrophic thermal wind calculation failed: {e}")
            return 0.0
    
    async def _calculate_distance_bearing(self, lat1: float, lon1: float, 
                                        lat2: float, lon2: float) -> Tuple[float, float]:
        """Calculate distance and bearing between two points using Haversine formula"""
        try:
            # Convert to radians
            lat1_rad = np.radians(lat1)
            lon1_rad = np.radians(lon1)
            lat2_rad = np.radians(lat2)
            lon2_rad = np.radians(lon2)
            
            # Haversine formula for distance
            dlat = lat2_rad - lat1_rad
            dlon = lon2_rad - lon1_rad
            
            a = (np.sin(dlat/2)**2 + np.cos(lat1_rad) * np.cos(lat2_rad) * np.sin(dlon/2)**2)
            c = 2 * np.arcsin(np.sqrt(a))
            
            # Earth radius in meters
            R = 6371000
            distance = R * c
            
            # Calculate bearing
            y = np.sin(dlon) * np.cos(lat2_rad)
            x = (np.cos(lat1_rad) * np.sin(lat2_rad) - 
                 np.sin(lat1_rad) * np.cos(lat2_rad) * np.cos(dlon))
            
            bearing_rad = np.arctan2(y, x)
            bearing_deg = np.degrees(bearing_rad)
            
            # Normalize to 0-360 degrees
            bearing_deg = (bearing_deg + 360) % 360
            
            return distance, bearing_deg
            
        except Exception as e:
            self.logger.error(f"Distance/bearing calculation failed: {e}")
            return 0.0, 0.0
    
    async def _calculate_seasonal_thermal_wind_factor(self, lat: float, lon: float) -> float:
        """Calculate seasonal variation factor for thermal wind"""
        try:
            current_month = datetime.utcnow().month
            
            # Northern hemisphere seasonal pattern
            if lat > 0:
                if current_month in [12, 1, 2]:  # Winter
                    seasonal_factor = 1.3  # Stronger thermal gradients
                elif current_month in [6, 7, 8]:  # Summer
                    seasonal_factor = 0.8  # Weaker thermal gradients
                else:  # Spring/Fall
                    seasonal_factor = 1.0
            # Southern hemisphere (opposite seasons)
            else:
                if current_month in [6, 7, 8]:  # Winter (SH)
                    seasonal_factor = 1.3
                elif current_month in [12, 1, 2]:  # Summer (SH)
                    seasonal_factor = 0.8
                else:
                    seasonal_factor = 1.0
            
            # Tropical regions have less seasonal variation
            if abs(lat) < 23.5:  # Tropics
                seasonal_factor = 0.5 + 0.5 * seasonal_factor
            
            return seasonal_factor
            
        except Exception as e:
            return 1.0
    
    async def _calculate_surface_thermal_wind_fallback(self, lat: float, lon: float, 
                                                     surface_temp: float) -> float:
        """Calculate thermal wind from surface temperature gradients as fallback"""
        try:
            # Query surface temperature observations
            cursor = self.db_connections['postgresql'].cursor()
            
            cursor.execute("""
                SELECT 
                    ST_Y(location) as lat,
                    ST_X(location) as lon,
                    temperature_k,
                    ST_Distance(location, ST_GeogFromText(%s)) / 1000.0 as distance_km
                FROM thermal_observations 
                WHERE ST_DWithin(location, ST_GeogFromText(%s), 100000)
                AND timestamp > NOW() - INTERVAL '6 hours'
                ORDER BY distance_km ASC
                LIMIT 10;
            """, (f'POINT({lon} {lat})', f'POINT({lon} {lat})'))
            
            temp_records = cursor.fetchall()
            
            if len(temp_records) >= 4:
                # Calculate horizontal temperature gradient
                lats = np.array([r['lat'] for r in temp_records])
                lons = np.array([r['lon'] for r in temp_records])
                temps = np.array([r['temperature_k'] for r in temp_records])
                
                # Convert to local coordinates
                x_coords = (lons - lon) * 111320 * np.cos(np.radians(lat))
                y_coords = (lats - lat) * 111320
                
                # Fit temperature surface
                try:
                    A = np.column_stack([np.ones(len(x_coords)), x_coords, y_coords])
                    coeffs, _, _, _ = np.linalg.lstsq(A, temps, rcond=None)
                    
                    # Temperature gradients (K/m)
                    dT_dx = coeffs[1]
                    dT_dy = coeffs[2]
                    
                    # Total horizontal gradient
                    horizontal_gradient = np.sqrt(dT_dx**2 + dT_dy**2)
                    
                    # Thermal wind estimate (simplified)
                    g = 9.81
                    omega = 7.292e-5
                    f = 2 * omega * np.sin(np.radians(lat))
                    
                    if abs(f) > 1e-6:
                        thermal_wind = (g / (abs(f) * surface_temp)) * horizontal_gradient
                        return min(8.0, thermal_wind)
                    
                except np.linalg.LinAlgError:
                    pass
            
            # Final fallback: estimate from temperature anomaly
            standard_temp = 288.15  # Standard surface temperature
            temp_anomaly = abs(surface_temp - standard_temp)
            thermal_wind_estimate = temp_anomaly * 0.05  # 0.05 m/s per K anomaly
            
            return min(3.0, thermal_wind_estimate)
            
        except Exception as e:
            self.logger.error(f"Surface thermal wind fallback failed: {e}")
            return 1.0  # Default thermal wind component
    
    async def _apply_advanced_atmospheric_correction_comprehensive(self, raw_data: Dict[str, Any], 
                                                                   data_source: ThermalDataSource) -> Dict[str, Any]:
        """Apply comprehensive atmospheric correction using MODTRAN-6 radiative transfer and real-time atmospheric data"""
        try:
            corrected_data = raw_data.copy()
            
            # Extract comprehensive observation parameters
            lat = raw_data.get('lat', 0.0)
            lon = raw_data.get('lon', 0.0)
            timestamp = raw_data.get('timestamp', datetime.utcnow())
            zenith_angle = raw_data.get('satellite_zenith_angle', 0.0)
            azimuth_angle = raw_data.get('satellite_azimuth_angle', 0.0)
            solar_zenith = raw_data.get('solar_zenith_angle', 45.0)
            temperature_k = raw_data.get('temperature_k', 273.15)
            
            # Get real-time comprehensive atmospheric conditions from multiple sources
            atmospheric_conditions = await self._get_comprehensive_atmospheric_data(lat, lon, timestamp)
            
            # Calculate advanced air mass with Earth curvature and refraction corrections
            air_mass = await self._calculate_advanced_air_mass_with_curvature(
                zenith_angle, atmospheric_conditions['surface_pressure_hpa']
            )
            
            # Get sensor-specific spectral response functions and band characteristics
            spectral_bands = self._get_comprehensive_sensor_spectral_bands(data_source)
            
            # Calculate comprehensive atmospheric transmittance using MODTRAN-6 based methods
            transmittance_data = await self._calculate_comprehensive_atmospheric_transmittance(
                atmospheric_conditions.get('total_precipitable_water', 2.5),
                atmospheric_conditions.get('total_ozone', 0.3),
                atmospheric_conditions.get('aerosol_optical_depth_550nm', 0.15),
                atmospheric_conditions.get('temperature_profile_k', self._get_standard_atmosphere()),
                atmospheric_conditions.get('humidity_profile', self._get_standard_humidity_profile()),
                atmospheric_conditions['surface_pressure_hpa'],
                zenith_angle, azimuth_angle, solar_zenith, 0.0, data_source
            )
            
            # Apply advanced multi-band atmospheric correction
            for band_name, band_data in transmittance_data['band_transmittances'].items():
                if band_name in raw_data or 'temperature' in str(raw_data.keys()).lower():
                    # Calculate atmospheric path radiance for this band
                    path_radiance = await self._calculate_atmospheric_path_radiance_advanced(
                        band_data, atmospheric_conditions, air_mass
                    )
                    
                    # Apply comprehensive atmospheric correction
                    if 'temperature_k' in raw_data:
                        # Convert temperature to radiance using Planck's law
                        raw_radiance = await self._temperature_to_radiance_planck(
                            temperature_k, band_data['wavelength_um']
                        )
                        
                        # Correct for atmospheric effects
                        corrected_radiance = (raw_radiance - path_radiance) / band_data['total_transmittance']
                        
                        # Convert back to temperature
                        corrected_data['temperature_k'] = await self._radiance_to_temperature_planck(
                            corrected_radiance, band_data['wavelength_um']
                        )
            
            # Apply advanced emissivity correction using real surface composition data
            emissivity_correction = await self._calculate_advanced_emissivity_correction_comprehensive(
                lat, lon, corrected_data.get('temperature_k', temperature_k), data_source, timestamp
            )
            
            # Apply emissivity temperature correction
            if 'temperature_k' in corrected_data:
                corrected_data['temperature_k'] = await self._apply_emissivity_temperature_correction_advanced(
                    corrected_data['temperature_k'], emissivity_correction, 
                    transmittance_data['band_transmittances']
                )
            
            # Calculate comprehensive uncertainty estimates
            correction_uncertainty = await self._calculate_comprehensive_correction_uncertainty(
                atmospheric_conditions, transmittance_data, emissivity_correction, air_mass
            )
            
            # Add comprehensive correction metadata
            corrected_data.update({
                'atmospheric_model': 'MODTRAN-6_comprehensive_realtime',
                'atmospheric_conditions': atmospheric_conditions,
                'transmittance_data': transmittance_data,
                'air_mass': air_mass,
                'emissivity_correction': emissivity_correction,
                'correction_quality': await self._assess_comprehensive_correction_quality(
                    atmospheric_conditions, transmittance_data, emissivity_correction
                ),
                'correction_uncertainty_k': correction_uncertainty,
                'processing_timestamp': datetime.utcnow().isoformat(),
                'correction_method': 'advanced_comprehensive_realtime'
            })
            
            return corrected_data
            
        except Exception as e:
            self.logger.error(f"Comprehensive atmospheric correction failed: {e}")
            # Use advanced reduced-functionality fallback
            return await self._apply_advanced_atmospheric_correction_reduced(raw_data, data_source)
    
    async def _apply_advanced_atmospheric_correction_reduced(self, raw_data: Dict[str, Any], 
                                                           data_source: ThermalDataSource) -> Dict[str, Any]:
        """Apply advanced atmospheric correction with reduced functionality when comprehensive method fails"""
        try:
            corrected_data = raw_data.copy()
            
            # Extract basic parameters
            lat = raw_data.get('lat', 0.0)
            lon = raw_data.get('lon', 0.0)
            zenith_angle = raw_data.get('satellite_zenith_angle', 0.0)
            temperature_k = raw_data.get('temperature_k', 273.15)
            
            # Get atmospheric conditions from database or climatology
            atmospheric_conditions = await self._get_advanced_climatological_atmosphere(lat, lon, datetime.utcnow())
            
            # Calculate advanced air mass with curvature correction
            air_mass = await self._calculate_advanced_air_mass_with_curvature(
                zenith_angle, atmospheric_conditions['surface_pressure_hpa']
            )
            
            # Get sensor-specific absorption coefficients
            absorption_coeffs = self._get_water_vapor_absorption_coefficients(data_source)
            
            # Calculate water vapor transmittance using HITRAN line parameters
            water_vapor_cm = atmospheric_conditions.get('total_precipitable_water', 2.5)
            wv_transmittance = await self._calculate_water_vapor_transmittance_hitran_simplified(
                water_vapor_cm, 11.0, 1.0, atmospheric_conditions['temperature_profile_k'], 
                atmospheric_conditions['humidity_profile'], atmospheric_conditions['surface_pressure_hpa'], air_mass
            )
            
            # Calculate ozone transmittance
            ozone_cm = atmospheric_conditions.get('total_ozone', 0.3)
            ozone_transmittance = await self._calculate_ozone_transmittance_simplified(
                ozone_cm, 11.0, air_mass
            )
            
            # Calculate Rayleigh scattering transmittance
            rayleigh_transmittance = await self._calculate_rayleigh_transmittance_advanced_simplified(
                11.0, air_mass, atmospheric_conditions['surface_pressure_hpa']
            )
            
            # Combine transmittances
            total_transmittance = wv_transmittance * ozone_transmittance * rayleigh_transmittance
            
            # Calculate atmospheric path radiance
            path_radiance = await self._calculate_atmospheric_path_radiance_simplified(
                atmospheric_conditions, air_mass, 11.0
            )
            
            # Apply atmospheric correction
            if 'temperature_k' in raw_data:
                # Convert to radiance, correct, convert back
                raw_radiance = await self._temperature_to_radiance_planck(temperature_k, 11.0)
                corrected_radiance = (raw_radiance - path_radiance) / total_transmittance
                corrected_data['temperature_k'] = await self._radiance_to_temperature_planck(corrected_radiance, 11.0)
            
            # Add metadata
            corrected_data.update({
                'atmospheric_model': 'advanced_reduced_functionality',
                'atmospheric_conditions': atmospheric_conditions,
                'total_transmittance': total_transmittance,
                'air_mass': air_mass,
                'path_radiance': path_radiance,
                'correction_uncertainty_k': 2.0  # Estimated uncertainty
            })
            
            return corrected_data
            
        except Exception as e:
            self.logger.error(f"Advanced reduced atmospheric correction failed: {e}")
            return await self._apply_basic_atmospheric_correction_emergency_fallback(raw_data, data_source)
    
    async def _apply_basic_atmospheric_correction_emergency_fallback(self, raw_data: Dict[str, Any], 
                                                                    data_source: ThermalDataSource) -> Dict[str, Any]:
        """Emergency fallback atmospheric correction using minimal processing"""
        try:
            corrected_data = raw_data.copy()
            
            zenith_angle = raw_data.get('satellite_zenith_angle', 0.0)
            temperature_k = raw_data.get('temperature_k', 273.15)
            
            # Simple air mass with curvature
            air_mass = 1.0 / np.cos(np.radians(min(zenith_angle, 80))) if zenith_angle < 80 else 5.76
            air_mass *= (1 + 0.0001 * zenith_angle**2)  # Curvature correction
            
            # Advanced empirical transmittance model
            base_transmittance = 0.88 - 0.02 * np.log(air_mass)
            seasonal_factor = 1.0 + 0.05 * np.cos(2 * np.pi * datetime.utcnow().timetuple().tm_yday / 365.25)
            transmittance = base_transmittance * seasonal_factor
            
            # Temperature correction with path radiance
            atmospheric_temp = 240.0 + 10.0 * np.cos(np.radians(abs(raw_data.get('lat', 0))))
            path_correction = 1.0 + 0.03 * (atmospheric_temp / temperature_k - 1.0)
            
            corrected_data['temperature_k'] = (temperature_k / transmittance) * path_correction
            corrected_data['atmospheric_model'] = 'emergency_fallback'
            corrected_data['correction_uncertainty_k'] = 5.0
            
            return corrected_data
            
        except Exception as e:
            self.logger.error(f"Emergency atmospheric correction failed: {e}")
            return raw_data

    async def _apply_basic_geometric_correction_fallback(self, data: Dict[str, Any], 
                                                       data_source: ThermalDataSource) -> Dict[str, Any]:
        """Apply basic geometric correction as fallback"""
        try:
            corrected_data = data.copy()
            
            # Basic parallax correction for terrain relief
            lat = data.get('lat', 0.0)
            lon = data.get('lon', 0.0)
            zenith_angle = data.get('satellite_zenith_angle', 0.0)
            
            # Get basic elevation
            try:
                terrain_params = await self._get_terrain_parameters(lat, lon)
                elevation = terrain_params.get('elevation', 0.0)
            except:
                elevation = 0.0
            
            # Simple parallax displacement calculation
            if zenith_angle > 0 and elevation > 0:
                # Approximate satellite altitude (km)
                satellite_altitude = 700.0  # Typical for most sensors
                
                # Parallax displacement (simplified)
                displacement_m = elevation * np.tan(np.radians(zenith_angle))
                
                # Convert to lat/lon displacement (approximate)
                lat_displacement = displacement_m / 111320.0  # meters per degree latitude
                lon_displacement = displacement_m / (111320.0 * np.cos(np.radians(lat)))
                
                # Apply correction
                corrected_data['lat'] = lat + lat_displacement
                corrected_data['lon'] = lon + lon_displacement
                corrected_data['geometric_correction_applied'] = True
                corrected_data['parallax_displacement_m'] = displacement_m
            
            corrected_data['geometric_model'] = 'basic_parallax_correction'
            
            return corrected_data
            
        except Exception as e:
            self.logger.error(f"Basic geometric correction fallback failed: {e}")
            return data
    
    async def _get_comprehensive_terrain_parameters(self, lat: float, lon: float) -> Dict[str, Any]:
        """Get comprehensive terrain parameters including advanced topographic analysis"""
        try:
            # Query detailed terrain data from database
            cursor = self.db_connections['postgresql'].cursor()
            
            # Get terrain parameters from high-resolution DEM
            cursor.execute("""
                SELECT 
                    elevation_m,
                    slope_degrees,
                    aspect_degrees,
                    curvature,
                    roughness,
                    topographic_wetness_index,
                    terrain_ruggedness_index,
                    geomorphology_class,
                    drainage_density,
                    ST_Distance(location, ST_GeogFromText(%s)) as distance
                FROM terrain_analysis 
                WHERE ST_DWithin(location, ST_GeogFromText(%s), 1000)
                ORDER BY distance ASC
                LIMIT 5;
            """, (f'POINT({lon} {lat})', f'POINT({lon} {lat})'))
            
            terrain_records = cursor.fetchall()
            
            if terrain_records:
                # Use closest terrain data with interpolation if multiple points
                if len(terrain_records) == 1:
                    record = terrain_records[0]
                    return {
                        'elevation': record['elevation_m'] or 0.0,
                        'slope_degrees': record['slope_degrees'] or 0.0,
                        'aspect_degrees': record['aspect_degrees'] or 0.0,
                        'curvature': record['curvature'] or 0.0,
                        'roughness': record['roughness'] or 0.0,
                        'topographic_wetness_index': record['topographic_wetness_index'] or 5.0,
                        'terrain_ruggedness_index': record['terrain_ruggedness_index'] or 0.0,
                        'geomorphology_class': record['geomorphology_class'] or 'unknown',
                        'drainage_density': record['drainage_density'] or 0.0,
                        'data_source': 'high_resolution_dem'
                    }
                else:
                    # Interpolate between multiple points
                    distances = np.array([r['distance'] for r in terrain_records])
                    weights = 1.0 / (distances + 1.0)
                    weights /= np.sum(weights)
                    
                    elevation = np.average([r['elevation_m'] or 0 for r in terrain_records], weights=weights)
                    slope = np.average([r['slope_degrees'] or 0 for r in terrain_records], weights=weights)
                    aspect = np.average([r['aspect_degrees'] or 0 for r in terrain_records], weights=weights)
                    curvature = np.average([r['curvature'] or 0 for r in terrain_records], weights=weights)
                    roughness = np.average([r['roughness'] or 0 for r in terrain_records], weights=weights)
                    
                    return {
                        'elevation': elevation,
                        'slope_degrees': slope,
                        'aspect_degrees': aspect,
                        'curvature': curvature,
                        'roughness': roughness,
                        'topographic_wetness_index': 5.0,
                        'terrain_ruggedness_index': roughness,
                        'geomorphology_class': terrain_records[0]['geomorphology_class'] or 'unknown',
                        'drainage_density': np.average([r['drainage_density'] or 0 for r in terrain_records], weights=weights),
                        'data_source': 'interpolated_high_resolution_dem'
                    }
            
            # Fallback to SRTM or other global DEM
            return await self._get_global_terrain_parameters(lat, lon)
            
        except Exception as e:
            self.logger.error(f"Comprehensive terrain parameter retrieval failed: {e}")
            return await self._get_global_terrain_parameters(lat, lon)
    
    async def _get_global_terrain_parameters(self, lat: float, lon: float) -> Dict[str, Any]:
        """Get terrain parameters from global datasets as fallback"""
        try:
            # Query global terrain database (SRTM, ASTER GDEM, etc.)
            cursor = self.db_connections['postgresql'].cursor()
            
            cursor.execute("""
                SELECT 
                    elevation_m,
                    slope_degrees,
                    aspect_degrees,
                    ST_Distance(location, ST_GeogFromText(%s)) as distance
                FROM global_dem 
                WHERE ST_DWithin(location, ST_GeogFromText(%s), 5000)
                ORDER BY distance ASC
                LIMIT 3;
            """, (f'POINT({lon} {lat})', f'POINT({lon} {lat})'))
            
            global_records = cursor.fetchall()
            
            if global_records:
                # Use distance-weighted interpolation
                distances = np.array([r['distance'] for r in global_records])
                weights = 1.0 / (distances + 100.0)  # Add 100m to avoid division by zero
                weights /= np.sum(weights)
                
                elevation = np.average([r['elevation_m'] or 0 for r in global_records], weights=weights)
                slope = np.average([r['slope_degrees'] or 0 for r in global_records], weights=weights)
                aspect = np.average([r['aspect_degrees'] or 0 for r in global_records], weights=weights)
                
                return {
                    'elevation': elevation,
                    'slope_degrees': slope,
                    'aspect_degrees': aspect,
                    'curvature': 0.0,
                    'roughness': slope * 0.1,  # Rough estimate
                    'topographic_wetness_index': 5.0,
                    'terrain_ruggedness_index': slope * 0.1,
                    'geomorphology_class': 'unknown',
                    'drainage_density': 0.0,
                    'data_source': 'global_dem'
                }
            
            # Final fallback: estimate from geographic location
            return await self._estimate_terrain_from_geography(lat, lon)
            
        except Exception as e:
            self.logger.error(f"Global terrain parameter retrieval failed: {e}")
            return await self._estimate_terrain_from_geography(lat, lon)
    
