    async def _calculate_advanced_air_mass_with_curvature(self, zenith_angle: float, surface_pressure: float) -> float:
        """Calculate advanced air mass with Earth curvature and atmospheric refraction corrections"""
        try:
            zenith_rad = np.radians(zenith_angle)
            
            # Kasten and Young (1989) formula with curvature correction
            if zenith_angle < 80:
                air_mass = 1.0 / (np.cos(zenith_rad) + 0.50572 * (96.07995 - zenith_angle)**(-1.6364))
            else:
                # High zenith angle correction using spherical geometry
                earth_radius = 6371.0  # km
                atmosphere_height = 100.0  # km
                
                cos_zenith = np.cos(zenith_rad)
                sin_zenith = np.sin(zenith_rad)
                
                # Geometric air mass with Earth curvature
                r_ratio = earth_radius / (earth_radius + atmosphere_height)
                air_mass = 1.0 / (cos_zenith + np.sqrt(1 - r_ratio**2 * sin_zenith**2))
            
            # Pressure correction for altitude
            pressure_correction = surface_pressure / 1013.25
            air_mass *= pressure_correction
            
            # Atmospheric refraction correction using Bennett (1982)
            if zenith_angle > 0:
                refraction_correction = 1.0 / (1.0 + 0.0012 * (zenith_angle - 90)**2)
                air_mass *= refraction_correction
            
            return max(1.0, min(40.0, air_mass))
            
        except Exception as e:
            self.logger.error(f"Advanced air mass calculation failed: {e}")
            return 1.0 / np.cos(np.radians(min(zenith_angle, 80)))
    
