    def _get_modis_band31_response(self) -> np.ndarray:
        """Get MODIS Band 31 spectral response function"""
        # Real MODIS Band 31 spectral response (11 μm)
        wavelengths = np.linspace(10.5, 11.5, 100)
        # Gaussian approximation of actual MODIS response
        center = 11.03
        sigma = 0.15
        response = np.exp(-0.5 * ((wavelengths - center) / sigma)**2)
        return np.column_stack([wavelengths, response])
    
