    async def _temperature_to_radiance_planck(self, temperature_k: float, wavelength_um: float) -> float:
        """Convert temperature to radiance using Planck's law"""
        try:
            # Physical constants
            h = 6.62607015e-34  # Planck constant (J⋅s)
            c = 2.99792458e8    # Speed of light (m/s)
            k_b = 1.380649e-23  # Boltzmann constant (J/K)
            
            # Convert wavelength to meters
            wavelength_m = wavelength_um * 1e-6
            
            # Planck's law for spectral radiance (W⋅m⁻²⋅sr⁻¹⋅m⁻¹)
            c1 = 2 * h * c**2
            c2 = h * c / k_b
            
            radiance = c1 / (wavelength_m**5 * (np.exp(c2 / (wavelength_m * temperature_k)) - 1))
            
            # Convert to W⋅m⁻²⋅sr⁻¹⋅μm⁻¹
            radiance_per_um = radiance * 1e-6
            
            return radiance_per_um
            
        except Exception as e:
            self.logger.error(f"Temperature to radiance conversion failed: {e}")
            return 1.0
    
    async def _radiance_to_temperature_planck(self, radiance: float, wavelength_um: float) -> float:
        """Convert radiance to temperature using inverse Planck's law"""
        try:
            # Physical constants
            h = 6.62607015e-34  # Planck constant (J⋅s)
            c = 2.99792458e8    # Speed of light (m/s)
            k_b = 1.380649e-23  # Boltzmann constant (J/K)
            
            # Convert wavelength to meters
            wavelength_m = wavelength_um * 1e-6
            
            # Convert radiance from W⋅m⁻²⋅sr⁻¹⋅μm⁻¹ to W⋅m⁻²⋅sr⁻¹⋅m⁻¹
            radiance_per_m = radiance * 1e6
            
            # Inverse Planck's law
            c1 = 2 * h * c**2
            c2 = h * c / k_b
            
            # Solve for temperature
            if radiance_per_m > 0:
                temperature_k = c2 / (wavelength_m * np.log(c1 / (radiance_per_m * wavelength_m**5) + 1))
            else:
                temperature_k = 273.15  # Default to 0°C
            
            return max(150.0, min(2000.0, temperature_k))  # Realistic bounds
            
        except Exception as e:
            self.logger.error(f"Radiance to temperature conversion failed: {e}")
            return 273.15
    
    async def _calculate_atmospheric_path_radiance_advanced(self, band_data: Dict[str, Any], 
                                                          atmospheric_conditions: Dict[str, Any], 
                                                          air_mass: float) -> float:
        """Calculate atmospheric path radiance using advanced radiative transfer"""
        try:
            wavelength_um = band_data['wavelength_um']
            
            # Get atmospheric temperature profile
            temp_profile = atmospheric_conditions.get('temperature_profile_k', self._get_standard_atmosphere())
            
            # Calculate layer-by-layer path radiance
            total_path_radiance = 0.0
            
            # Standard atmospheric layers (pressure levels in hPa)
            pressure_levels = [1013.25, 850, 700, 500, 300, 200, 100, 50, 30, 10, 5, 1]
            
            for i in range(len(pressure_levels) - 1):
                # Layer properties
                p1, p2 = pressure_levels[i], pressure_levels[i + 1]
                layer_pressure = (p1 + p2) / 2
                
                # Temperature for this layer
                if i < len(temp_profile):
                    layer_temp = temp_profile[i]
                else:
                    # Extrapolate using lapse rate
                    layer_temp = temp_profile[-1] - 0.0065 * (i - len(temp_profile) + 1) * 1000
                
                # Layer optical depth (simplified)
                water_vapor_od = atmospheric_conditions.get('total_precipitable_water', 2.5) * 0.01 * (p1 - p2) / 1013.25
                ozone_od = atmospheric_conditions.get('total_ozone', 0.3) * 0.001 * (p1 - p2) / 1013.25
                aerosol_od = atmospheric_conditions.get('aerosol_optical_depth_550nm', 0.15) * 0.1 * (p1 - p2) / 1013.25
                
                layer_od = water_vapor_od + ozone_od + aerosol_od
                
                # Layer emission (using Planck's law)
                layer_radiance = await self._temperature_to_radiance_planck(layer_temp, wavelength_um)
                
                # Layer contribution to path radiance
                layer_contribution = layer_radiance * (1 - np.exp(-layer_od * air_mass))
                total_path_radiance += layer_contribution
            
            return total_path_radiance
            
        except Exception as e:
            self.logger.error(f"Advanced path radiance calculation failed: {e}")
            # Simplified fallback
            atmospheric_temp = np.mean(atmospheric_conditions.get('temperature_profile_k', [250.0]))
            return await self._temperature_to_radiance_planck(atmospheric_temp, band_data['wavelength_um']) * 0.05
    
    async def _calculate_advanced_emissivity_correction_comprehensive(self, lat: float, lon: float, 
                                                                    temperature_k: float, 
                                                                    data_source: ThermalDataSource,
                                                                    timestamp: datetime) -> Dict[str, Any]:
        """Calculate comprehensive emissivity correction using real surface composition and physics"""
        try:
            # Query real surface composition from geological database
            surface_composition = await self._get_comprehensive_surface_composition(lat, lon)
            
            # Calculate temperature-dependent emissivity using Kirchhoff's law
            base_emissivity = await self._calculate_physics_based_emissivity(
                surface_composition, temperature_k, data_source
            )
            
            # Apply angular dependence using Fresnel equations
            viewing_angle = 0.0  # Assume nadir for now
            angular_correction = await self._calculate_angular_emissivity_correction(
                base_emissivity, viewing_angle, surface_composition
            )
            
            # Apply wavelength dependence
            spectral_bands = self._get_comprehensive_sensor_spectral_bands(data_source)
            wavelength_corrections = {}
            
            for band_name, band_info in spectral_bands.items():
                wavelength_correction = await self._calculate_spectral_emissivity_correction(
                    base_emissivity, band_info['center_wavelength'], surface_composition
                )
                wavelength_corrections[band_name] = wavelength_correction
            
            # Apply temporal variations (seasonal, diurnal)
            temporal_correction = await self._calculate_temporal_emissivity_variation(
                lat, lon, timestamp, surface_composition
            )
            
            return {
                'base_emissivity': base_emissivity,
                'angular_correction': angular_correction,
                'wavelength_corrections': wavelength_corrections,
                'temporal_correction': temporal_correction,
                'surface_composition': surface_composition,
                'correction_uncertainty': 0.02,  # Typical uncertainty
                'method': 'comprehensive_physics_based'
            }
            
        except Exception as e:
            self.logger.error(f"Comprehensive emissivity correction failed: {e}")
            return {
                'base_emissivity': 0.95,
                'angular_correction': 1.0,
                'wavelength_corrections': {'thermal': 1.0},
                'temporal_correction': 1.0,
                'correction_uncertainty': 0.05,
                'method': 'fallback'
            }
    
    def _calculate_julian_day_number_precise(self, timestamp: datetime) -> float:
        """Calculate precise Julian Day Number using astronomical algorithms"""
        try:
            year = timestamp.year
            month = timestamp.month
            day = timestamp.day
            hour = timestamp.hour
            minute = timestamp.minute
            second = timestamp.second + timestamp.microsecond / 1e6
            
            # Convert to decimal day
            decimal_day = day + (hour + minute/60.0 + second/3600.0) / 24.0
            
            # Adjust for January and February
            if month <= 2:
                year -= 1
                month += 12
            
            # Calculate Julian Day Number using Meeus algorithm
            a = int(year / 100)
            b = 2 - a + int(a / 4)
            
            julian_day = int(365.25 * (year + 4716)) + int(30.6001 * (month + 1)) + decimal_day + b - 1524.5
            
            return julian_day
            
        except Exception as e:
            # Fallback to simple calculation
            return 2451545.0 + (timestamp - datetime(2000, 1, 1, 12, 0, 0)).total_seconds() / 86400.0
    
    def _calculate_earth_heliocentric_longitude(self, julian_century: float) -> float:
        """Calculate Earth's heliocentric longitude with high precision"""
        try:
            # VSOP87 series for Earth's longitude (truncated for performance)
            # L0 terms (most significant)
            L0 = [
                [175347046.0, 0.0, 0.0],
                [3341656.0, 4.6692568, 6283.0758500],
                [34894.0, 4.6261, 12566.1517],
                [3497.0, 2.7441, 5753.3849],
                [3418.0, 2.8289, 3.5231],
                [3136.0, 3.6277, 77713.7715],
                [2676.0, 4.4181, 7860.4194],
                [2343.0, 6.1352, 3930.2097],
                [1324.0, 0.7425, 11506.7698],
                [1273.0, 2.0371, 529.6910]
            ]
            
            # L1 terms
            L1 = [
                [628331966747.0, 0.0, 0.0],
                [206059.0, 2.678235, 6283.075850],
                [4303.0, 2.6351, 12566.1517],
                [425.0, 1.590, 3.523],
                [119.0, 5.796, 26.298],
                [109.0, 2.966, 1577.344],
                [93.0, 2.59, 18849.23],
                [72.0, 1.14, 529.69],
                [68.0, 1.87, 398.15],
                [67.0, 4.41, 5507.55]
            ]
            
            # L2 terms
            L2 = [
                [52919.0, 0.0, 0.0],
                [8720.0, 1.0721, 6283.0758],
                [309.0, 0.867, 12566.152],
                [27.0, 0.05, 3.52],
                [16.0, 5.19, 26.30],
                [16.0, 3.68, 155.42],
                [10.0, 0.76, 18849.23],
                [9.0, 2.06, 77713.77],
                [7.0, 0.83, 775.52],
                [5.0, 4.66, 1577.34]
            ]
            
            # Calculate longitude components
            t = julian_century
            
            # L0 component
            l0_sum = 0.0
            for term in L0:
                l0_sum += term[0] * np.cos(term[1] + term[2] * t)
            
            # L1 component
            l1_sum = 0.0
            for term in L1:
                l1_sum += term[0] * np.cos(term[1] + term[2] * t)
            
            # L2 component
            l2_sum = 0.0
            for term in L2:
                l2_sum += term[0] * np.cos(term[1] + term[2] * t)
            
            # Combine components
            longitude_rad = (l0_sum + l1_sum * t + l2_sum * t**2) / 1e8
            longitude_deg = np.degrees(longitude_rad)
            
            # Normalize to [0, 360]
            longitude_deg = longitude_deg % 360.0
            
            return longitude_deg
            
        except Exception as e:
            # Fallback to simplified calculation
            return (280.46646 + julian_century * (36000.76983 + julian_century * 0.0003032)) % 360.0
    
    def _calculate_earth_heliocentric_latitude(self, julian_century: float) -> float:
        """Calculate Earth's heliocentric latitude"""
        try:
            # VSOP87 B1 terms for latitude
            B1 = [
                [280.0, 3.199, 84334.662],
                [102.0, 5.422, 5507.553],
                [80.0, 3.88, 5223.69],
                [44.0, 3.70, 2352.87],
                [32.0, 4.00, 1577.34]
            ]
            
            t = julian_century
            
            # Calculate B1 component
            b1_sum = 0.0
            for term in B1:
                b1_sum += term[0] * np.cos(term[1] + term[2] * t)
            
            # Earth's latitude is very small, dominated by B1 term
            latitude_rad = b1_sum * t / 1e8
            latitude_deg = np.degrees(latitude_rad)
            
            return latitude_deg
            
        except Exception as e:
            return 0.0  # Earth's heliocentric latitude is very small
    
    def _calculate_earth_radius_vector(self, julian_century: float) -> float:
        """Calculate Earth's radius vector (distance from Sun in AU)"""
        try:
            # VSOP87 R0 terms
            R0 = [
                [100013989.0, 0.0, 0.0],
                [1670700.0, 3.0984635, 6283.0758500],
                [13956.0, 3.0552, 12566.1517],
                [3084.0, 5.1985, 77713.7715],
                [1628.0, 1.1739, 5753.3849],
                [1576.0, 2.8469, 7860.4194],
                [925.0, 5.453, 11506.770],
                [542.0, 4.564, 3930.210]
            ]
            
            t = julian_century
            
            # Calculate R0 component
            r0_sum = 0.0
            for term in R0:
                r0_sum += term[0] * np.cos(term[1] + term[2] * t)
            
            # Convert to AU
            radius_vector = r0_sum / 1e8
            
            return radius_vector
            
        except Exception as e:
            return 1.0  # Average Earth-Sun distance
    
    def _calculate_nutation_corrections(self, julian_century: float) -> tuple:
        """Calculate nutation corrections for longitude and obliquity"""
        try:
            # Mean elongation of Moon from Sun
            D = 297.85036 + 445267.111480 * julian_century - 0.0019142 * julian_century**2 + julian_century**3 / 189474.0
            
            # Mean anomaly of Sun
            M = 357.52772 + 35999.050340 * julian_century - 0.0001603 * julian_century**2 - julian_century**3 / 300000.0
            
            # Mean anomaly of Moon
            M_prime = 134.96298 + 477198.867398 * julian_century + 0.0086972 * julian_century**2 + julian_century**3 / 56250.0
            
            # Moon's argument of latitude
            F = 93.27191 + 483202.017538 * julian_century - 0.0036825 * julian_century**2 + julian_century**3 / 327270.0
            
            # Longitude of ascending node of Moon
            Omega = 125.04452 - 1934.136261 * julian_century + 0.0020708 * julian_century**2 + julian_century**3 / 450000.0
            
            # Convert to radians
            D_rad = np.radians(D)
            M_rad = np.radians(M)
            M_prime_rad = np.radians(M_prime)
            F_rad = np.radians(F)
            Omega_rad = np.radians(Omega)
            
            # Principal nutation terms (simplified)
            delta_psi = (-17.20 * np.sin(Omega_rad) - 1.32 * np.sin(2 * (F_rad - D_rad + Omega_rad)) 
                        - 0.23 * np.sin(2 * (F_rad + Omega_rad)) + 0.21 * np.sin(2 * Omega_rad)) / 3600.0
            
            delta_epsilon = (9.20 * np.cos(Omega_rad) + 0.57 * np.cos(2 * (F_rad - D_rad + Omega_rad)) 
                           + 0.10 * np.cos(2 * (F_rad + Omega_rad)) - 0.09 * np.cos(2 * Omega_rad)) / 3600.0
            
            return delta_psi, delta_epsilon
            
        except Exception as e:
            return 0.0, 0.0
    
    def _calculate_aberration_correction(self, earth_radius_vector: float) -> float:
        """Calculate aberration correction"""
        try:
            # Annual aberration constant
            kappa = 20.49552  # arcseconds
            
            # Aberration correction (simplified)
            aberration = -kappa / (3600.0 * earth_radius_vector)
            
            return aberration
            
        except Exception as e:
            return 0.0
    
    def _calculate_mean_obliquity_ecliptic(self, julian_century: float) -> float:
        """Calculate mean obliquity of the ecliptic"""
        try:
            # IAU 2000 formula
            t = julian_century
            
            # Mean obliquity in arcseconds
            epsilon0_arcsec = (84381.448 - 46.8150 * t - 0.00059 * t**2 + 0.001813 * t**3)
            
            # Convert to degrees
            epsilon0_deg = epsilon0_arcsec / 3600.0
            
            return epsilon0_deg
            
        except Exception as e:
            return 23.4393  # Approximate current value
    
    def _calculate_greenwich_mean_sidereal_time(self, julian_day: float, julian_century: float) -> float:
        """Calculate Greenwich Mean Sidereal Time"""
        try:
            # Greenwich Mean Sidereal Time at 0h UT
            gmst0 = 280.46061837 + 360.98564736629 * (julian_day - 2451545.0) + 0.000387933 * julian_century**2 - julian_century**3 / 38710000.0
            
            # Normalize to [0, 360]
            gmst0 = gmst0 % 360.0
            
            return gmst0
            
        except Exception as e:
            return 0.0
    
    def _calculate_atmospheric_refraction_correction(self, elevation_angle: float) -> float:
        """Calculate atmospheric refraction correction"""
        try:
            if elevation_angle < -0.575:
                return 0.0
            
            # Saemundsson's formula for refraction
            if elevation_angle >= 15.0:
                refraction = 0.00452 * 1.02 / np.tan(np.radians(elevation_angle + 10.3 / (elevation_angle + 5.11)))
            elif elevation_angle >= -0.575:
                refraction = 1.02 / (60.0 * np.tan(np.radians(elevation_angle + 10.3 / (elevation_angle + 5.11))))
            else:
                refraction = 0.0
            
            return refraction
            
        except Exception as e:
            return 0.0
    
    def _calculate_solar_zenith_angle_simplified_accurate(self, lat: float, lon: float, timestamp: datetime) -> float:
        """Simplified but accurate solar zenith angle calculation as fallback"""
        try:
            # Julian day calculation
            julian_day = self._calculate_julian_day_number_precise(timestamp)
            n = julian_day - 2451545.0
            
            # Solar mean longitude
            L = (280.460 + 0.9856474 * n) % 360.0
            
            # Solar mean anomaly
            g = np.radians((357.528 + 0.9856003 * n) % 360.0)
            
            # Ecliptic longitude
            lambda_sun = np.radians(L + 1.915 * np.sin(g) + 0.020 * np.sin(2 * g))
            
            # Obliquity of ecliptic
            epsilon = np.radians(23.439 - 0.0000004 * n)
            
            # Right ascension and declination
            alpha = np.arctan2(np.cos(epsilon) * np.sin(lambda_sun), np.cos(lambda_sun))
            delta = np.arcsin(np.sin(epsilon) * np.sin(lambda_sun))
            
            # Greenwich Mean Sidereal Time
            gmst = (18.697374558 + 24.06570982441908 * n) % 24.0
            
            # Local hour angle
            hour_angle = np.radians(15.0 * (gmst - lon / 15.0) - np.degrees(alpha))
            
            # Solar zenith angle
            zenith = np.arccos(np.sin(np.radians(lat)) * np.sin(delta) + 
                              np.cos(np.radians(lat)) * np.cos(delta) * np.cos(hour_angle))
            
            return np.degrees(zenith)
            
        except Exception as e:
            return 45.0
    
    async def _estimate_crustal_age_from_global_models(self, lat: float, lon: float) -> float:
        """Estimate crustal age using global geological models"""
        try:
            # Advanced global crustal age estimation using multiple geological indicators
            
            # Method 1: Magnetic anomaly patterns (for oceanic crust)
            magnetic_age = await self._estimate_age_from_magnetic_anomalies(lat, lon)
            
            # Method 2: Geological province classification
            geological_age = await self._estimate_age_from_geological_provinces(lat, lon)
            
            # Method 3: Tectonic setting analysis
            tectonic_age = await self._estimate_age_from_tectonic_setting(lat, lon)
            
            # Method 4: Radiometric age compilation
            radiometric_age = await self._estimate_age_from_radiometric_data(lat, lon)
            
            # Weighted combination based on reliability
            ages = []
            weights = []
            
            if magnetic_age > 0:
                ages.append(magnetic_age)
                weights.append(0.4)  # High weight for oceanic areas
            
            if geological_age > 0:
                ages.append(geological_age)
                weights.append(0.3)  # Moderate weight
            
            if tectonic_age > 0:
                ages.append(tectonic_age)
                weights.append(0.2)  # Lower weight
            
            if radiometric_age > 0:
                ages.append(radiometric_age)
                weights.append(0.5)  # Highest weight when available
            
            if ages:
                # Normalize weights
                total_weight = sum(weights)
                normalized_weights = [w / total_weight for w in weights]
                
                # Calculate weighted average
                estimated_age = sum(age * weight for age, weight in zip(ages, normalized_weights))
                return max(0.1, min(4000.0, estimated_age))  # Realistic bounds
            else:
                # Fallback based on latitude (continental vs oceanic patterns)
                return await self._estimate_age_from_latitude_patterns(lat, lon)
                
        except Exception as e:
            self.logger.error(f"Global crustal age estimation failed: {e}")
            return 100.0  # Default intermediate age
    
    async def _estimate_age_from_magnetic_anomalies(self, lat: float, lon: float) -> float:
        """Estimate crustal age from magnetic anomaly patterns"""
        try:
            # Query magnetic anomaly data from database
            cursor = self.db_connections['postgresql'].cursor()
            
            cursor.execute("""
                SELECT 
                    properties->>'magnetic_anomaly' as anomaly_id,
                    properties->>'estimated_age_ma' as age_ma,
                    ST_Distance(location, ST_GeogFromText(%s)) as distance
                FROM geological_structures 
                WHERE ST_DWithin(location, ST_GeogFromText(%s), 200000)
                AND properties ? 'magnetic_anomaly'
                AND properties ? 'estimated_age_ma'
                ORDER BY distance ASC
                LIMIT 5;
            """, (f'POINT({lon} {lat})', f'POINT({lon} {lat})'))
            
            magnetic_records = cursor.fetchall()
            
            if magnetic_records:
                # Use distance-weighted average of magnetic ages
                total_weight = 0
                weighted_age = 0
                
                for record in magnetic_records:
                    try:
                        age_ma = float(record['age_ma'])
                        distance_km = record['distance'] / 1000.0
                        weight = 1.0 / (1.0 + distance_km / 100.0)
                        
                        weighted_age += age_ma * weight
                        total_weight += weight
                    except (ValueError, TypeError):
                        continue
                
                if total_weight > 0:
                    return weighted_age / total_weight
            
            # Fallback: estimate from distance to nearest spreading center
            spreading_center_distance = await self._calculate_distance_to_spreading_center(lat, lon)
            if spreading_center_distance < 2000:  # Within 2000 km of spreading center
                # Approximate age based on spreading rate (2-10 cm/year)
                average_spreading_rate = 5.0  # cm/year
                estimated_age = (spreading_center_distance * 1000) / (average_spreading_rate * 10)  # Convert to Ma
                return max(0.1, min(200.0, estimated_age))
            
            return 0.0  # No magnetic age data available
            
        except Exception as e:
            return 0.0
    
    async def _estimate_age_from_geological_provinces(self, lat: float, lon: float) -> float:
        """Estimate age from geological province classification"""
        try:
            # Major geological provinces with typical ages
            geological_provinces = {
                # Archean cratons (2.5-4.0 Ga)
                'superior_craton': {'bounds': (45, 55, -95, -75), 'age_range': (2500, 3800)},
                'slave_craton': {'bounds': (60, 67, -115, -105), 'age_range': (2500, 4000)},
                'kaapvaal_craton': {'bounds': (-30, -22, 24, 32), 'age_range': (2700, 3600)},
                'pilbara_craton': {'bounds': (-23, -19, 116, 122), 'age_range': (2800, 3500)},
                
                # Proterozoic provinces (0.5-2.5 Ga)
                'trans_hudson_orogen': {'bounds': (55, 65, -105, -85), 'age_range': (1800, 2000)},
                'grenville_province': {'bounds': (40, 50, -85, -65), 'age_range': (1000, 1300)},
                'capricorn_orogen': {'bounds': (-24, -20, 116, 122), 'age_range': (1600, 2000)},
                
                # Phanerozoic provinces (0-540 Ma)
                'appalachian_orogen': {'bounds': (30, 50, -85, -65), 'age_range': (250, 480)},
                'cordilleran_orogen': {'bounds': (30, 60, -125, -105), 'age_range': (50, 200)},
                'alpine_orogen': {'bounds': (40, 50, 5, 15), 'age_range': (20, 100)},
                'himalayan_orogen': {'bounds': (25, 40, 70, 95), 'age_range': (10, 50)},
                
                # Oceanic provinces
                'pacific_plate': {'bounds': (-60, 60, -180, -120), 'age_range': (0, 180)},
                'atlantic_basin': {'bounds': (-60, 70, -70, 20), 'age_range': (0, 200)},
                'indian_ocean': {'bounds': (-60, 30, 20, 120), 'age_range': (0, 150)}
            }
            
            # Check which province the location falls into
            for province_name, province_data in geological_provinces.items():
                bounds = province_data['bounds']
                if (bounds[0] <= lat <= bounds[1] and bounds[2] <= lon <= bounds[3]):
                    age_range = province_data['age_range']
                    # Return middle of age range
                    return (age_range[0] + age_range[1]) / 2.0
            
            return 0.0  # No province match
            
        except Exception as e:
            return 0.0
    
    async def _calculate_volcanic_heat_enhancement(self, lat: float, lon: float) -> float:
        """Calculate volcanic heat enhancement factor"""
        try:
            # Query recent volcanic activity
            cursor = self.db_connections['postgresql'].cursor()
            
            cursor.execute("""
                SELECT 
                    COUNT(*) as volcano_count,
                    AVG(CASE WHEN properties->>'last_eruption_year' IS NOT NULL 
                        THEN EXTRACT(YEAR FROM NOW()) - (properties->>'last_eruption_year')::int 
                        ELSE NULL END) as avg_years_since_eruption
                FROM volcanoes 
                WHERE ST_DWithin(location, ST_GeogFromText(%s), 50000)
                AND (properties->>'last_eruption_year')::int > 1800;
            """, (f'POINT({lon} {lat})',))
            
            volcanic_data = cursor.fetchone()
            
            if volcanic_data and volcanic_data['volcano_count'] > 0:
                volcano_count = volcanic_data['volcano_count']
                years_since = volcanic_data['avg_years_since_eruption'] or 100
                
                # Enhancement based on volcano density and recency
                density_factor = min(1.0, volcano_count / 5.0)  # Up to 5 volcanoes
                recency_factor = max(0.1, 1.0 - years_since / 200.0)  # Decay over 200 years
                
                enhancement = density_factor * recency_factor * 0.5  # Up to 50% enhancement
                return enhancement
            
            return 0.0
            
        except Exception as e:
            return 0.0
    
    async def _calculate_hydrothermal_heat_factor(self, lat: float, lon: float) -> float:
        """Calculate hydrothermal circulation heat factor"""
        try:
            # Hydrothermal circulation is common in young oceanic crust
            # Check for indicators of hydrothermal activity
            
            # Method 1: Check for known hydrothermal fields
            cursor = self.db_connections['postgresql'].cursor()
            
            cursor.execute("""
                SELECT COUNT(*) as hydrothermal_count
                FROM geological_structures 
                WHERE ST_DWithin(location, ST_GeogFromText(%s), 100000)
                AND (structure_type ILIKE '%hydrothermal%' OR 
                     lithology ILIKE '%hydrothermal%' OR
                     properties ? 'hydrothermal_activity');
            """, (f'POINT({lon} {lat})',))
            
            hydrothermal_result = cursor.fetchone()
            
            if hydrothermal_result and hydrothermal_result['hydrothermal_count'] > 0:
                return 1.3  # 30% enhancement for hydrothermal areas
            
            # Method 2: Estimate based on seafloor age and depth
            seafloor_depth = await self._estimate_seafloor_depth(lat, lon)
            
            if 2000 <= seafloor_depth <= 4000:  # Typical mid-ocean ridge depths
                return 1.2  # 20% enhancement
            elif seafloor_depth > 4000:  # Deep ocean basins
                return 0.9  # 10% reduction due to sediment blanketing
            
            return 1.0  # No hydrothermal effect
            
        except Exception as e:
            return 1.0
    
    async def _calculate_sediment_blanketing_factor(self, lat: float, lon: float) -> float:
        """Calculate sediment blanketing effect on heat flow"""
        try:
            # Query sediment thickness data
            cursor = self.db_connections['postgresql'].cursor()
            
            cursor.execute("""
                SELECT 
                    AVG(CASE WHEN properties->>'sediment_thickness_m' IS NOT NULL 
                        THEN (properties->>'sediment_thickness_m')::float 
                        ELSE NULL END) as avg_sediment_thickness
                FROM geological_structures 
                WHERE ST_DWithin(location, ST_GeogFromText(%s), 50000)
                AND properties ? 'sediment_thickness_m';
            """, (f'POINT({lon} {lat})',))
            
            sediment_result = cursor.fetchone()
            
            if sediment_result and sediment_result['avg_sediment_thickness']:
                thickness_m = sediment_result['avg_sediment_thickness']
                
                # Sediment blanketing reduces surface heat flow
                # Exponential decay with thickness
                blanketing_factor = np.exp(-thickness_m / 1000.0)  # 1 km decay scale
                return max(0.5, blanketing_factor)  # Minimum 50% of original heat flow
            
            # Estimate sediment thickness from bathymetry and location
            estimated_thickness = await self._estimate_sediment_thickness(lat, lon)
            blanketing_factor = np.exp(-estimated_thickness / 1000.0)
            
            return max(0.7, blanketing_factor)
            
        except Exception as e:
            return 1.0
    
    async def _calculate_radiogenic_heat_factor(self, lat: float, lon: float, age_ma: float) -> float:
        """Calculate radiogenic heat production factor"""
        try:
            # Query crustal composition for radiogenic elements
            cursor = self.db_connections['postgresql'].cursor()
            
            cursor.execute("""
                SELECT 
                    lithology,
                    mineral_composition,
                    properties->>'uranium_ppm' as uranium,
                    properties->>'thorium_ppm' as thorium,
                    properties->>'potassium_percent' as potassium
                FROM geological_structures 
                WHERE ST_DWithin(location, ST_GeogFromText(%s), 25000)
                AND (properties ? 'uranium_ppm' OR properties ? 'thorium_ppm' OR properties ? 'potassium_percent')
                ORDER BY ST_Distance(location, ST_GeogFromText(%s)) ASC
                LIMIT 5;
            """, (f'POINT({lon} {lat})', f'POINT({lon} {lat})'))
            
            composition_records = cursor.fetchall()
            
            if composition_records:
                # Calculate radiogenic heat production
                total_heat_production = 0.0
                valid_records = 0
                
                for record in composition_records:
                    try:
                        uranium_ppm = float(record['uranium']) if record['uranium'] else 2.0  # Average crustal U
                        thorium_ppm = float(record['thorium']) if record['thorium'] else 8.0  # Average crustal Th
                        potassium_percent = float(record['potassium']) if record['potassium'] else 2.0  # Average crustal K
                        
                        # Heat production calculation (μW/m³)
                        # Based on Rybach (1988) formula
                        heat_production = (0.0952 * uranium_ppm + 0.0256 * thorium_ppm + 
                                         0.0348 * potassium_percent * 10000)  # Convert K% to ppm
                        
                        total_heat_production += heat_production
                        valid_records += 1
                        
                    except (ValueError, TypeError):
                        continue
                
                if valid_records > 0:
                    avg_heat_production = total_heat_production / valid_records
                    
                    # Normalize to typical continental crust (1.5 μW/m³)
                    radiogenic_factor = avg_heat_production / 1.5
                    
                    # Apply age-dependent decay
                    # Radiogenic heat decreases with age due to radioactive decay
                    decay_factor = np.exp(-age_ma / 1000.0)  # 1 Ga decay scale
                    
                    return radiogenic_factor * decay_factor
            
            # Fallback based on lithology
            lithology_heat_factors = {
                'granite': 0.4,
                'granodiorite': 0.3,
                'rhyolite': 0.35,
                'shale': 0.2,
                'sandstone': 0.1,
                'basalt': 0.05,
                'gabbro': 0.03,
                'peridotite': 0.01
            }
            
            # Get dominant lithology
            dominant_lithology = await self._get_dominant_lithology(lat, lon)
            base_factor = lithology_heat_factors.get(dominant_lithology.lower(), 0.15)
            
            # Apply age decay
            decay_factor = np.exp(-age_ma / 1000.0)
            
            return base_factor * decay_factor
            
        except Exception as e:
            return 0.1  # Default low radiogenic heat
    
    async def _calculate_crustal_age_factor_simplified_improved(self, lat: float, lon: float) -> float:
        """Simplified but improved crustal age factor calculation"""
        try:
            # Improved classification based on global tectonic patterns
            
            # Very young crust (< 10 Ma): spreading centers and volcanic arcs
            if await self._is_near_spreading_center_improved(lat, lon):
                return 2.0
            elif await self._is_volcanic_arc_improved(lat, lon):
                return 1.8
            
            # Young crust (10-100 Ma): young ocean basins and active margins
            elif await self._is_young_ocean_basin(lat, lon):
                return 1.4
            elif await self._is_active_continental_margin(lat, lon):
                return 1.3
            
            # Intermediate age crust (100-1000 Ma): stable continental regions
            elif await self._is_stable_continental_region(lat, lon):
                return 1.1
            
            # Old crust (> 1000 Ma): cratons and shields
            elif await self._is_cratonic_shield_region(lat, lon):
                return 0.8
            
            # Default intermediate age
            else:
                return 1.0
                
        except Exception as e:
            return 1.0